// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// accumulator_cell_v4c.v — points.md #720: the "c" (carrier) variant
// of accumulator_cell_v4.v. Same real reasoning as the other _v4c
// files' own headers -- the carrier's whole design concept is to hold
// common functionality centrally, and this core's own internal
// 3-addon chain duplicates exactly what the carrier itself now
// provides once, shared. accumulator_cell_v4.v itself is UNCHANGED,
// still the real, proven, standalone core.
//
// Real, honest scope of this file's own changes from v4:
//   1. The internal addon chain is REMOVED entirely -- data_out_n/s/
//      e/w now come directly from out_buffer (the real offered
//      snapshot; the internal `accumulator` register itself was NEVER
//      touched by the addon chain even in v4, so this change is
//      purely about what feeds data_out, nothing about the real
//      running-total semantics).
//   2. addon_config (20 bits) is removed from cfg_data's own field
//      map, the register, and PROG_ID_ADDON_CONFIG. cfg_data KEEPS
//      its original 64-bit width; PROG_ID_COMPLETE stays at 3'd7,
//      addon_config's own old slot (3'd6) is simply unused now.
//   3. Same real config-off-shell reasoning as every other _v4c file:
//      all real config fields STAY registers; the real fix lives at
//      the carrier's own shell level.
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   inc_dir           — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  dec_dir           — one-hot(s), N/S/E/W real + 2 reserved
//   [17:12] downstream_mask   — one-hot(s), N/S/E/W real + 2 reserved
//   [25:18] step_amount       — unsigned magnitude per matching arrival
//   [26]    pulse_mode        — 0=static/continuous, 1=reset-after-fire
//   [42:27] threshold         — pulse_mode only
//   [63:43] reserved          — 21 bits (addon_config's own old home,
//                               now genuinely free, plus the original
//                               1 bit of headroom)

`default_nettype none
`timescale 1ns / 1ps

module accumulator_cell_v4c #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: real, targeted programming channel, same real
    // shape as #618-#620's own. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         ready_out,
    output wire         status_negative
);

    reg [5:0]  inc_dir         = 6'h0;
    reg [5:0]  dec_dir         = 6'h0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [7:0]  step_amount     = 8'h00;
    reg        pulse_mode      = 1'b0;
    reg [15:0] threshold       = 16'h0000;

    reg signed [WIDTH-1:0] accumulator = 0;
    reg signed [WIDTH-1:0] out_buffer  = 0;
    reg data_valid = 1'b0;
    reg pulse_pending = 1'b0;
    reg [3:0] pending_ack = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as #618-#620's own.
    reg armed = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ── Real, unchanged from v1: independent inc/dec capture, only
    // the low 4 bits of the now-6-bit inc_dir/dec_dir are ever wired
    // to a real physical port here (bits [5:4] real, reserved
    // headroom, matching nano's own convention). Real, necessary
    // extension: also gated on effective_armed/!program_in — an
    // inactive or mid-reprogram cell must not silently keep
    // incrementing its own internal total in the background. ──
    wire sel_inc_n = arrived_n && inc_dir[0];
    wire sel_inc_s = arrived_s && inc_dir[1];
    wire sel_inc_e = arrived_e && inc_dir[2];
    wire sel_inc_w = arrived_w && inc_dir[3];
    wire capture_inc = (sel_inc_n | sel_inc_s | sel_inc_e | sel_inc_w) &&
                       !effective_freeze && effective_armed && !program_in;

    wire sel_dec_n = arrived_n && dec_dir[0];
    wire sel_dec_s = arrived_s && dec_dir[1];
    wire sel_dec_e = arrived_e && dec_dir[2];
    wire sel_dec_w = arrived_w && dec_dir[3];
    wire capture_dec = (sel_dec_n | sel_dec_s | sel_dec_e | sel_dec_w) &&
                       !effective_freeze && effective_armed && !program_in;

    assign ack_out_n = (sel_inc_n || sel_dec_n) && !effective_freeze && effective_armed && !program_in;
    assign ack_out_s = (sel_inc_s || sel_dec_s) && !effective_freeze && effective_armed && !program_in;
    assign ack_out_e = (sel_inc_e || sel_dec_e) && !effective_freeze && effective_armed && !program_in;
    assign ack_out_w = (sel_inc_w || sel_dec_w) && !effective_freeze && effective_armed && !program_in;

    wire signed [WIDTH-1:0] step_ext = {{(WIDTH-8){1'b0}}, step_amount};
    wire signed [WIDTH-1:0] delta = (capture_inc && !capture_dec) ?  step_ext :
                                     (capture_dec && !capture_inc) ? -step_ext :
                                                                      {WIDTH{1'b0}};
    wire signed [WIDTH-1:0] next_accumulator = accumulator + delta;

    wire signed [WIDTH-1:0] threshold_ext  = {{(WIDTH-16){1'b0}}, threshold};
    wire signed [WIDTH-1:0] abs_next_acc   = next_accumulator[WIDTH-1] ? -next_accumulator : next_accumulator;
    wire threshold_hit = pulse_mode && (capture_inc || capture_dec) &&
                         (threshold != 16'h0000) && (abs_next_acc >= threshold_ext);

    wire want_to_offer = (pulse_mode ? pulse_pending : data_valid) && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #720: NO addon chain here at all — the carrier
    // already provides one, shared across whichever core is active.
    // data_out_n/s/e/w are the real offered snapshot, directly (the
    // internal accumulator itself is still never touched here, same
    // as v4). ──
    assign data_out_n = out_buffer[31:0];
    assign data_out_s = out_buffer[31:0];
    assign data_out_e = out_buffer[31:0];
    assign data_out_w = out_buffer[31:0];

    assign status_negative = out_buffer[WIDTH-1];
    // Real, honest gating: an inactive/disarmed cell is never ready --
    // same real convention as #618-#620's own.
    assign ready_out = effective_armed && !effective_freeze;

    // ── points.md #617: real, targeted programming channel — same
    // real priority-select shape as #618-#620's own. Real, notable:
    // threshold (16 bits) fits in ONE real targeted write here, no
    // split needed (a third, different real answer to the same
    // question #619/#620 each answered differently). ──
    localparam [2:0] PROG_ID_INC_DIR         = 3'd0;
    localparam [2:0] PROG_ID_DEC_DIR         = 3'd1;
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd2;
    localparam [2:0] PROG_ID_STEP_AMOUNT     = 3'd3;
    localparam [2:0] PROG_ID_PULSE_MODE      = 3'd4;
    localparam [2:0] PROG_ID_THRESHOLD       = 3'd5;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            accumulator     <= 0;
            out_buffer      <= 0;
            data_valid      <= 1'b0;
            pulse_pending   <= 1'b0;
            pending_ack     <= 4'h0;
            inc_dir         <= 6'h0;
            dec_dir         <= 6'h0;
            downstream_mask <= 6'h0;
            step_amount     <= 8'h00;
            pulse_mode      <= 1'b0;
            threshold       <= 16'h0000;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            inc_dir         <= cfg_data[5:0];
            dec_dir         <= cfg_data[11:6];
            downstream_mask <= cfg_data[17:12];
            step_amount     <= cfg_data[25:18];
            pulse_mode      <= cfg_data[26];
            threshold       <= cfg_data[42:27];
            accumulator     <= 0;
            out_buffer      <= 0;
            data_valid      <= 1'b1;
            pulse_pending   <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_INC_DIR:         inc_dir         <= prog_word[5:0];
                PROG_ID_DEC_DIR:         dec_dir         <= prog_word[5:0];
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_STEP_AMOUNT:     step_amount     <= prog_word[7:0];
                PROG_ID_PULSE_MODE:      pulse_mode      <= prog_word[0];
                PROG_ID_THRESHOLD:       threshold       <= prog_word[15:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_inc || capture_dec) begin
                accumulator <= (pulse_mode && threshold_hit) ? {WIDTH{1'b0}} : next_accumulator;
            end

            if (pulse_mode) begin
                if (threshold_hit) begin
                    out_buffer    <= next_accumulator;
                    pulse_pending <= 1'b1;
                end else if ((pending_ack != 4'h0) && (next_pending_ack == 4'h0)) begin
                    pulse_pending <= 1'b0;
                end
            end else begin
                if (pending_ack == 4'h0) begin
                    out_buffer <= next_accumulator;
                end
            end

            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// accumulator_cell_v4s.v -- stripped version of accumulator_cell_v4c.v's real
// function. One real wrinkle, worth stating plainly: the original distinguishes
// "increment" from "decrement" by WHICH cardinal direction an arrival came from
// (inc_dir/dec_dir masks), not by any value the arrival carries -- the incoming
// data_in value is never even used for inc/dec; the step size comes entirely from
// a fixed, configured step_amount. Stripped to fixed ports, that becomes two
// dedicated one-bit EVENT pulses (inc_pulse, dec_pulse) instead of two 32-bit data
// operands -- the same "one dedicated wire per real role the function needs"
// principle as adder_cell_v4s's in_a/in_b, just applied to events instead of data.
//
// Same mechanical strip otherwise: no addon chain, no downstream mask/ack, fixed
// latency, boot-load config only. See sub/README.md / adder_cell_v4s.v.
//
// pulse_mode is a REAL function distinction (not cardinality machinery) and is
// kept faithfully: 0 = continuous (data_out always mirrors the running total;
// valid_out fires whenever a real inc/dec event happens), 1 = pulse (the running
// total resets to zero and fires exactly once, only when its magnitude crosses
// the configured threshold).
//
// cfg_data field map:
//   [7:0]   step_amount -- unsigned magnitude applied per inc/dec pulse
//   [8]     pulse_mode  -- 0=continuous, 1=reset-after-threshold-hit
//   [24:9]  threshold   -- pulse_mode only, unsigned magnitude to cross
`default_nettype none
`timescale 1ns / 1ps

module accumulator_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,

    input  wire         inc_pulse,
    input  wire         dec_pulse,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg [7:0]  step_amount = 8'h0;
    reg        pulse_mode  = 1'b0;
    reg [15:0] threshold   = 16'h0;
    reg        armed       = 1'b0;

    reg signed [WIDTH-1:0] accumulator = 0;
    reg signed [WIDTH-1:0] out_buffer  = 0;
    reg                    valid_out_r = 1'b0;

    // ── The real accumulate logic -- unchanged semantics from v4c ───────
    wire signed [WIDTH-1:0] step_ext = {{(WIDTH-8){1'b0}}, step_amount};
    wire signed [WIDTH-1:0] delta = (inc_pulse && !dec_pulse) ?  step_ext :
                                     (dec_pulse && !inc_pulse) ? -step_ext :
                                                                  {WIDTH{1'b0}};
    wire signed [WIDTH-1:0] next_accumulator = accumulator + delta;
    wire signed [WIDTH-1:0] threshold_ext = {{(WIDTH-16){1'b0}}, threshold};
    wire signed [WIDTH-1:0] abs_next_acc  = next_accumulator[WIDTH-1] ? -next_accumulator : next_accumulator;
    wire threshold_hit = pulse_mode && (inc_pulse || dec_pulse) &&
                         (threshold != 16'h0) && (abs_next_acc >= threshold_ext);

    assign data_out  = out_buffer[31:0];
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            step_amount  <= 8'h0;
            pulse_mode   <= 1'b0;
            threshold    <= 16'h0;
            armed        <= 1'b0;
            accumulator  <= 0;
            out_buffer   <= 0;
            valid_out_r  <= 1'b0;
        end else if (cfg_valid) begin
            step_amount  <= cfg_data[7:0];
            pulse_mode   <= cfg_data[8];
            threshold    <= cfg_data[24:9];
            armed        <= 1'b1;
            accumulator  <= 0;
            out_buffer   <= 0;
            valid_out_r  <= 1'b0;
        end else begin
            if (inc_pulse || dec_pulse) begin
                accumulator <= (pulse_mode && threshold_hit) ? {WIDTH{1'b0}} : next_accumulator;
            end

            if (pulse_mode) begin
                if (threshold_hit) out_buffer <= next_accumulator;
                // else: hold the last snapshot -- pulse mode only ever
                // presents a fresh value at the moment it actually fires.
            end else begin
                out_buffer <= next_accumulator;   // continuous: always mirrors the running total
            end

            valid_out_r <= armed && (pulse_mode ? threshold_hit : (inc_pulse || dec_pulse));
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// accumulator_cell_v4sa.v -- points.md #911: the "Flex-Sub" shape (ack+freeze
// per #906, real WIDTH parameter per #909/#910) applied to accumulator, the
// second cell in the family with genuine per-cycle arithmetic, continuing the
// ALU story #908-#910 built. Same real wrinkle as accumulator_cell_v4s.v: the
// original distinguishes increment from decrement by WHICH cardinal direction
// an arrival came from, not by data content -- two dedicated one-bit event
// pulses (inc_pulse/dec_pulse), not two data operands.
//
// A real, pre-existing bug fixed here, not inherited silently: accumulator_cell_
// v4s.v already had a WIDTH parameter internally, but its data_out PORT stayed
// hardcoded [31:0] regardless -- the external interface never actually reflected
// a narrower width correctly. Fixed here: data_out is genuinely [WIDTH-1:0].
//
// ack/freeze: identical shape and reasoning to adder_cell_v4sa.v -- standard
// ready/valid (valid_out stays high until ack_in, not a one-shot pulse),
// freeze_in global and gating the entire update including cfg_valid's own
// effect. See adder_cell_v4sa.v's own header for the full "why this is not a
// retreat from physics, not control" reasoning -- unchanged here.
//
// pulse_mode is a real function distinction (not cardinality machinery),
// unchanged from accumulator_cell_v4s.v: 0 = continuous (every real inc/dec
// is its own offer, pending/ack-gated like any other v4sa cell), 1 = pulse
// (the running total resets to zero and offers exactly once, only when its
// magnitude crosses the configured threshold).
//
// cfg_data field map, unchanged from accumulator_cell_v4s.v:
//   [7:0]   step_amount -- unsigned magnitude applied per inc/dec pulse
//   [8]     pulse_mode  -- 0=continuous, 1=reset-after-threshold-hit
//   [24:9]  threshold   -- pulse_mode only, unsigned magnitude to cross
`default_nettype none
`timescale 1ns / 1ps

module accumulator_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,

    input  wire         inc_pulse,
    input  wire         dec_pulse,
    output wire         ack_out,      // backward, to whoever drives inc_pulse/dec_pulse

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in       // backward, from the one fixed downstream receiver
);

    reg [7:0]  step_amount = 8'h0;
    reg        pulse_mode  = 1'b0;
    reg [15:0] threshold   = 16'h0;
    reg        armed       = 1'b0;
    reg        pending     = 1'b0;   // holding a real, not-yet-consumed offer

    reg signed [WIDTH-1:0] accumulator = 0;
    reg signed [WIDTH-1:0] out_buffer  = 0;

    // ── The real accumulate logic -- unchanged semantics from v4c/v4s ───
    // #973: no replication with a (WIDTH-8)/(WIDTH-16) count any more -- it went NEGATIVE below 16 bits and the cell did not elaborate. The 8-bit step is assigned straight
    // to a WIDTH-bit wire (zero-extended when wider, cut to the low WIDTH bits when narrower: a step is a count modulo 2^WIDTH like the total itself), and the threshold is
    // compared with |total| in a space wide enough for both (CW bits), so a 16-bit threshold is NEVER cut down: one larger than the data can reach simply never fires.
    wire signed [WIDTH-1:0] step_ext = step_amount;
    wire signed [WIDTH-1:0] delta = (inc_pulse && !dec_pulse) ?  step_ext :
                                     (dec_pulse && !inc_pulse) ? -step_ext :
                                                                  {WIDTH{1'b0}};
    wire signed [WIDTH-1:0] next_accumulator = accumulator + delta;
    // |total| >= threshold. At WIDTH >= 16 exactly the original form (same logic, same cost: the 16-bit threshold zero-extends to the data width). Below 16 bits that form cannot be
    // written (the threshold is wider than the data), so |total| and the threshold are compared in a 17-bit space: no overflow, nothing cut down.
    wire threshold_ge;
    generate
        if (WIDTH >= 16) begin : TH_NORMAL
            wire signed [WIDTH-1:0] threshold_ext = {{(WIDTH-16){1'b0}}, threshold};
            wire signed [WIDTH-1:0] abs_next_acc  = next_accumulator[WIDTH-1] ? -next_accumulator : next_accumulator;
            assign threshold_ge = (abs_next_acc >= threshold_ext);
        end else begin : TH_NARROW
            wire signed [16:0] next_cw      = next_accumulator;           // sign-extended
            wire signed [16:0] abs_next_acc = next_cw[16] ? -next_cw : next_cw;
            wire signed [16:0] threshold_ext = {1'b0, threshold};
            assign threshold_ge = (abs_next_acc >= threshold_ext);
        end
    endgenerate
    wire threshold_hit = pulse_mode && (inc_pulse || dec_pulse) &&
                         (threshold != 16'h0) && threshold_ge;

    // A real event happened this cycle, in the sense that matters for
    // offering a new value: continuous mode offers on every real inc/dec;
    // pulse mode offers only when the threshold is actually crossed.
    wire real_event = pulse_mode ? threshold_hit : (inc_pulse || dec_pulse);

    assign data_out  = out_buffer;
    assign valid_out = pending;
    assign ack_out   = armed && !pending && !freeze_in;

    always @(posedge clk) begin
        if (rst) begin
            step_amount  <= 8'h0;
            pulse_mode   <= 1'b0;
            threshold    <= 16'h0;
            armed        <= 1'b0;
            pending      <= 1'b0;
            accumulator  <= 0;
            out_buffer   <= 0;
        end else if (cfg_valid) begin
            step_amount  <= cfg_data[7:0];
            pulse_mode   <= cfg_data[8];
            threshold    <= cfg_data[24:9];
            armed        <= 1'b1;
            pending      <= 1'b0;
            accumulator  <= 0;
            out_buffer   <= 0;
        end else if (!freeze_in) begin
            // The running total itself updates on every real inc/dec,
            // REGARDLESS of pending/ack -- an accumulator keeps counting even
            // while its last offer is still waiting to be taken, same as the
            // original v4c/v4s semantics. Only the OFFER (pending/out_buffer)
            // is ack-gated.
            if (inc_pulse || dec_pulse) begin
                accumulator <= (pulse_mode && threshold_hit) ? {WIDTH{1'b0}} : next_accumulator;
            end

            if (pending) begin
                if (ack_in) pending <= 1'b0;
            end else if (real_event) begin
                out_buffer <= next_accumulator;
                pending    <= 1'b1;
            end
        end
    end

endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// adder_cell_v4.v — points.md #617/#618: the FIRST real "unified
// carrier" core. Real, proven core logic CLONED from adder_cell_v1.v
// unchanged (the two-stage A/B capture, the real adder_v1.v carry
// chain, subtract_mode) -- everything ADDED here is real SHELL
// richness, per Alan's own precise 5-point breakdown (#617):
//
//   1. programming/#: a real, working program_in/PROG_ID targeted,
//      staged reconfiguration channel -- FAITHFULLY PORTED from
//      unicell_stripped_v1.v's own real protocol (#123/#140), not
//      reinvented, remapped onto this cell's own real 3 fields
//      (downstream_mask/upstream_mask/subtract_mode) instead of
//      nano's 7.
//   2. shift/nibble_mask/lane: the real, ALREADY-BUILT addon chain
//      (#303-#312), wired here exactly as unicell_super_v3.v already
//      does it -- nibble_mask -> shift/lane -> invert, same
//      addon_config bit layout, reused verbatim, not reimplemented.
//   3. 6-way cardinality: downstream_mask/upstream_mask widened to
//      6 bits (matching nano's own real routing_mask/cardinal_edge
//      width) -- REAL FIELD-WIDTH HEADROOM ONLY. Only 4 real cardinal
//      ports (N/S/E/W) are physically wired in this file; bits [5:4]
//      are real, reserved headroom, exactly mirroring nano's own
//      already-real convention, not a claim that 6-directional
//      routing is implemented here (#604 remains the separate, larger,
//      not-yet-started thread for that).
//   4. "with ack all around": the programming channel gets its own
//      real, independent ack_out/in per direction, matching nano's
//      own real convention -- not a single shared/broadcast ack.
//   5. the `active` bit: a new, real, explicit top-level port. Tied
//      permanently high for standalone (N=1) use -- when a future
//      N-core carrier wraps this same real core, `active` becomes the
//      REAL, ALREADY-PROVEN `incoming_select == SEL_ADDER` decode
//      (unicell_super_v3.v's own real pattern), not a new mechanism.
//      When low, this cell is fully silent: no capture, no offer, no
//      acks on any channel -- confirmed by construction, not asserted.
//
// REAL, HONEST SCOPE, stated plainly, matching #617's own scope doc:
// `is_command_cell` / COMMAND_EMIT mode is NOT included in this first
// build -- a real, separate, later increment (needs real, careful
// semantic design for this core's own two-stage capture model, unlike
// nano's more general hold/reemit shape). The `cmd_in`/`cmd_out`
// cardinal channel remains genuinely unbuilt (#84), same as
// everywhere else in this project today.
//
// ledger #1036: cfg_data[39:34] = second_downstream_mask, cfg_data[33] = second_output (carry word)
// cfg_data[63:0] field map (atomic boot-load path, unchanged from v1):
//   [5:0]   downstream_mask  — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  upstream_mask    — one-hot(s), N/S/E/W real + 2 reserved
//   [12]    subtract_mode    — 0=A+B, 1=A-B (unchanged from v1)
//   [32:13] addon_config     — 20 bits, SAME real layout as
//                              unicell_super_v3.v's own real addon_config
//   [63:33] reserved
`default_nettype none
`timescale 1ns / 1ps

module adder_cell_v4 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: the real, explicit "active" bit. Tie
    // high for standalone use; drive with a real core_select decode
    // when this core is wrapped by a future N-core carrier.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: the real, targeted programming channel,
    // faithfully ported from unicell_stripped_v1.v's own real
    // program_in/PROG_ID protocol (#123/#140/#615) — its own,
    // independent 4-directional real ack, exactly mirroring nano's
    // own real convention. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid,   // out_buffer holds an unconsumed sum
    output wire         status_a_arrived     // A captured, awaiting B — debug only
);

    // ── State — real core state, unchanged in shape from v1 (6-bit
    // masks instead of 4-bit is the only real width change) ──────────
    reg [31:0] a_reg           = 32'h0;
    reg        a_arrived       = 1'b0;
    reg [31:0] out_buffer      = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg        subtract_mode   = 1'b0;
    // ledger #1036: the optional SECOND OUTPUT word (the carry-out, 0/1) -- cfg_data[33] second_output, cfg_data[39:34] second_downstream_mask (0 = the carry leaves by downstream_mask
    // like the sum). Same two-phase delivery as the multiplier's wide_mode: the sum, then (once it is fully acknowledged) the carry; no new operand is taken meanwhile.
    reg        second_output   = 1'b0;
    reg [5:0]  second_downstream_mask = 6'h0;
    reg        captured_carry  = 1'b0;
    reg        delivering_carry = 1'b0;
    reg        phase1_offered  = 1'b0;
    reg [19:0] addon_config    = 20'h0;
    reg [3:0]  pending_ack     = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state,
    // faithfully mirroring unicell_stripped_v1.v's own real `armed`
    // register and its own real semantics exactly — a cell mid-
    // reprogram via the targeted channel stays COLD (disarmed) until
    // an explicit COMPLETE with its own data payload's LSB set.
    reg        armed           = 1'b0;

    wire effective_freeze = freeze_in;
    // points.md #617 point 5: `active` gates EVERYTHING below —
    // capture, fire, offer, and both real ack channels — by
    // construction, not by a separate late-stage mux the way the
    // existing super shell currently zeroes out non-selected cores'
    // OWN outputs from the outside. When low, this cell has no real
    // effect on anything it's wired to.
    wire effective_armed  = armed && active;

    // ── Upstream arrival selection — real, only the low 4 bits of
    // the now-6-bit upstream_mask are ever wired to a real physical
    // port in this file (bits [5:4] are real, reserved headroom,
    // matching nano's own real convention exactly — #604's own
    // 3D-cardinal prerequisite, not implemented here). ──
    wire sel_n = arrived_n && upstream_mask[0];
    wire sel_s = arrived_s && upstream_mask[1];
    wire sel_e = arrived_e && upstream_mask[2];
    wire sel_w = arrived_w && upstream_mask[3];
    wire any_upstream_arrived = sel_n | sel_s | sel_e | sel_w;
    wire [31:0] upstream_val = (sel_n ? data_in_n : 32'h0) |
                               (sel_s ? data_in_s : 32'h0) |
                               (sel_e ? data_in_e : 32'h0) |
                               (sel_w ? data_in_w : 32'h0);

    wire block_for_second = second_output && data_valid;
    wire capture_now = any_upstream_arrived && !a_arrived && !effective_freeze && !block_for_second &&
                       effective_armed && !program_in;
    wire can_fire = any_upstream_arrived && a_arrived && !data_valid && !effective_freeze &&
                    effective_armed && !program_in;

    assign ack_out_n = (capture_now || can_fire) && sel_n;
    assign ack_out_s = (capture_now || can_fire) && sel_s;
    assign ack_out_e = (capture_now || can_fire) && sel_e;
    assign ack_out_w = (capture_now || can_fire) && sel_w;

    // ── The real arithmetic — unchanged from adder_cell_v1.v ────────
    wire [31:0] adder_b_in = subtract_mode ? ~upstream_val : upstream_val;
    wire [31:0] adder_sum;
    wire        adder_cout;
    adder_v1 #(.WIDTH(32)) ADD (
        .a(a_reg), .b(adder_b_in), .cin(subtract_mode),
        .sum(adder_sum), .cout(adder_cout)
    );

    // ── Downstream offering — real, unchanged shape from v1, gated
    // additionally on `effective_armed` (a disarmed/inactive cell
    // never offers, by construction). ──
    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && !phase1_offered && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);
    wire start_carry_phase = offer_draining && second_output && !delivering_carry;
    wire genuinely_done    = offer_draining && !start_carry_phase;

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #617: the real, three-addon chain, wired exactly
    // as unicell_super_v3.v already does it -- SAME order
    // (nibble_mask -> shift/lane -> invert), SAME 20-bit addon_config
    // layout, reused verbatim (#311/#312's own already-proven wiring,
    // not reinvented). ──
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(out_buffer), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    // Real, honest gating: ready_out reflects `armed` the same way
    // nano's own real ready_out does (`ready_bit && armed`, #615) —
    // an inactive or disarmed cell is never ready.
    assign ready_out = effective_armed && !effective_freeze && !(a_arrived && data_valid) && !block_for_second;
    assign status_data_valid = data_valid;
    assign status_a_arrived  = a_arrived;

    // ── points.md #617: the real, targeted programming channel's own
    // priority-select and field IDs — faithfully mirroring
    // unicell_stripped_v1.v's own real convention (#140), remapped
    // onto this cell's own real 3 fields. Real, deliberate deviation
    // from nano's own exact bit positions: nano's own word is 16 bits
    // (`prog_word[15:0]`, ID at `[18:16]`) since none of ITS OWN 7
    // fields need more; this core's `PROG_ID_ADDON_CONFIG` needs a
    // real, full 20-bit word (the same real `addon_config` width
    // shared with `unicell_super_v3.v`) to land in ONE write rather
    // than being split across two -- so the ID field here sits at
    // `[22:20]`, directly above a genuinely wider `[19:0]` word,
    // non-overlapping, same real principle nano's own layout follows
    // (ID immediately above its own data payload), just sized for
    // this core's own real, wider field. Only 3 real IDs + COMPLETE
    // are used; the 3-bit ID width (same as nano's) leaves real,
    // honest headroom for this core's own future fields, same
    // "nothing wasted, real reserved space" convention nano already
    // has. ──
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_SUBTRACT_MODE   = 3'd2;
    localparam [2:0] PROG_ID_ADDON_CONFIG    = 3'd3;
    localparam [2:0] PROG_ID_SECOND_OUTPUT   = 3'd4;   // ledger #1036 (word[0])
    localparam [2:0] PROG_ID_SECOND_DOWNSTREAM_MASK = 3'd5;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            a_reg           <= 32'h0;
            a_arrived       <= 1'b0;
            out_buffer      <= 32'h0;
            data_valid      <= 1'b0;
            downstream_mask <= 6'h0;
            upstream_mask   <= 6'h0;
            subtract_mode   <= 1'b0;
            second_output   <= 1'b0;
            second_downstream_mask <= 6'h0;
            captured_carry  <= 1'b0;
            delivering_carry <= 1'b0;
            phase1_offered  <= 1'b0;
            addon_config    <= 20'h0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            // Real, atomic boot-load path — unchanged real semantics
            // from v1, arms immediately (nothing left to stage).
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            subtract_mode   <= cfg_data[12];
            second_output   <= cfg_data[33];
            second_downstream_mask <= cfg_data[39:34];
            delivering_carry <= 1'b0;
            phase1_offered  <= 1'b0;
            addon_config    <= cfg_data[32:13];
            a_arrived       <= 1'b0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            // Real, targeted, staged reconfiguration — mirrors
            // unicell_stripped_v1.v's own real case statement exactly,
            // remapped onto this cell's own 3 real fields.
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_SUBTRACT_MODE:   subtract_mode   <= prog_word[0];
                PROG_ID_SECOND_OUTPUT:   second_output   <= prog_word[0];
                PROG_ID_SECOND_DOWNSTREAM_MASK: second_downstream_mask <= prog_word[5:0];
                PROG_ID_ADDON_CONFIG:    addon_config    <= prog_word[19:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];  // real "commit+arm" vs "commit, stay cold"
                end
                default: ;
            endcase
        end else begin
            if (can_fire) begin
                out_buffer <= adder_sum;
                data_valid <= 1'b1;
                captured_carry   <= adder_cout;
                delivering_carry <= 1'b0;
                phase1_offered   <= 1'b0;
                a_arrived  <= 1'b0;
            end else if (capture_now) begin
                a_reg     <= upstream_val;
                a_arrived <= 1'b1;
            end

            if (start_carry_phase) begin
                out_buffer       <= {31'h0, captured_carry};
                delivering_carry <= 1'b1;
            end else if (genuinely_done) begin
                data_valid <= 1'b0;
            end
            if (any_fire) phase1_offered <= 1'b1;
            // a phase transition re-arms pending_ack this very cycle (no window where it reads 0 while data_valid is still high)
            pending_ack <= start_carry_phase ? ((|second_downstream_mask[3:0]) ? second_downstream_mask[3:0] : downstream_mask[3:0]) : next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4c.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// adder_cell_v4c.v — points.md #720: the "c" (carrier) variant of
// adder_cell_v4.v. Alan's own real, direct observation: the VIX
// carrier's whole design concept is to hold COMMON functionality
// centrally, so each wrapped core only does its own specific task --
// but adder_cell_v4's own internal 3-addon chain (nibble_mask/shift_
// lane/invert) duplicates exactly what the carrier itself is meant to
// provide once, shared across whichever core is active. Confirmed
// directly, not assumed: an audit of all 9 VIX core types found this
// EXACT SAME 3-addon chain built into 8 of the 9 (every one except
// command, which does programming/routing, not data transformation)
// -- a real, genuine case of the "inflation problem," not a one-off.
//
// adder_cell_v4.v itself is UNCHANGED and stays exactly as it is --
// still the real, proven, standalone core used wherever a carrier
// isn't wrapping it. This "c" variant exists ONLY for use inside a
// carrier that already supplies the addon chain itself.
//
// Real, honest scope of this specific file's own changes from v4:
//   1. The internal addon chain (nibble_mask_addon_v1/shift_lane_
//      addon_v1/invert_addon_v1) is REMOVED entirely -- data_out_n/s/
//      e/w now come directly from out_buffer, the real computed sum,
//      matching what data_out_n/s/e/w already were BEFORE the addon
//      chain's own real transform in v4.
//   2. addon_config (20 bits) is removed from cfg_data's own field
//      map, the register, and the live-programming PROG_ID case --
//      there is nothing left for it to configure at this core level.
//      cfg_data itself KEEPS its original 64-bit width (simpler, no
//      risk to any wiring elsewhere that assumes it) -- the bits
//      addon_config used to occupy are now genuinely reserved.
//   3. Real, honest, considered decision -- NOT the same fix v9's own
//      _v3 cells got: downstream_mask/upstream_mask/subtract_mode
//      STAY real registers here (latched on cfg_valid or the live
//      programming channel), not continuous wires. v9's own _v3 cells
//      have no live-programming channel at all, so reading core_config
//      continuously is both safe and the strongest fix (genuinely
//      always current). This cell's own live-programming channel
//      (program_in/prog_data_in, #617) genuinely NEEDS a register it
//      can independently write to -- a continuous wire would silence
//      that feature entirely. The real, correct config-off-shell fix
//      for a v4c cell lives at the SHELL level instead: the carrier
//      must feed this cell's own cfg_data from its own stable
//      core_config, not a transient incoming/about-to-commit value --
//      once that's true, every cfg_valid latch here reads the correct,
//      current value, and core_config's own UNION semantics (the same
//      physical bits mean this core's own fields ONLY while it's
//      actually selected) mean there is no real window where this
//      core's own config could change without cfg_valid also pulsing
//      for it.
//
// ledger #1036: cfg_data[39:34] = second_downstream_mask, cfg_data[33] = second_output (carry word)
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   downstream_mask  — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  upstream_mask    — one-hot(s), N/S/E/W real + 2 reserved
//   [12]    subtract_mode    — 0=A+B, 1=A-B
//   [63:13] reserved (addon_config's own old home, now genuinely free)
`default_nettype none
`timescale 1ns / 1ps

module adder_cell_v4c #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid,
    output wire         status_a_arrived
);

    reg [31:0] a_reg           = 32'h0;
    reg        a_arrived       = 1'b0;
    reg [31:0] out_buffer      = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg        subtract_mode   = 1'b0;
    // ledger #1036: the optional SECOND OUTPUT word (the carry-out, 0/1) -- cfg_data[33] second_output, cfg_data[39:34] second_downstream_mask (0 = the carry leaves by downstream_mask
    // like the sum). Same two-phase delivery as the multiplier's wide_mode: the sum, then (once it is fully acknowledged) the carry; no new operand is taken meanwhile.
    reg        second_output   = 1'b0;
    reg [5:0]  second_downstream_mask = 6'h0;
    reg        captured_carry  = 1'b0;
    reg        delivering_carry = 1'b0;
    reg        phase1_offered  = 1'b0;
    reg [3:0]  pending_ack     = 4'h0;
    reg        armed           = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    wire sel_n = arrived_n && upstream_mask[0];
    wire sel_s = arrived_s && upstream_mask[1];
    wire sel_e = arrived_e && upstream_mask[2];
    wire sel_w = arrived_w && upstream_mask[3];
    wire any_upstream_arrived = sel_n | sel_s | sel_e | sel_w;
    wire [31:0] upstream_val = (sel_n ? data_in_n : 32'h0) |
                               (sel_s ? data_in_s : 32'h0) |
                               (sel_e ? data_in_e : 32'h0) |
                               (sel_w ? data_in_w : 32'h0);

    wire block_for_second = second_output && data_valid;
    wire capture_now = any_upstream_arrived && !a_arrived && !effective_freeze && !block_for_second &&
                       effective_armed && !program_in;
    wire can_fire = any_upstream_arrived && a_arrived && !data_valid && !effective_freeze &&
                    effective_armed && !program_in;

    assign ack_out_n = (capture_now || can_fire) && sel_n;
    assign ack_out_s = (capture_now || can_fire) && sel_s;
    assign ack_out_e = (capture_now || can_fire) && sel_e;
    assign ack_out_w = (capture_now || can_fire) && sel_w;

    // ── The real arithmetic — unchanged from v4/v1 ──────────────────
    wire [31:0] adder_b_in = subtract_mode ? ~upstream_val : upstream_val;
    wire [31:0] adder_sum;
    wire        adder_cout;
    adder_v1 #(.WIDTH(32)) ADD (
        .a(a_reg), .b(adder_b_in), .cin(subtract_mode),
        .sum(adder_sum), .cout(adder_cout)
    );

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && !phase1_offered && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);
    wire start_carry_phase = offer_draining && second_output && !delivering_carry;
    wire genuinely_done    = offer_draining && !start_carry_phase;

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #720: NO addon chain here at all — the carrier
    // already provides one, shared across whichever core is active.
    // data_out_n/s/e/w are the real computed sum, directly. ──
    assign data_out_n = out_buffer;
    assign data_out_s = out_buffer;
    assign data_out_e = out_buffer;
    assign data_out_w = out_buffer;

    assign ready_out = effective_armed && !effective_freeze && !(a_arrived && data_valid) && !block_for_second;
    assign status_data_valid = data_valid;
    assign status_a_arrived  = a_arrived;

    // points.md #720: PROG_ID_ADDON_CONFIG removed -- nothing left at
    // this core level for it to configure. IDs kept numerically stable
    // for the three real remaining fields (matching v4's own numbering
    // exactly, so a v4-vs-v4c swap doesn't also require re-deriving
    // programming words elsewhere).
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_SUBTRACT_MODE   = 3'd2;
    localparam [2:0] PROG_ID_SECOND_OUTPUT   = 3'd4;   // ledger #1036 (word[0])
    localparam [2:0] PROG_ID_SECOND_DOWNSTREAM_MASK = 3'd5;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            a_reg           <= 32'h0;
            a_arrived       <= 1'b0;
            out_buffer      <= 32'h0;
            data_valid      <= 1'b0;
            downstream_mask <= 6'h0;
            upstream_mask   <= 6'h0;
            subtract_mode   <= 1'b0;
            second_output   <= 1'b0;
            second_downstream_mask <= 6'h0;
            captured_carry  <= 1'b0;
            delivering_carry <= 1'b0;
            phase1_offered  <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            subtract_mode   <= cfg_data[12];
            second_output   <= cfg_data[33];
            second_downstream_mask <= cfg_data[39:34];
            delivering_carry <= 1'b0;
            phase1_offered  <= 1'b0;
            a_arrived       <= 1'b0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_SUBTRACT_MODE:   subtract_mode   <= prog_word[0];
                PROG_ID_SECOND_OUTPUT:   second_output   <= prog_word[0];
                PROG_ID_SECOND_DOWNSTREAM_MASK: second_downstream_mask <= prog_word[5:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (can_fire) begin
                out_buffer <= adder_sum;
                data_valid <= 1'b1;
                captured_carry   <= adder_cout;
                delivering_carry <= 1'b0;
                phase1_offered   <= 1'b0;
                a_arrived  <= 1'b0;
            end else if (capture_now) begin
                a_reg     <= upstream_val;
                a_arrived <= 1'b1;
            end

            if (start_carry_phase) begin
                out_buffer       <= {31'h0, captured_carry};
                delivering_carry <= 1'b1;
            end else if (genuinely_done) begin
                data_valid <= 1'b0;
            end
            if (any_fire) phase1_offered <= 1'b1;
            // a phase transition re-arms pending_ack this very cycle (no window where it reads 0 while data_valid is still high)
            pending_ack <= start_carry_phase ? ((|second_downstream_mask[3:0]) ? second_downstream_mask[3:0] : downstream_mask[3:0]) : next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// adder_cell_v4s.v -- the first "v4s" (stripped) cell, per Alan's own real design
// direction from a live conversation (2026-09-29, morning), building directly on
// that session's own measured findings:
//
//   - #886 measured shift_lane_addon_v2 alone at ~2,600 LUT4 -- bigger than this
//     WHOLE adder core (adder_full 2,348 LUT4) -- so the addon chain is gone here
//     entirely, not made optional. There is no addon_config field at all.
//   - #889 found that nearly an entire cell's footprint, for several light types,
//     was the SHARED HANDSHAKE SKELETON (armed/pending_ack/ready_in/ready_out/the
//     4-way mask decode) -- not the function it nominally computed. That skeleton
//     is removed here too: no ack, no ready, no upstream/downstream mask, no
//     per-direction arrived tracking.
//   - #885 already measured the winning shape this design commits to structurally:
//     a static, fixed-latency pipeline stage beat the general ack-driven fold on
//     both size and speed (8 cells/19 ticks vs 56 cells/204 ticks, same job).
//
// What is DELIBERATELY gone, and why (real trade-offs, not oversights):
//   - Cardinal routing (N/S/E/W): replaced by two FIXED, dedicated operand inputs
//     (in_a, in_b) and one fixed output. "No cardinality" removes the runtime
//     DECISION of which direction data comes from/goes to -- it does not reduce
//     a binary function's real arity below two operands. Each operand has its own
//     permanent wire; there is no mask, so there is nothing to decide at runtime.
//   - Backward ack/ready (flow control): gone entirely, by design, not an
//     oversight. This is what makes the cell genuinely timing-agnostic -- no cell
//     can ever be told to wait. The real consequence Alan named directly: every
//     cell's latency must now be a KNOWN, FIXED number of cycles at build time,
//     and any two paths that CONVERGE on a later cell must arrive latency-matched,
//     or a fresh value on one side silently combines with a stale one on the
//     other. This is not a new problem for the project -- #762-#765's timing
//     model and dsp_latency_v1's latency-padding mechanism already exist to solve
//     exactly this; they have simply never been pointed at this cell family yet.
//     That padding work is the real next step this file creates a need for, not
//     something this file itself solves.
//   - freeze_in: also removed, as a direct consequence of the above, not a
//     separate cut. A per-cell pause would silently break every latency guarantee
//     downstream of it. If a global pause is ever needed, it must be a single
//     synchronized clock-enable across the WHOLE chain at once, never per-cell --
//     that is a separate, future design question, not addressed here.
//   - Live per-direction reprogramming (program_in/prog_data_in_*): removed for
//     this first cut. There is no longer a cardinal direction to receive a
//     reprogramming word from. Config is boot-load only here (cfg_valid/cfg_data);
//     a future shared reprogramming bus for the v4s family, if wanted, is a
//     separate design question, deliberately not decided by this file.
//
// The "timing line": a single FORWARD valid_out bit riding alongside data_out,
// asserted for exactly one cycle when data_out holds a genuinely new result.
// This is not ack's replacement -- it carries no backward information and never
// stalls anything upstream. A downstream cell either uses it or free-runs without
// it; either way this cell never waits and never asks anyone else to wait.
//
// Fixed latency: exactly ONE clock cycle from (valid_in asserted, in_a/in_b
// present) to (valid_out asserted, data_out holding the result). This number is
// the whole point -- it is what a real latency-padding scheme downstream needs to
// know, and it must stay exactly this if this file is ever edited.
//
// cfg_data field map (deliberately tiny -- no mask, no addon config left to hold):
//   [0]     subtract_mode -- 0 = A+B, 1 = A-B (same semantics as adder_cell_v4/v4c)
//   [31:1]  reserved
`default_nettype none
`timescale 1ns / 1ps

module adder_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,

    input  wire [31:0]  in_a,
    input  wire [31:0]  in_b,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        subtract_mode = 1'b0;
    reg        armed         = 1'b0;   // gates output until cfg_valid has loaded real config once
    reg [31:0] out_buffer    = 32'h0;
    reg        valid_out_r   = 1'b0;

    // ── The real arithmetic -- unchanged from adder_v1, the same primitive
    // adder_cell_v4/v4c already use ──────────────────────────────────────
    wire [31:0] adder_b_in = subtract_mode ? ~in_b : in_b;
    wire [31:0] adder_sum;
    wire        adder_cout;
    adder_v1 #(.WIDTH(32)) ADD (
        .a(in_a), .b(adder_b_in), .cin(subtract_mode),
        .sum(adder_sum), .cout(adder_cout)
    );

    assign data_out  = out_buffer;
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            subtract_mode <= 1'b0;
            armed         <= 1'b0;
            out_buffer    <= 32'h0;
            valid_out_r   <= 1'b0;
        end else if (cfg_valid) begin
            subtract_mode <= cfg_data[0];
            armed         <= 1'b1;
            valid_out_r   <= 1'b0;
        end else begin
            // Fixed one-cycle latency: this cycle's inputs become next cycle's
            // output, unconditionally once armed. No capture/hold state, no
            // wait -- the whole reason this is timing-agnostic.
            out_buffer  <= adder_sum;
            valid_out_r <= armed && valid_in;
        end
    end

endmodule

