// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// adder_cell_v4sa.v -- points.md #906: "v4s" plus a minimal, reintroduced ack and
// a global freeze, per Alan's own real design direction (2026-09-30 morning).
// Builds on adder_cell_v4s.v (kept unchanged, as the zero-wait alternative for
// anyone who genuinely needs guaranteed fixed-cycle throughput); this is the
// SEPARATE, ack-bearing sibling, not a replacement.
//
// THE REAL DISTINCTION FROM THE ORIGINAL CARDINAL FAMILY'S ACK (why this isn't a
// retreat from "physics, not control"): what made the original expensive wasn't
// having a backward signal at all -- #889/#899 found it was the ARBITRATION: a
// 4-way mask deciding WHICH direction to wait for and WHICH to route to, every
// cycle. This cell's ack is POINT-TO-POINT: one fixed sender, one fixed receiver,
// decided at build time, same as in_a/in_b. There is no "who" to decide here --
// the topology is still fixed by construction. This adds a cheap SYNCHRONISATION
// primitive on top of a graph that stays fixed; it does not reintroduce the
// runtime ROUTING decision that was the actual expensive part.
//
// A real, valuable consequence worth stating plainly: this likely removes the
// need for the static latency-padding work `adder_cell_v4s.v`'s own header named
// as the real next step. That scheme only works if every cell's latency is known
// at compile time, and breaks the moment any future cell has data-dependent
// timing. A local ack solves the same underlying problem (don't let a fast
// path's fresh value collide with a slow path's stale one) in a way that is
// robust to ANY timing, known or not, with zero static analysis required.
//
// ── ack protocol (standard ready/valid, not a one-shot pulse) ──────────────
//   ack_out = this cell is ready to accept a NEW (in_a, in_b, valid_in) --
//             true whenever it isn't already holding an unconsumed result.
//   valid_out = this cell IS holding a real, not-yet-consumed result -- stays
//             HIGH across multiple cycles if the downstream receiver isn't
//             ready yet, unlike adder_cell_v4s.v's one-shot pulse. This is the
//             real behavioural difference reintroducing ack requires.
//   ack_in  = the downstream receiver has taken the current result; this cell
//             may present a new one starting next cycle.
// Latency is no longer always exactly one cycle -- it is AT LEAST one cycle,
// more if the downstream receiver stalls. That is the real, honest trade this
// file makes in exchange for removing the static-timing requirement.
//
// ── freeze: GLOBAL, not per-cell (Alan's own real refinement) ──────────────
// One signal, broadcast identically to every cell in the whole assembled
// design by the assembler -- not part of the ICM connection graph, not wired
// cell-to-cell. Two real jobs, not one: (1) the original stated purpose --
// hold the WHOLE system still while configuration is loaded into every cell,
// so nothing processes a partial or inconsistent config mid-load; (2) a real,
// useful side effect of going global rather than local -- freezing the whole
// system at any later point gives a clean, synchronised pause where every
// cell's state can be safely read out and compared against the VM's own
// mirrored computation, which per-cell freeze could never offer as cleanly.
// `armed` keeps its own, separate, narrower meaning (has this cell EVER
// received real config -- a one-way latch); freeze is the new, orthogonal,
// re-triggerable hold, and gates the ENTIRE update -- including whether a
// fresh `cfg_valid` may take effect -- not just the data path, so config can
// be loaded safely while frozen and nothing else moves until release.
`default_nettype none
`timescale 1ns / 1ps

module adder_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        SECOND_PORT = 0,   // 1 = build the carry_out port's logic (ledger #976: the compiler's ICM flag tells the assembler which cells need it);
                                          // 0 = the ports exist (fixed placement) but are silent and cost nothing
    parameter        WIDTH   = 32   // points.md #909: the real "flex" width parameter --
                                     // Alan's own direction. Defaults to 32 so every
                                     // existing #906/#908 measurement stays exactly valid
                                     // unchanged; the assembler (once built, #903-905's
                                     // standing plan) is meant to override this per the
                                     // target's own MAN-file-recorded native width (18 for
                                     // this card, per #903/#904's own finding). cfg_data
                                     // deliberately stays a fixed 32 bits regardless of
                                     // WIDTH -- it only ever needs to hold a 1-bit
                                     // subtract_mode flag here, and other v4s cells
                                     // (sequencer_cell_v4s) already needed a config bus
                                     // wider than their own data width, so tying the two
                                     // together would be the wrong coupling.
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,   // global, fanned out identically to every cell

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,

    input  wire [WIDTH-1:0]  in_a,
    input  wire [WIDTH-1:0]  in_b,
    input  wire              valid_in,
    output wire               ack_out,     // backward, to whoever feeds in_a/in_b

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in,      // backward, from the one fixed downstream receiver

    // SECOND OUTPUT PORT (Alan's ruling, 2026-10-06: a cell that produces two results gets two
    // ports, as branch does). The raw carry-out of the add, as a WIDTH-bit word that is 0 or 1
    // (so it can feed an adder's in_b directly for multi-word arithmetic). Own valid/ack pair,
    // fully independent of data_out's. For subtract (a + ~b + 1) this is the raw carry, i.e.
    // NOT-borrow. Only produced when cfg_data[1] (carry_enable) is set: with it clear the port is
    // silent, never goes pending, and the cell behaves exactly as before -- so leaving the three
    // ports unconnected is safe.
    output wire [WIDTH-1:0]  carry_out,
    output wire               valid_out_c,
    input  wire               ack_in_c
);

    reg             subtract_mode = 1'b0;
    reg             armed         = 1'b0;   // narrow, permanent: has real config ever loaded
    reg             pending       = 1'b0;   // holding a real, not-yet-consumed result
    reg             carry_enable  = 1'b0;   // cfg_data[1]: also produce the carry on carry_out
    reg             pending_c     = 1'b0;   // carry result held, not yet consumed
    reg             carry_buffer  = 1'b0;
    reg [WIDTH-1:0] out_buffer    = {WIDTH{1'b0}};

    // ── The real arithmetic -- unchanged from adder_v1, the same primitive
    // adder_cell_v4/v4c/v4s already use, now genuinely width-generic ──────
    wire [WIDTH-1:0] adder_b_in = subtract_mode ? ~in_b : in_b;
    wire [WIDTH-1:0] adder_sum;
    wire             adder_cout;
    adder_v1 #(.WIDTH(WIDTH)) ADD (
        .a(in_a), .b(adder_b_in), .cin(subtract_mode),
        .sum(adder_sum), .cout(adder_cout)
    );

    assign data_out  = out_buffer;
    assign valid_out = pending;
    assign carry_out   = {{(WIDTH-1){1'b0}}, carry_buffer};
    assign valid_out_c = pending_c;
    // A new round needs BOTH outputs consumed (same rule as branch_cell_v4sa).
    assign ack_out   = armed && !pending && !pending_c && !freeze_in;   // a frozen cell must not claim
                                                            // readiness -- nothing can move

    always @(posedge clk) begin
        if (rst) begin
            subtract_mode <= 1'b0;
            armed         <= 1'b0;
            pending       <= 1'b0;
            carry_enable  <= 1'b0;
            pending_c     <= 1'b0;
            carry_buffer  <= 1'b0;
            out_buffer    <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            // Config load takes effect even while frozen -- loading safely
            // during a freeze is the whole point of freeze existing.
            subtract_mode <= cfg_data[0];
            carry_enable  <= (SECOND_PORT != 0) && cfg_data[1];
            armed         <= 1'b1;
            pending       <= 1'b0;   // discard any in-flight result on reconfigure
            pending_c     <= 1'b0;
            out_buffer    <= {WIDTH{1'b0}};
        end else if (!freeze_in) begin
            // Normal operation, only when not frozen. Exactly one of "clear a
            // consumed result" or "capture a fresh one" ever happens per
            // cycle -- never both, since ack_out is only ever true when
            // pending is already false, so a correctly-behaving upstream
            // sender never presents valid_in while pending is still true.
            if (pending || pending_c) begin
                // each output clears independently on its own ack
                if (pending   && ack_in)   pending   <= 1'b0;
                if (pending_c && ack_in_c) pending_c <= 1'b0;
            end else if (valid_in) begin
                out_buffer   <= adder_sum;
                pending      <= 1'b1;
                carry_buffer <= (SECOND_PORT != 0) && adder_cout;
                pending_c    <= carry_enable;
            end
        end
        // else: frozen, not resetting, not reconfiguring -- hold everything
        // exactly as it is, including `pending`/`out_buffer`/`ack_out`'s own
        // registered state. A real, true pause.
    end

endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// branch_cell_v4.v — points.md #617/#624: the SIXTH real "unified
// carrier" core, and the most structurally complex of the six built
// so far. Real core logic CLONED from branch_cell_v1.v unchanged,
// INCLUDING its own real, documented history, faithfully preserved:
//   - the real held-reference two-phase capture (#497): the first
//     real arrival becomes a held comparison reference (never itself
//     compared or drained); every later arrival is compared against
//     it and routed per a real 3-outcome (<, =, >) table, each with
//     independently configured value source, emit/suppress, and
//     fan-out routing.
//   - the real, found-not-assumed `consumed` bug guard: without it, a
//     single physical arrival would be captured TWICE (once as the
//     reference, once immediately compared against itself) since this
//     core's two capture paths have DIFFERENT guards, unlike every
//     other core's single shared one.
//   - real ROLLING MODE (#497-followup): the just-compared value
//     becomes the new held reference regardless of whether that
//     outcome emitted, turning static baseline comparison into real
//     drift detection.
//
// Same real shell additions as #618-#623, per Alan's own precise
// 5-point breakdown (#617):
//   1. programming: real, targeted program_in/PROG_ID channel -- REAL,
//      NECESSARY ADAPTATION found here, not assumed: this core has 15
//      real distinct fields, more than the 3-bit ID (7 real slots)
//      every prior core's own budget supported. Widened to a real
//      4-bit ID (16 real slots, 15 fields + COMPLETE, a clean, exact
//      fit with zero spare) -- the first real case where FIELD COUNT,
//      not field WIDTH, forced the protocol to adapt.
//   2. shift/nibble_mask/lane: the same real, already-proven 3-addon
//      chain, applied to the offered out_buffer.
//   3. 6-way cardinality: real field-width headroom, applied here to
//      BOTH the real absolute route masks (route_low/equal/high,
//      4->6 bits) AND, a real, deliberate first, `upstream_dir`
//      itself (2->3 bits) -- a single fixed-direction VALUE, not a
//      mask, but widened for the same real reason (future 3D
//      headroom, #604), since a value field needs the same reserved
//      room a mask field does if a 6-way substrate is ever built.
//   4. ack all around: the programming channel's own real ack.
//   5. `active`: the same real, explicit port -- gates BOTH real
//      capture paths (`capture_reference`/`capture_compare`) and the
//      offer side, so an inactive cell neither silently captures a
//      new reference nor silently compares against an old one.
//
// REAL, NECESSARY WIDTH CHANGE: this core's own real field total
// (69 bits with the widened route/upstream_dir fields + addon_config)
// exceeds the original 64-bit cfg_data -- widened to 80 bits, same
// real precedent as `ram_cell_v4.v` (#619), 11 bits of real reserved
// headroom.
//
// REAL, HONEST SCOPE, matching #618-#623's own stated deferrals:
// `is_command_cell` mode NOT included (parked as a possible 9th-core
// question).
//
// cfg_data[79:0] field map (atomic boot-load path):
//   [2:0]   upstream_dir        — single fixed direction, 0=N 1=S 2=E
//                                 3=W, real, reserved headroom at 4-7
//   [3]     value_source_low
//   [4]     value_source_equal
//   [5]     value_source_high
//   [12:6]  fixed_value_low     — 7-bit constant
//   [19:13] fixed_value_equal
//   [26:20] fixed_value_high
//   [27]    emit_low
//   [28]    emit_equal
//   [29]    emit_high
//   [35:30] route_low           — real, absolute one-hot(s), 4 real +
//                                 2 reserved
//   [41:36] route_equal
//   [47:42] route_high
//   [48]    rolling_mode
//   [68:49] addon_config        — 20 bits, SAME real layout as
//                                 unicell_super_v3.v's own real addon_config
//   [79:69] reserved            — 11 bits, real, honest headroom
`default_nettype none
`timescale 1ns / 1ps

module branch_cell_v4 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [79:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: real, targeted programming channel — real,
    // necessary 4-bit ID (16 real slots), not the 3-bit budget every
    // prior core used, see the header's own real reasoning. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid
);

    // ── Real, static config fields, loaded on cfg_valid -- same real
    // shape as v1, widened per the header's own real reasoning. ──
    reg [2:0] upstream_dir = 3'h0;

    reg value_source_low = 1'b0, value_source_equal = 1'b0, value_source_high = 1'b0;
    reg [6:0] fixed_value_low = 7'h0, fixed_value_equal = 7'h0, fixed_value_high = 7'h0;
    reg emit_low = 1'b0, emit_equal = 1'b0, emit_high = 1'b0;
    reg [5:0] route_low = 6'h0, route_equal = 6'h0, route_high = 6'h0;
    reg rolling_mode = 1'b0;
    reg [19:0] addon_config = 20'h0;

    // ── The held reference, per #497's own real optimization —
    // unchanged from v1. ──
    reg [31:0] ref_value = 32'h0;
    reg        ref_valid = 1'b0;

    reg [31:0] out_buffer  = 32'h0;
    reg        data_valid  = 1'b0;
    reg [5:0]  active_route = 6'h0;
    reg [3:0]  pending_ack  = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as #618-#623's own.
    reg        armed = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ── Real, single fixed upstream direction -- decoded, not a mask,
    // unchanged from v1. Only values 0-3 are ever real (the widened
    // field's own values 4-7 are real, reserved headroom, matching
    // nano's own convention). ──
    wire sel_n = arrived_n && (upstream_dir == 3'd0);
    wire sel_s = arrived_s && (upstream_dir == 3'd1);
    wire sel_e = arrived_e && (upstream_dir == 3'd2);
    wire sel_w = arrived_w && (upstream_dir == 3'd3);
    wire any_upstream_arrived = sel_n | sel_s | sel_e | sel_w;
    wire [31:0] upstream_val = (sel_n ? data_in_n : 32'h0) |
                               (sel_s ? data_in_s : 32'h0) |
                               (sel_e ? data_in_e : 32'h0) |
                               (sel_w ? data_in_w : 32'h0);

    // ── Real, unchanged from v1: the found-not-assumed `consumed`
    // bug guard -- see this file's own real header for why it's
    // necessary. Real, necessary extension: both real capture paths
    // also gated on effective_armed/!program_in (#617's own real
    // "inactive = zero effect" principle, extended here to a
    // genuinely two-path core for the first time). ──
    reg consumed = 1'b0;

    wire capture_reference = any_upstream_arrived && !consumed && !ref_valid &&
                             !effective_freeze && effective_armed && !program_in;
    wire capture_compare   = any_upstream_arrived && !consumed && ref_valid && !data_valid &&
                             !effective_freeze && effective_armed && !program_in;
    wire capture_now       = capture_reference || capture_compare;

    assign ack_out_n = capture_now && sel_n;
    assign ack_out_s = capture_now && sel_s;
    assign ack_out_e = capture_now && sel_e;
    assign ack_out_w = capture_now && sel_w;

    // ── THE CORE — real, unchanged from v1: a genuine two's-complement
    // 3-way outcome. ──
    wire signed [31:0] signed_val = upstream_val;
    wire signed [31:0] signed_ref = ref_value;
    wire is_low   = (signed_val <  signed_ref);
    wire is_equal = (signed_val == signed_ref);
    wire is_high  = (signed_val >  signed_ref);

    wire outcome_value_source = (is_low  ? value_source_low  :
                                  is_equal ? value_source_equal :
                                             value_source_high);
    wire [6:0] outcome_fixed_value = (is_low  ? fixed_value_low  :
                                       is_equal ? fixed_value_equal :
                                                  fixed_value_high);
    wire outcome_emit = (is_low  ? emit_low  :
                          is_equal ? emit_equal :
                                     emit_high);
    wire [5:0] outcome_route = (is_low  ? route_low  :
                                 is_equal ? route_equal :
                                            route_high);

    wire [31:0] outcome_out_value = outcome_value_source ? {25'h0, outcome_fixed_value}
                                                           : upstream_val;

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!active_route[0] || ready_in_n) &&
                             (!active_route[1] || ready_in_s) &&
                             (!active_route[2] || ready_in_e) &&
                             (!active_route[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (active_route[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack       & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #617: the real, three-addon chain, applied to the
    // offered out_buffer, wired identically to #618-#623's own. ──
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(out_buffer), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    assign ready_out = effective_armed && !effective_freeze && !data_valid && ref_valid;
    assign status_data_valid = data_valid;

    // ── points.md #617: real, targeted programming channel — real,
    // necessary 4-bit ID width (16 real slots), the first core where
    // FIELD COUNT (15 real fields) forced this rather than field
    // WIDTH. id at [23:20], word at [19:0] -- same real "ID sits
    // directly above its own data payload" principle every other
    // core's own layout already follows, just wider here. ──
    localparam [3:0] PROG_ID_UPSTREAM_DIR       = 4'd0;
    localparam [3:0] PROG_ID_VALUE_SOURCE_LOW   = 4'd1;
    localparam [3:0] PROG_ID_VALUE_SOURCE_EQUAL = 4'd2;
    localparam [3:0] PROG_ID_VALUE_SOURCE_HIGH  = 4'd3;
    localparam [3:0] PROG_ID_FIXED_VALUE_LOW    = 4'd4;
    localparam [3:0] PROG_ID_FIXED_VALUE_EQUAL  = 4'd5;
    localparam [3:0] PROG_ID_FIXED_VALUE_HIGH   = 4'd6;
    localparam [3:0] PROG_ID_EMIT_LOW           = 4'd7;
    localparam [3:0] PROG_ID_EMIT_EQUAL         = 4'd8;
    localparam [3:0] PROG_ID_EMIT_HIGH          = 4'd9;
    localparam [3:0] PROG_ID_ROUTE_LOW          = 4'd10;
    localparam [3:0] PROG_ID_ROUTE_EQUAL        = 4'd11;
    localparam [3:0] PROG_ID_ROUTE_HIGH         = 4'd12;
    localparam [3:0] PROG_ID_ROLLING_MODE       = 4'd13;
    localparam [3:0] PROG_ID_ADDON_CONFIG       = 4'd14;
    localparam [3:0] PROG_ID_COMPLETE           = 4'd15;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [3:0]  prog_id   = prog_data_val[23:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            upstream_dir        <= 3'h0;
            value_source_low    <= 1'b0; value_source_equal <= 1'b0; value_source_high <= 1'b0;
            fixed_value_low     <= 7'h0; fixed_value_equal  <= 7'h0; fixed_value_high  <= 7'h0;
            emit_low            <= 1'b0; emit_equal         <= 1'b0; emit_high         <= 1'b0;
            route_low           <= 6'h0; route_equal        <= 6'h0; route_high        <= 6'h0;
            rolling_mode        <= 1'b0;
            addon_config        <= 20'h0;
            ref_value            <= 32'h0;
            ref_valid            <= 1'b0;
            out_buffer           <= 32'h0;
            data_valid           <= 1'b0;
            active_route         <= 6'h0;
            pending_ack          <= 4'h0;
            consumed             <= 1'b0;
            armed                <= 1'b0;
            program_done_r       <= 1'b0;
        end else if (cfg_valid) begin
            upstream_dir        <= cfg_data[2:0];
            value_source_low    <= cfg_data[3];
            value_source_equal  <= cfg_data[4];
            value_source_high   <= cfg_data[5];
            fixed_value_low     <= cfg_data[12:6];
            fixed_value_equal   <= cfg_data[19:13];
            fixed_value_high    <= cfg_data[26:20];
            emit_low             <= cfg_data[27];
            emit_equal           <= cfg_data[28];
            emit_high            <= cfg_data[29];
            route_low            <= cfg_data[35:30];
            route_equal          <= cfg_data[41:36];
            route_high           <= cfg_data[47:42];
            rolling_mode         <= cfg_data[48];
            addon_config         <= cfg_data[68:49];
            // ── Real release, unchanged from v1: reprogramming
            // discards the held reference and any in-flight offer --
            // see v1's own real, explicitly-flagged judgment call. ──
            ref_value             <= 32'h0;
            ref_valid             <= 1'b0;
            data_valid            <= 1'b0;
            pending_ack           <= 4'h0;
            consumed              <= 1'b0;
            armed                 <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_UPSTREAM_DIR:       upstream_dir       <= prog_word[2:0];
                PROG_ID_VALUE_SOURCE_LOW:   value_source_low   <= prog_word[0];
                PROG_ID_VALUE_SOURCE_EQUAL: value_source_equal <= prog_word[0];
                PROG_ID_VALUE_SOURCE_HIGH:  value_source_high  <= prog_word[0];
                PROG_ID_FIXED_VALUE_LOW:    fixed_value_low    <= prog_word[6:0];
                PROG_ID_FIXED_VALUE_EQUAL:  fixed_value_equal  <= prog_word[6:0];
                PROG_ID_FIXED_VALUE_HIGH:   fixed_value_high   <= prog_word[6:0];
                PROG_ID_EMIT_LOW:           emit_low           <= prog_word[0];
                PROG_ID_EMIT_EQUAL:         emit_equal         <= prog_word[0];
                PROG_ID_EMIT_HIGH:          emit_high          <= prog_word[0];
                PROG_ID_ROUTE_LOW:          route_low          <= prog_word[5:0];
                PROG_ID_ROUTE_EQUAL:        route_equal        <= prog_word[5:0];
                PROG_ID_ROUTE_HIGH:         route_high         <= prog_word[5:0];
                PROG_ID_ROLLING_MODE:       rolling_mode       <= prog_word[0];
                PROG_ID_ADDON_CONFIG:       addon_config       <= prog_word[19:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_reference) begin
                ref_value <= upstream_val;
                ref_valid <= 1'b1;
            end else if (capture_compare) begin
                if (outcome_emit) begin
                    out_buffer   <= outcome_out_value;
                    active_route <= outcome_route;
                    data_valid   <= 1'b1;
                end
                if (rolling_mode) begin
                    ref_value <= upstream_val;
                end
            end

            if (capture_now) begin
                consumed <= 1'b1;
            end else if (!any_upstream_arrived) begin
                consumed <= 1'b0;
            end

            if (offer_draining) begin
                data_valid <= 1'b0;
            end

            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4c.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// branch_cell_v4c.v — points.md #720: the "c" (carrier) variant of
// branch_cell_v4.v. Same real reasoning as the other _v4c files' own
// headers -- the carrier's whole design concept is to hold common
// functionality centrally, and this core's own internal 3-addon chain
// duplicates exactly what the carrier itself now provides once,
// shared. branch_cell_v4.v itself is UNCHANGED, still the real,
// proven, standalone core.
//
// Real, honest scope of this file's own changes from v4:
//   1. The internal addon chain is REMOVED entirely -- data_out_n/s/
//      e/w now come directly from out_buffer.
//   2. addon_config (20 bits) is removed from cfg_data's own field
//      map, the register, and PROG_ID_ADDON_CONFIG. cfg_data KEEPS
//      its original 80-bit width; PROG_ID numbering stays exactly as
//      v4 has it (4'd14, addon_config's own old slot, is simply
//      unused now) rather than renumbering COMPLETE down -- a v4-vs-
//      v4c swap shouldn't also require re-deriving any other real
//      programming word.
//   3. Same real config-off-shell reasoning as every other _v4c file:
//      all real config fields STAY registers (this cell's own live-
//      programming channel needs them independently writable); the
//      real fix lives at the carrier's own shell level.
//
// cfg_data[79:0] field map (atomic boot-load path) -- IDENTICAL to
// v4's own except addon_config's own old home is now reserved:
//   [2:0]   upstream_dir        — single fixed direction, 0=N 1=S 2=E
//                                 3=W, real, reserved headroom at 4-7
//   [3]     value_source_low
//   [4]     value_source_equal
//   [5]     value_source_high
//   [12:6]  fixed_value_low     — 7-bit constant
//   [19:13] fixed_value_equal
//   [26:20] fixed_value_high
//   [27]    emit_low
//   [28]    emit_equal
//   [29]    emit_high
//   [35:30] route_low           — real, absolute one-hot(s), 4 real +
//                                 2 reserved
//   [41:36] route_equal
//   [47:42] route_high
//   [48]    rolling_mode
//   [79:49] reserved            — 31 bits (addon_config's own old
//                                 home, now genuinely free, plus the
//                                 original 11 bits of headroom)

`default_nettype none
`timescale 1ns / 1ps

module branch_cell_v4c #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [79:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: real, targeted programming channel — real,
    // necessary 4-bit ID (16 real slots), not the 3-bit budget every
    // prior core used, see the header's own real reasoning. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid
);

    // ── Real, static config fields, loaded on cfg_valid -- same real
    // shape as v1, widened per the header's own real reasoning. ──
    reg [2:0] upstream_dir = 3'h0;

    reg value_source_low = 1'b0, value_source_equal = 1'b0, value_source_high = 1'b0;
    reg [6:0] fixed_value_low = 7'h0, fixed_value_equal = 7'h0, fixed_value_high = 7'h0;
    reg emit_low = 1'b0, emit_equal = 1'b0, emit_high = 1'b0;
    reg [5:0] route_low = 6'h0, route_equal = 6'h0, route_high = 6'h0;
    reg rolling_mode = 1'b0;

    // ── The held reference, per #497's own real optimization —
    // unchanged from v1. ──
    reg [31:0] ref_value = 32'h0;
    reg        ref_valid = 1'b0;

    reg [31:0] out_buffer  = 32'h0;
    reg        data_valid  = 1'b0;
    reg [5:0]  active_route = 6'h0;
    reg [3:0]  pending_ack  = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as #618-#623's own.
    reg        armed = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ── Real, single fixed upstream direction -- decoded, not a mask,
    // unchanged from v1. Only values 0-3 are ever real (the widened
    // field's own values 4-7 are real, reserved headroom, matching
    // nano's own convention). ──
    wire sel_n = arrived_n && (upstream_dir == 3'd0);
    wire sel_s = arrived_s && (upstream_dir == 3'd1);
    wire sel_e = arrived_e && (upstream_dir == 3'd2);
    wire sel_w = arrived_w && (upstream_dir == 3'd3);
    wire any_upstream_arrived = sel_n | sel_s | sel_e | sel_w;
    wire [31:0] upstream_val = (sel_n ? data_in_n : 32'h0) |
                               (sel_s ? data_in_s : 32'h0) |
                               (sel_e ? data_in_e : 32'h0) |
                               (sel_w ? data_in_w : 32'h0);

    // ── Real, unchanged from v1: the found-not-assumed `consumed`
    // bug guard -- see this file's own real header for why it's
    // necessary. Real, necessary extension: both real capture paths
    // also gated on effective_armed/!program_in (#617's own real
    // "inactive = zero effect" principle, extended here to a
    // genuinely two-path core for the first time). ──
    reg consumed = 1'b0;

    wire capture_reference = any_upstream_arrived && !consumed && !ref_valid &&
                             !effective_freeze && effective_armed && !program_in;
    wire capture_compare   = any_upstream_arrived && !consumed && ref_valid && !data_valid &&
                             !effective_freeze && effective_armed && !program_in;
    wire capture_now       = capture_reference || capture_compare;

    assign ack_out_n = capture_now && sel_n;
    assign ack_out_s = capture_now && sel_s;
    assign ack_out_e = capture_now && sel_e;
    assign ack_out_w = capture_now && sel_w;

    // ── THE CORE — real, unchanged from v1: a genuine two's-complement
    // 3-way outcome. ──
    wire signed [31:0] signed_val = upstream_val;
    wire signed [31:0] signed_ref = ref_value;
    wire is_low   = (signed_val <  signed_ref);
    wire is_equal = (signed_val == signed_ref);
    wire is_high  = (signed_val >  signed_ref);

    wire outcome_value_source = (is_low  ? value_source_low  :
                                  is_equal ? value_source_equal :
                                             value_source_high);
    wire [6:0] outcome_fixed_value = (is_low  ? fixed_value_low  :
                                       is_equal ? fixed_value_equal :
                                                  fixed_value_high);
    wire outcome_emit = (is_low  ? emit_low  :
                          is_equal ? emit_equal :
                                     emit_high);
    wire [5:0] outcome_route = (is_low  ? route_low  :
                                 is_equal ? route_equal :
                                            route_high);

    wire [31:0] outcome_out_value = outcome_value_source ? {25'h0, outcome_fixed_value}
                                                           : upstream_val;

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!active_route[0] || ready_in_n) &&
                             (!active_route[1] || ready_in_s) &&
                             (!active_route[2] || ready_in_e) &&
                             (!active_route[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (active_route[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack       & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #720: NO addon chain here at all — the carrier
    // already provides one, shared across whichever core is active. ──
    assign data_out_n = out_buffer;
    assign data_out_s = out_buffer;
    assign data_out_e = out_buffer;
    assign data_out_w = out_buffer;

    assign ready_out = effective_armed && !effective_freeze && !data_valid && ref_valid;
    assign status_data_valid = data_valid;

    // ── points.md #617: real, targeted programming channel — real,
    // necessary 4-bit ID width (16 real slots), the first core where
    // FIELD COUNT (15 real fields) forced this rather than field
    // WIDTH. id at [23:20], word at [19:0] -- same real "ID sits
    // directly above its own data payload" principle every other
    // core's own layout already follows, just wider here. ──
    localparam [3:0] PROG_ID_UPSTREAM_DIR       = 4'd0;
    localparam [3:0] PROG_ID_VALUE_SOURCE_LOW   = 4'd1;
    localparam [3:0] PROG_ID_VALUE_SOURCE_EQUAL = 4'd2;
    localparam [3:0] PROG_ID_VALUE_SOURCE_HIGH  = 4'd3;
    localparam [3:0] PROG_ID_FIXED_VALUE_LOW    = 4'd4;
    localparam [3:0] PROG_ID_FIXED_VALUE_EQUAL  = 4'd5;
    localparam [3:0] PROG_ID_FIXED_VALUE_HIGH   = 4'd6;
    localparam [3:0] PROG_ID_EMIT_LOW           = 4'd7;
    localparam [3:0] PROG_ID_EMIT_EQUAL         = 4'd8;
    localparam [3:0] PROG_ID_EMIT_HIGH          = 4'd9;
    localparam [3:0] PROG_ID_ROUTE_LOW          = 4'd10;
    localparam [3:0] PROG_ID_ROUTE_EQUAL        = 4'd11;
    localparam [3:0] PROG_ID_ROUTE_HIGH         = 4'd12;
    localparam [3:0] PROG_ID_ROLLING_MODE       = 4'd13;
    localparam [3:0] PROG_ID_COMPLETE           = 4'd15;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [3:0]  prog_id   = prog_data_val[23:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            upstream_dir        <= 3'h0;
            value_source_low    <= 1'b0; value_source_equal <= 1'b0; value_source_high <= 1'b0;
            fixed_value_low     <= 7'h0; fixed_value_equal  <= 7'h0; fixed_value_high  <= 7'h0;
            emit_low            <= 1'b0; emit_equal         <= 1'b0; emit_high         <= 1'b0;
            route_low           <= 6'h0; route_equal        <= 6'h0; route_high        <= 6'h0;
            rolling_mode        <= 1'b0;
            ref_value            <= 32'h0;
            ref_valid            <= 1'b0;
            out_buffer           <= 32'h0;
            data_valid           <= 1'b0;
            active_route         <= 6'h0;
            pending_ack          <= 4'h0;
            consumed             <= 1'b0;
            armed                <= 1'b0;
            program_done_r       <= 1'b0;
        end else if (cfg_valid) begin
            upstream_dir        <= cfg_data[2:0];
            value_source_low    <= cfg_data[3];
            value_source_equal  <= cfg_data[4];
            value_source_high   <= cfg_data[5];
            fixed_value_low     <= cfg_data[12:6];
            fixed_value_equal   <= cfg_data[19:13];
            fixed_value_high    <= cfg_data[26:20];
            emit_low             <= cfg_data[27];
            emit_equal           <= cfg_data[28];
            emit_high            <= cfg_data[29];
            route_low            <= cfg_data[35:30];
            route_equal          <= cfg_data[41:36];
            route_high           <= cfg_data[47:42];
            rolling_mode         <= cfg_data[48];
            // ── Real release, unchanged from v1: reprogramming
            // discards the held reference and any in-flight offer --
            // see v1's own real, explicitly-flagged judgment call. ──
            ref_value             <= 32'h0;
            ref_valid             <= 1'b0;
            data_valid            <= 1'b0;
            pending_ack           <= 4'h0;
            consumed              <= 1'b0;
            armed                 <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_UPSTREAM_DIR:       upstream_dir       <= prog_word[2:0];
                PROG_ID_VALUE_SOURCE_LOW:   value_source_low   <= prog_word[0];
                PROG_ID_VALUE_SOURCE_EQUAL: value_source_equal <= prog_word[0];
                PROG_ID_VALUE_SOURCE_HIGH:  value_source_high  <= prog_word[0];
                PROG_ID_FIXED_VALUE_LOW:    fixed_value_low    <= prog_word[6:0];
                PROG_ID_FIXED_VALUE_EQUAL:  fixed_value_equal  <= prog_word[6:0];
                PROG_ID_FIXED_VALUE_HIGH:   fixed_value_high   <= prog_word[6:0];
                PROG_ID_EMIT_LOW:           emit_low           <= prog_word[0];
                PROG_ID_EMIT_EQUAL:         emit_equal         <= prog_word[0];
                PROG_ID_EMIT_HIGH:          emit_high          <= prog_word[0];
                PROG_ID_ROUTE_LOW:          route_low          <= prog_word[5:0];
                PROG_ID_ROUTE_EQUAL:        route_equal        <= prog_word[5:0];
                PROG_ID_ROUTE_HIGH:         route_high         <= prog_word[5:0];
                PROG_ID_ROLLING_MODE:       rolling_mode       <= prog_word[0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_reference) begin
                ref_value <= upstream_val;
                ref_valid <= 1'b1;
            end else if (capture_compare) begin
                if (outcome_emit) begin
                    out_buffer   <= outcome_out_value;
                    active_route <= outcome_route;
                    data_valid   <= 1'b1;
                end
                if (rolling_mode) begin
                    ref_value <= upstream_val;
                end
            end

            if (capture_now) begin
                consumed <= 1'b1;
            end else if (!any_upstream_arrived) begin
                consumed <= 1'b0;
            end

            if (offer_draining) begin
                data_valid <= 1'b0;
            end

            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// branch_cell_v4s.v -- the sub-family (fixed-latency, no ack) branch. Completes the v4s cell set.
//
// Alan's call (4 Oct 2026, after #934 showed flex-at-32-bits-with-the-handshake-tied-off behaves exactly like sub on 12 of 12
// shared cells): "you can use the branch v4sa as the basis for the v4s version, a slight change but it completes the picture
// for the v4s (sub) set of cell types." So this is branch_cell_v4sa.v with EXACTLY the transformation every other v4s cell
// already shows against its v4sa twin (read from adder_cell_v4s vs adder_cell_v4sa, not assumed):
//   - freeze_in, ack_out, ack_in_1, ack_in_2 and the WIDTH parameter are gone (fixed 32 bits);
//   - the pending_1 / pending_2 hold registers and the `busy` gate are gone: nothing is held waiting for an ack;
//   - the output is a plain pipeline stage: out_buffer is registered every cycle, and each output's valid is a one-cycle
//     registered pulse -- valid_out_N <= armed && real_event && target_N  (one cycle of latency, like every v4s cell).
// Everything about WHAT the cell decides is unchanged from branch_cell_v4sa.v: two dedicated inputs each runtime-selectable
// as fixed (held, reloaded by its own valid) or flowing; the 3-way signed compare of in1 against in2; ONE shared emit_source
// (fixed constant / in1 / in2 / diff = in1 - in2); per-outcome routing to out1, out2, both or neither.
//
// cfg_data field map (identical to branch_cell_v4sa.v):
//   [0] in1_fixed_mode   [1] in2_fixed_mode   [3:2] emit_source (00 fixed, 01 in1, 10 in2, 11 diff)
//   [5:4] route_low   [7:6] route_equal   [9:8] route_high   -- each: bit0 = out1, bit1 = out2 (neither = swallow)
// cfg_emit_fixed_value[31:0]: its own port (does not fit alongside everything else in one 32-bit cfg_data).
//
// Fixed-latency contract (same as the rest of the family): no backpressure. The caller must present rounds no faster than it
// wants results, and converging paths must be latency-matched; a round routed to neither output simply produces no pulse.
`default_nettype none
`timescale 1ns / 1ps

module branch_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,
    input  wire [31:0]  cfg_emit_fixed_value,

    input  wire [31:0]  in1_data,
    input  wire         in1_valid,
    input  wire [31:0]  in2_data,
    input  wire         in2_valid,

    output wire [31:0]  data_out_1,
    output wire         valid_out_1,
    output wire [31:0]  data_out_2,
    output wire         valid_out_2
);

    reg        in1_fixed_mode = 1'b0;
    reg        in2_fixed_mode = 1'b0;
    reg [1:0]  emit_source    = 2'b00;
    reg [1:0]  route_low      = 2'b00;
    reg [1:0]  route_equal    = 2'b00;
    reg [1:0]  route_high     = 2'b00;
    reg        armed          = 1'b0;

    reg [31:0] held1_reg    = 32'h0;
    reg [31:0] held2_reg    = 32'h0;
    reg        has_loaded_1 = 1'b0;
    reg        has_loaded_2 = 1'b0;

    reg [31:0] out_buffer    = 32'h0;
    reg        valid_out_1_r = 1'b0;
    reg        valid_out_2_r = 1'b0;

    // The value actually compared this cycle: the live input if flowing, the stored register if fixed.
    wire [31:0] live1 = in1_fixed_mode ? held1_reg : in1_data;
    wire [31:0] live2 = in2_fixed_mode ? held2_reg : in2_data;

    // A "round" is ready once both sides have a usable value THIS cycle: a fixed side once it has ever been loaded, a flowing
    // side only on the cycle its own valid fires.
    wire in1_ready_now = in1_fixed_mode ? has_loaded_1 : in1_valid;
    wire in2_ready_now = in2_fixed_mode ? has_loaded_2 : in2_valid;
    wire real_event    = in1_ready_now && in2_ready_now;

    wire signed [31:0] signed1 = live1;
    wire signed [31:0] signed2 = live2;
    wire is_low   = (signed1 <  signed2);
    wire is_equal = (signed1 == signed2);

    wire [1:0] active_route = is_low ? route_low : is_equal ? route_equal : route_high;
    wire target_1 = active_route[0];
    wire target_2 = active_route[1];

    wire [31:0] diff_val = live1 + (~live2) + 1'b1;     // in1 - in2, same convention as adder_cell_v4s's subtract_mode

    wire [31:0] emit_val = (emit_source == 2'b00) ? cfg_emit_fixed_value :
                           (emit_source == 2'b01) ? live1 :
                           (emit_source == 2'b10) ? live2 :
                                                    diff_val;

    assign data_out_1  = out_buffer;
    assign data_out_2  = out_buffer;
    assign valid_out_1 = valid_out_1_r;
    assign valid_out_2 = valid_out_2_r;

    always @(posedge clk) begin
        if (rst) begin
            in1_fixed_mode <= 1'b0;
            in2_fixed_mode <= 1'b0;
            emit_source    <= 2'b00;
            route_low      <= 2'b00;
            route_equal    <= 2'b00;
            route_high     <= 2'b00;
            armed          <= 1'b0;
            held1_reg      <= 32'h0;
            held2_reg      <= 32'h0;
            has_loaded_1   <= 1'b0;
            has_loaded_2   <= 1'b0;
            out_buffer     <= 32'h0;
            valid_out_1_r  <= 1'b0;
            valid_out_2_r  <= 1'b0;
        end else if (cfg_valid) begin
            in1_fixed_mode <= cfg_data[0];
            in2_fixed_mode <= cfg_data[1];
            emit_source    <= cfg_data[3:2];
            route_low      <= cfg_data[5:4];
            route_equal    <= cfg_data[7:6];
            route_high     <= cfg_data[9:8];
            armed          <= 1'b1;
            has_loaded_1   <= 1'b0;   // a reconfigure is a fresh start -- reload required
            has_loaded_2   <= 1'b0;
            valid_out_1_r  <= 1'b0;
            valid_out_2_r  <= 1'b0;
        end else begin
            // Loading a fixed input is a silent side effect: it changes what future comparisons use, but is not an offer.
            if (in1_fixed_mode && in1_valid) begin
                held1_reg    <= in1_data;
                has_loaded_1 <= 1'b1;
            end
            if (in2_fixed_mode && in2_valid) begin
                held2_reg    <= in2_data;
                has_loaded_2 <= 1'b1;
            end
            // Pipeline stage: data every cycle, one registered valid pulse per targeted output. Routed to neither: the round is
            // consumed (held state above already updated) but nothing is offered downstream.
            out_buffer    <= emit_val;
            valid_out_1_r <= armed && real_event && target_1;
            valid_out_2_r <= armed && real_event && target_2;
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// branch_cell_v4sa.v -- points.md #918: the real Flex-Sub redesign of branch,
// resolving the architectural tension flagged since #898 (branch being the
// one cell whose whole job is a runtime decision). Designed through a full
// conversation with Alan, confirming the real original (branch_cell_v4c.v)
// first, then building the new shape together, point by point.
//
// Real differences from the original, each a deliberate, discussed choice:
//   - TWO dedicated inputs (in1, in2), each INDEPENDENTLY runtime-selectable
//     as fixed (held, reloaded via its own valid pulse, reused every firing)
//     or flowing (a fresh value expected every firing) -- matching ram_cell_
//     v4sa's own fixed/flowing choice, applied per-input here. This gives a
//     real new capability the original never had: comparing two genuinely
//     live streams against each other, not just one value against a held
//     reference.
//   - The 3-way signed compare (low/equal/high) is unchanged in spirit.
//   - emit_source is ONE SHARED, config-time choice (fixed constant / in1 /
//     in2 / diff), not independently chosen per outcome the way the
//     original's value_source_low/equal/high were -- a real, deliberate
//     simplification Alan chose once per-outcome value selection was found
//     to add real complexity for comparatively little value.
//   - diff = in1 - in2, true signed two's-complement subtraction, same
//     convention as adder_cell_v4sa.v's own subtract_mode.
//   - Per-outcome ROUTING (low/equal/high each independently choose out1,
//     out2, both, or neither) replaces the original's independent per-
//     outcome emit-enable AND routing-mask with one thing: routing to
//     "neither" IS the emit-disable case, for free -- no separate enable bit
//     needed. The original's routing could ALSO fan out across up to 4 real
//     cardinal directions simultaneously per outcome; here it is narrowed to
//     exactly 2 fixed ports, each independently selectable per outcome
//     (every real combination: out1 only, out2 only, both, or neither).
//   - ack/freeze: standard Flex-Sub shape. ONE shared ack_out gates
//     acceptance of a new (in1, in2) round -- the same "one ack per atomic
//     operand pair" principle adder_cell_v4sa.v's own single ack_out already
//     established, not two separate input acks. TWO independent output
//     pending/ack pairs, mirroring router_cell_v4sa.v's own per-output
//     handshake exactly, since a given firing may target either, both, or
//     neither output.
//
// cfg_data field map:
//   [0]   in1_fixed_mode
//   [1]   in2_fixed_mode
//   [3:2] emit_source   -- 00=fixed constant, 01=in1, 10=in2, 11=diff(in1-in2)
//   [5:4] route_low     -- bit0=out1, bit1=out2 (any combination, including neither)
//   [7:6] route_equal
//   [9:8] route_high
// cfg_emit_fixed_value[WIDTH-1:0]: its own port, same reason sequencer_cell_v4s.v
// and ram_cell_v4s.v each needed one -- does not fit alongside everything
// else in one 32-bit cfg_data.
`default_nettype none
`timescale 1ns / 1ps

module branch_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,
    input  wire [WIDTH-1:0] cfg_emit_fixed_value,

    input  wire [WIDTH-1:0]  in1_data,
    input  wire               in1_valid,
    input  wire [WIDTH-1:0]  in2_data,
    input  wire               in2_valid,
    output wire                ack_out,     // ONE shared ack, gates a new (in1,in2) round

    output wire [WIDTH-1:0]  data_out_1,
    output wire               valid_out_1,
    input  wire                ack_in_1,

    output wire [WIDTH-1:0]  data_out_2,
    output wire               valid_out_2,
    input  wire                ack_in_2
);

    reg        in1_fixed_mode = 1'b0;
    reg        in2_fixed_mode = 1'b0;
    reg [1:0]  emit_source    = 2'b00;
    reg [1:0]  route_low      = 2'b00;
    reg [1:0]  route_equal    = 2'b00;
    reg [1:0]  route_high     = 2'b00;
    reg        armed          = 1'b0;

    reg [WIDTH-1:0] held1_reg = {WIDTH{1'b0}};
    reg [WIDTH-1:0] held2_reg = {WIDTH{1'b0}};
    reg             has_loaded_1 = 1'b0;
    reg             has_loaded_2 = 1'b0;

    reg pending_1 = 1'b0;
    reg pending_2 = 1'b0;
    reg [WIDTH-1:0] out_buffer = {WIDTH{1'b0}};

    // ── Which value is actually used for this cycle's comparison -- the
    // live input if flowing, the stored register if fixed. ──────────────
    wire [WIDTH-1:0] live1 = in1_fixed_mode ? held1_reg : in1_data;
    wire [WIDTH-1:0] live2 = in2_fixed_mode ? held2_reg : in2_data;

    // ── A "round" is ready once both sides have a usable value THIS
    // cycle: a fixed side is ready once it has ever been loaded; a flowing
    // side is ready only on the cycle its own valid fires. ──────────────
    wire in1_ready_now = in1_fixed_mode ? has_loaded_1 : in1_valid;
    wire in2_ready_now = in2_fixed_mode ? has_loaded_2 : in2_valid;
    wire real_event    = in1_ready_now && in2_ready_now;

    wire busy = pending_1 || pending_2;
    assign ack_out = armed && !busy && !freeze_in;

    // ── The real 3-way signed compare -- unchanged in spirit from the
    // original's is_low/is_equal/is_high. ────────────────────────────────
    wire signed [WIDTH-1:0] signed1 = live1;
    wire signed [WIDTH-1:0] signed2 = live2;
    wire is_low   = (signed1 <  signed2);
    wire is_equal = (signed1 == signed2);
    wire is_high  = (signed1 >  signed2);

    wire [1:0] active_route = is_low ? route_low : is_equal ? route_equal : route_high;
    wire target_1 = active_route[0];
    wire target_2 = active_route[1];

    // ── diff = in1 - in2, true signed subtraction, same convention as
    // adder_cell_v4sa.v's own subtract_mode. ─────────────────────────────
    wire [WIDTH-1:0] diff_val = live1 + (~live2) + 1'b1;

    wire [WIDTH-1:0] emit_val = (emit_source == 2'b00) ? cfg_emit_fixed_value :
                                (emit_source == 2'b01) ? live1 :
                                (emit_source == 2'b10) ? live2 :
                                                          diff_val;

    assign data_out_1  = out_buffer;
    assign data_out_2  = out_buffer;
    assign valid_out_1 = pending_1;
    assign valid_out_2 = pending_2;

    always @(posedge clk) begin
        if (rst) begin
            in1_fixed_mode <= 1'b0;
            in2_fixed_mode <= 1'b0;
            emit_source    <= 2'b00;
            route_low      <= 2'b00;
            route_equal    <= 2'b00;
            route_high     <= 2'b00;
            armed          <= 1'b0;
            held1_reg      <= {WIDTH{1'b0}};
            held2_reg      <= {WIDTH{1'b0}};
            has_loaded_1   <= 1'b0;
            has_loaded_2   <= 1'b0;
            pending_1      <= 1'b0;
            pending_2      <= 1'b0;
            out_buffer     <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            in1_fixed_mode <= cfg_data[0];
            in2_fixed_mode <= cfg_data[1];
            emit_source    <= cfg_data[3:2];
            route_low      <= cfg_data[5:4];
            route_equal    <= cfg_data[7:6];
            route_high     <= cfg_data[9:8];
            armed          <= 1'b1;
            has_loaded_1   <= 1'b0;   // a reconfigure is a fresh start -- reload required
            has_loaded_2   <= 1'b0;
            pending_1      <= 1'b0;
            pending_2      <= 1'b0;
        end else if (!freeze_in) begin
            // Loading a fixed input is a real, silent side effect -- same
            // reasoning as nano_cell_v4sa.v's own load_hold: it changes what
            // future comparisons use, but is not itself an offer.
            if (in1_fixed_mode && in1_valid) begin
                held1_reg    <= in1_data;
                has_loaded_1 <= 1'b1;
            end
            if (in2_fixed_mode && in2_valid) begin
                held2_reg    <= in2_data;
                has_loaded_2 <= 1'b1;
            end

            // Each output clears independently on its own ack -- real,
            // separate handshakes, same shape as router_cell_v4sa.v.
            if (pending_1 && ack_in_1) pending_1 <= 1'b0;
            if (pending_2 && ack_in_2) pending_2 <= 1'b0;

            // A new round is only captured once NEITHER output is still
            // busy (pre-edge busy, same priority discipline every other
            // v4sa cell uses) -- conservative: gates on both outputs being
            // free regardless of which the upcoming outcome will actually
            // target, since the real target is only known after the
            // compare itself runs.
            if (!busy && real_event) begin
                out_buffer <= emit_val;
                if (target_1) pending_1 <= 1'b1;
                if (target_2) pending_2 <= 1'b1;
                // target_1==target_2==0 (routed to neither): a real, valid
                // "swallow silently" case -- the round is consumed (fixed
                // inputs' own has_loaded/held state already updated above;
                // a flowing input's own round is simply over) but nothing
                // is offered downstream at all.
            end
        end
    end

endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// compare_cell_v4.v — points.md #617/#620: the THIRD real "unified
// carrier" core, following `adder_cell_v4.v` (#618, two-stage A/B
// capture) and `ram_cell_v4.v` (#619, single-arrival, no real
// computation). This core is a third genuinely distinct combination:
// single-arrival capture (like ram) WITH a real computation against a
// configured value (like adder has real computation, but two-stage)
// -- confirming the shell template keeps generalizing across real,
// different core shapes, not just the two already tried.
//
// Real core logic CLONED from compare_cell_v1.v unchanged (the
// signed `>=` comparison against a configured threshold, the doubly-
// full single-capture guard). Same real shell additions as `#618`/
// `#619`, per Alan's own precise 5-point breakdown (`#617`):
//   1. programming: real, targeted program_in/PROG_ID channel.
//   2. shift/nibble_mask/lane: the same real, already-proven 3-addon
//      chain, wired identically.
//   3. 6-way cardinality: real field-width headroom only.
//   4. ack all around: the programming channel's own real,
//      independent per-direction ack.
//   5. `active`: the same real, explicit port.
//
// REAL, NOTEWORTHY DIFFERENCE FROM THE PRIOR TWO CORES: this one's
// real field total (6+6+32+20 = 64 bits) fits EXACTLY in v1's own
// original 64-bit cfg_data -- no widening needed, unlike ram_cell_v4.v
// (#619, needed 80 bits). A real, useful data point: the unified
// carrier's own real cost in bits genuinely varies per core, not a
// fixed tax every core pays identically.
//
// REAL, NECESSARY PROTOCOL ADAPTATION, same real reason as ram's own
// init_data (#619): `threshold` is 32 bits, too wide for one real
// targeted PROG_ID write alongside its own 3-bit ID -- split into two
// real half-writes (`PROG_ID_THRESHOLD_LOW`/`_HIGH`). REAL, DELIBERATE
// SIMPLIFICATION versus ram's own real "explicit commit" pattern:
// `threshold` is pure CONFIGURATION, never itself offered downstream
// the way ram's `data_reg` is -- each half-write takes effect
// immediately, no separate commit trigger needed, since there's no
// real "currently held, must not be silently corrupted" state at risk
// here the way there was for ram (#619's own real bug).
//
// REAL, HONEST SCOPE, matching `#618`/`#619`'s own stated deferrals:
// `is_command_cell` mode NOT included (parked as a possible 9th-core
// question, per this session's own later discussion).
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   downstream_mask   — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  upstream_mask     — one-hot(s), N/S/E/W real + 2 reserved
//   [43:12] threshold         — the configured reference (32-bit signed)
//   [63:44] addon_config      — 20 bits, SAME real layout as
//                               unicell_super_v3.v's own real addon_config
`default_nettype none
`timescale 1ns / 1ps

module compare_cell_v4 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: the real, targeted programming channel, same
    // real shape as #618/#619's own. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid
);

    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg signed [31:0] threshold = 32'sh0;
    reg [19:0] addon_config    = 20'h0;

    reg [31:0] out_buffer  = 32'h0;
    reg        data_valid  = 1'b0;
    reg [3:0]  pending_ack = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as #618/#619's own.
    reg        armed       = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    wire sel_n = arrived_n && upstream_mask[0];
    wire sel_s = arrived_s && upstream_mask[1];
    wire sel_e = arrived_e && upstream_mask[2];
    wire sel_w = arrived_w && upstream_mask[3];
    wire any_upstream_arrived = sel_n | sel_s | sel_e | sel_w;
    wire signed [31:0] upstream_val = (sel_n ? data_in_n : 32'h0) |
                                      (sel_s ? data_in_s : 32'h0) |
                                      (sel_e ? data_in_e : 32'h0) |
                                      (sel_w ? data_in_w : 32'h0);

    wire capture_now = any_upstream_arrived && !data_valid && !effective_freeze &&
                       effective_armed && !program_in;

    assign ack_out_n = capture_now && sel_n;
    assign ack_out_s = capture_now && sel_s;
    assign ack_out_e = capture_now && sel_e;
    assign ack_out_w = capture_now && sel_w;

    // ── THE CORE — real, unchanged from v1: a genuine two's-complement
    // comparison against the configured threshold. ──
    wire result_bit = (upstream_val >= threshold);

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #617: the real, three-addon chain, wired identically
    // to #618/#619's own. ──
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(out_buffer), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    assign ready_out = effective_armed && !effective_freeze && !data_valid;
    assign status_data_valid = data_valid;

    // ── points.md #617: real, targeted programming channel — same
    // real priority-select shape as #618/#619's own. threshold split
    // across two real half-writes, same real reason as ram's own
    // init_data (#619) -- but real, deliberately simpler here: no
    // separate commit trigger needed, since threshold is pure config,
    // not a currently-held, offer-bound value. ──
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_THRESHOLD_LOW   = 3'd2;
    localparam [2:0] PROG_ID_THRESHOLD_HIGH  = 3'd3;
    localparam [2:0] PROG_ID_ADDON_CONFIG    = 3'd4;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            out_buffer      <= 32'h0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            downstream_mask <= 6'h0;
            upstream_mask   <= 6'h0;
            threshold       <= 32'sh0;
            addon_config    <= 20'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            threshold       <= cfg_data[43:12];
            addon_config    <= cfg_data[63:44];
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask   <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask     <= prog_word[5:0];
                PROG_ID_THRESHOLD_LOW:   threshold[15:0]   <= prog_word[15:0];
                PROG_ID_THRESHOLD_HIGH:  threshold[31:16]  <= prog_word[15:0];
                PROG_ID_ADDON_CONFIG:    addon_config      <= prog_word[19:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_now) begin
                out_buffer <= {31'h0, result_bit};
                data_valid <= 1'b1;
            end

            if (offer_draining) begin
                data_valid <= 1'b0;
            end

            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4c.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// compare_cell_v4c.v — points.md #720: the "c" (carrier) variant of
// compare_cell_v4.v. Same real reasoning as adder_cell_v4c.v's/ram_
// cell_v4c.v's own headers -- the carrier's whole design concept is
// to hold common functionality centrally, and this core's own
// internal 3-addon chain duplicates exactly what the carrier itself
// now provides once, shared. compare_cell_v4.v itself is UNCHANGED,
// still the real, proven, standalone core.
//
// Real, honest scope of this file's own changes from v4:
//   1. The internal addon chain is REMOVED entirely -- data_out_n/s/
//      e/w now come directly from out_buffer, the real comparison
//      result.
//   2. addon_config (20 bits) is removed from cfg_data's own field
//      map, the register, and the PROG_ID_ADDON_CONFIG case -- cfg_
//      data KEEPS its original 64-bit width; those bits are now
//      genuinely reserved.
//   3. Same real config-off-shell reasoning as the other _v4c files:
//      downstream_mask/upstream_mask/threshold STAY real registers
//      (this cell's live-programming channel genuinely needs them
//      independently writable); the real fix lives at the carrier's
//      own shell level -- feed cfg_data from stable core_config, not
//      transient incoming_config.
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   downstream_mask   — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  upstream_mask     — one-hot(s), N/S/E/W real + 2 reserved
//   [43:12] threshold         — the configured reference (32-bit signed)
//   [63:44] reserved          — 20 bits (addon_config's own old home,
//                               now genuinely free)

`default_nettype none
`timescale 1ns / 1ps

module compare_cell_v4c #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: the real, targeted programming channel, same
    // real shape as #618/#619's own. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid
);

    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg signed [31:0] threshold = 32'sh0;

    reg [31:0] out_buffer  = 32'h0;
    reg        data_valid  = 1'b0;
    reg [3:0]  pending_ack = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as #618/#619's own.
    reg        armed       = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    wire sel_n = arrived_n && upstream_mask[0];
    wire sel_s = arrived_s && upstream_mask[1];
    wire sel_e = arrived_e && upstream_mask[2];
    wire sel_w = arrived_w && upstream_mask[3];
    wire any_upstream_arrived = sel_n | sel_s | sel_e | sel_w;
    wire signed [31:0] upstream_val = (sel_n ? data_in_n : 32'h0) |
                                      (sel_s ? data_in_s : 32'h0) |
                                      (sel_e ? data_in_e : 32'h0) |
                                      (sel_w ? data_in_w : 32'h0);

    wire capture_now = any_upstream_arrived && !data_valid && !effective_freeze &&
                       effective_armed && !program_in;

    assign ack_out_n = capture_now && sel_n;
    assign ack_out_s = capture_now && sel_s;
    assign ack_out_e = capture_now && sel_e;
    assign ack_out_w = capture_now && sel_w;

    // ── THE CORE — real, unchanged from v1: a genuine two's-complement
    // comparison against the configured threshold. ──
    wire result_bit = (upstream_val >= threshold);

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #720: NO addon chain here at all — the carrier
    // already provides one, shared across whichever core is active.
    // data_out_n/s/e/w are the real comparison result, directly. ──
    assign data_out_n = out_buffer;
    assign data_out_s = out_buffer;
    assign data_out_e = out_buffer;
    assign data_out_w = out_buffer;

    assign ready_out = effective_armed && !effective_freeze && !data_valid;
    assign status_data_valid = data_valid;

    // ── points.md #617: real, targeted programming channel — same
    // real priority-select shape as #618/#619's own. threshold split
    // across two real half-writes, same real reason as ram's own
    // init_data (#619) -- but real, deliberately simpler here: no
    // separate commit trigger needed, since threshold is pure config,
    // not a currently-held, offer-bound value. ──
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_THRESHOLD_LOW   = 3'd2;
    localparam [2:0] PROG_ID_THRESHOLD_HIGH  = 3'd3;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            out_buffer      <= 32'h0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            downstream_mask <= 6'h0;
            upstream_mask   <= 6'h0;
            threshold       <= 32'sh0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            threshold       <= cfg_data[43:12];
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask   <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask     <= prog_word[5:0];
                PROG_ID_THRESHOLD_LOW:   threshold[15:0]   <= prog_word[15:0];
                PROG_ID_THRESHOLD_HIGH:  threshold[31:16]  <= prog_word[15:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_now) begin
                out_buffer <= {31'h0, result_bit};
                data_valid <= 1'b1;
            end

            if (offer_draining) begin
                data_valid <= 1'b0;
            end

            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// compare_cell_v4s.v -- stripped version of compare_cell_v4c.v's real function
// (value vs a configured, static threshold), same mechanical strip as
// adder_cell_v4s.v: no addon chain (compare never had one used at this level
// anyway), no cardinal routing/masks, no ack, fixed one-cycle latency, boot-load
// config only. See sub/README.md and adder_cell_v4s.v for the family's shared
// rationale, unchanged here.
//
// The real function, unchanged from compare_cell_v4c: result = (data_in >=
// threshold), a genuine two's-complement signed comparison, output zero-extended
// to 32 bits (matching the original's own `{31'h0, result_bit}` convention).
//
// cfg_data field map:
//   [31:0] threshold -- the configured signed reference value, full 32 bits
//                        (compare_cell_v4c packed this alongside masks in a
//                        64-bit word; with no masks left here, it gets the
//                        whole cfg_data word to itself)
`default_nettype none
`timescale 1ns / 1ps

module compare_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,

    input  wire [31:0]  data_in,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg signed [31:0] threshold   = 32'sh0;
    reg               armed       = 1'b0;
    reg        [31:0] out_buffer  = 32'h0;
    reg               valid_out_r = 1'b0;

    // ── The real comparison -- unchanged from compare_cell_v4c ──────────
    wire result_bit = ($signed(data_in) >= threshold);

    assign data_out  = out_buffer;
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            threshold   <= 32'sh0;
            armed       <= 1'b0;
            out_buffer  <= 32'h0;
            valid_out_r <= 1'b0;
        end else if (cfg_valid) begin
            threshold   <= cfg_data;
            armed       <= 1'b1;
            valid_out_r <= 1'b0;
        end else begin
            out_buffer  <= {31'h0, result_bit};
            valid_out_r <= armed && valid_in;
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// compare_cell_v4sa.v -- points.md #912: the Flex-Sub shape (ack+freeze per
// #906, real WIDTH parameter per #909/#910) applied to compare -- a third
// cell with genuine per-cycle arithmetic (a signed comparison is typically
// implemented as a subtraction under the hood, the same ALU primitive
// adder/accumulator use), continuing the ALU-ratio story #908-#911 built.
//
// The real function, unchanged from compare_cell_v4c/v4s: result = (data_in
// >= threshold), a genuine two's-complement signed comparison, output
// zero-extended to the full bus width (matching the original's own
// `{31'h0, result_bit}` convention, now `{WIDTH-1{1'b0}, result_bit}`).
//
// WIDTH note (ledger #971, Alan): the threshold arrives on its OWN port, `cfg_threshold`, WIDTH bits wide, like the branch cell's `cfg_emit_fixed_value` -- the
// trend in the flex family is that when a cell needs two config parts it has two ports. It used to be read from cfg_data[WIDTH-1:0], and cfg_data is a fixed 32-bit
// word, so above 32 bits the upper threshold bits were undefined (x) and the result was x. `cfg_data` is now unused (kept for the uniform port shape).
//
// ack/freeze: identical shape and reasoning to adder_cell_v4sa.v/
// accumulator_cell_v4sa.v -- standard ready/valid (valid_out stays high until
// ack_in, not a one-shot pulse), freeze_in global and gating the entire
// update including cfg_valid's own effect. See adder_cell_v4sa.v's header for
// the full "why this is not a retreat from physics, not control" reasoning.
//
// Lessons from #906/#911 applied DELIBERATELY from the start here, not
// discovered again through debugging: the testbench for this file settles
// (a real delay) BEFORE clearing any pulse-like input the DUT also samples on
// the same edge -- the exact race class both those entries hit.
`default_nettype none
`timescale 1ns / 1ps

module compare_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,        // unused by this cell (kept for a uniform port shape)
    input  wire [WIDTH-1:0] cfg_threshold, // the threshold, a full WIDTH bits (signed), loaded on cfg_valid

    input  wire [WIDTH-1:0]  data_in,
    input  wire               valid_in,
    output wire                ack_out,     // backward, to whoever feeds data_in

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in       // backward, from the one fixed downstream receiver
);

    reg signed [WIDTH-1:0] threshold   = 0;
    reg                     armed       = 1'b0;
    reg                     pending     = 1'b0;
    reg [WIDTH-1:0]         out_buffer  = {WIDTH{1'b0}};

    // ── The real comparison -- unchanged from compare_cell_v4c/v4s ──────
    wire result_bit = ($signed(data_in) >= threshold);
    wire [WIDTH-1:0] result_ext = {{(WIDTH-1){1'b0}}, result_bit};

    assign data_out  = out_buffer;
    assign valid_out = pending;
    assign ack_out   = armed && !pending && !freeze_in;

    always @(posedge clk) begin
        if (rst) begin
            threshold   <= 0;
            armed       <= 1'b0;
            pending     <= 1'b0;
            out_buffer  <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            threshold   <= cfg_threshold;
            armed       <= 1'b1;
            pending     <= 1'b0;
            out_buffer  <= {WIDTH{1'b0}};
        end else if (!freeze_in) begin
            if (pending) begin
                if (ack_in) pending <= 1'b0;
            end else if (valid_in) begin
                out_buffer <= result_ext;
                pending    <= 1'b1;
            end
        end
    end

endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// latch_cell_v4.v — points.md #617/#623: the FIFTH real "unified
// carrier" core, following `adder`/`ram`/`compare`/`accumulator`
// (#618-#621). Shares `accumulator_cell_v4.v`'s own real
// continuously-live shape (state updates unconditionally, offered
// snapshot refreshes only when free) -- but SET/CLEAR/TOGGLE
// semantics on a single bit, not arithmetic increment/decrement on a
// running total. A genuinely different real STATE MODEL tested
// against the same shell template, not just a different set of
// triggers.
//
// Real core logic CLONED from latch_cell_v1.v unchanged, INCLUDING its
// own real, documented history, faithfully preserved, not silently
// dropped:
//   - the real `#295` bug fix: only an arrival that actually CARRIES a
//     1 on set_dir triggers a set (an earlier draft treated ANY
//     arrival as a trigger, misinterpreting a genuinely correct "0"
//     reading as a set).
//   - the real `#522` TOGGLE extension: a third real trigger, flipping
//     the current state rather than forcing one, with real priority
//     CLEAR > SET > TOGGLE when multiple land the same cycle
//     (extending #279/#284's own "explicit host action wins" rule).
//
// Same real shell additions as #618-#621, per Alan's own precise
// 5-point breakdown (#617):
//   1. programming: real, targeted program_in/PROG_ID channel.
//   2. shift/nibble_mask/lane: the same real, already-proven 3-addon
//      chain, applied to the offered {31'h0,out_buffer} expansion --
//      genuinely useful even for a single real bit (invert flips all
//      32 offered bits; shift can relocate which bit position carries
//      the real latch value).
//   3. 6-way cardinality: real field-width headroom only.
//   4. ack all around: the programming channel's own real ack.
//   5. `active`: the same real, explicit port -- REAL, NECESSARY
//      EXTENSION matching `#621`'s own real precedent for
//      accumulator: gates `capture_set`/`capture_clr`/`capture_tog`
//      too, so an inactive cell's own internal latch state genuinely
//      holds rather than silently flipping in the background.
//
// REAL, NOTABLE DATA POINT: this core's own real field total
// (6×4 + 20 = 44 bits) fits comfortably in the original 64-bit
// cfg_data with real, honest room to spare -- no widening needed, a
// fourth real, different answer on this same question (#619 needed
// 80 bits, #620/#621 fit exactly in 64, this one fits with margin).
//
// REAL, HONEST SCOPE, matching #618-#621's own stated deferrals:
// `is_command_cell` mode NOT included (parked as a possible 9th-core
// question).
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   set_dir           — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  clear_dir         — one-hot(s), N/S/E/W real + 2 reserved
//   [17:12] downstream_mask   — one-hot(s), N/S/E/W real + 2 reserved
//   [23:18] toggle_dir        — one-hot(s), N/S/E/W real + 2 reserved
//   [43:24] addon_config      — 20 bits, SAME real layout as
//                               unicell_super_v3.v's own real addon_config
//   [63:44] reserved          — 20 bits, real, honest headroom
`default_nettype none
`timescale 1ns / 1ps

module latch_cell_v4 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: real, targeted programming channel, same real
    // shape as #618-#621's own. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         ready_out,
    output wire         status_latched
);

    reg [5:0] set_dir         = 6'h0;
    reg [5:0] clear_dir       = 6'h0;
    reg [5:0] downstream_mask = 6'h0;
    reg [5:0] toggle_dir      = 6'h0;
    reg [19:0] addon_config   = 20'h0;

    reg latched    = 1'b0;   // ALWAYS correct, unconditional update, never blocked
    reg out_buffer = 1'b0;   // the OFFERED snapshot — stable while a transfer is in flight
    reg data_valid = 1'b0;
    reg [3:0] pending_ack = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as #618-#621's own.
    reg armed = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ── Real, unchanged from v1: set/clear/toggle capture, only the
    // low 4 bits of each now-6-bit direction field are ever wired to a
    // real physical port here (bits [5:4] real, reserved headroom,
    // matching nano's own convention). Real, necessary extension:
    // also gated on effective_armed/!program_in — an inactive or
    // mid-reprogram cell must not silently keep flipping its own
    // internal state in the background (#621's own real precedent). ──
    wire sel_set_n = arrived_n && set_dir[0];
    wire sel_set_s = arrived_s && set_dir[1];
    wire sel_set_e = arrived_e && set_dir[2];
    wire sel_set_w = arrived_w && set_dir[3];
    // Real #295 bug fix, faithfully preserved: only an arrival that
    // actually CARRIES a 1 triggers a set — not just any arrival.
    wire set_arrived_value = (sel_set_n ? data_in_n[0] : 1'b0) |
                             (sel_set_s ? data_in_s[0] : 1'b0) |
                             (sel_set_e ? data_in_e[0] : 1'b0) |
                             (sel_set_w ? data_in_w[0] : 1'b0);
    wire capture_set = (sel_set_n | sel_set_s | sel_set_e | sel_set_w) && set_arrived_value &&
                       !effective_freeze && effective_armed && !program_in;

    wire sel_clr_n = arrived_n && clear_dir[0];
    wire sel_clr_s = arrived_s && clear_dir[1];
    wire sel_clr_e = arrived_e && clear_dir[2];
    wire sel_clr_w = arrived_w && clear_dir[3];
    wire capture_clr = (sel_clr_n | sel_clr_s | sel_clr_e | sel_clr_w) &&
                       !effective_freeze && effective_armed && !program_in;

    // Real #522 TOGGLE extension, faithfully preserved: any real
    // arrival on toggle_dir flips the state, value not checked.
    wire sel_tog_n = arrived_n && toggle_dir[0];
    wire sel_tog_s = arrived_s && toggle_dir[1];
    wire sel_tog_e = arrived_e && toggle_dir[2];
    wire sel_tog_w = arrived_w && toggle_dir[3];
    wire capture_tog = (sel_tog_n | sel_tog_s | sel_tog_e | sel_tog_w) &&
                       !effective_freeze && effective_armed && !program_in;

    assign ack_out_n = (sel_set_n || sel_clr_n || sel_tog_n) && !effective_freeze && effective_armed && !program_in;
    assign ack_out_s = (sel_set_s || sel_clr_s || sel_tog_s) && !effective_freeze && effective_armed && !program_in;
    assign ack_out_e = (sel_set_e || sel_clr_e || sel_tog_e) && !effective_freeze && effective_armed && !program_in;
    assign ack_out_w = (sel_set_w || sel_clr_w || sel_tog_w) && !effective_freeze && effective_armed && !program_in;

    // Real, unchanged priority from v1: CLEAR > SET > TOGGLE.
    wire next_latched = capture_clr ? 1'b0 : capture_set ? 1'b1 : capture_tog ? ~latched : latched;

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #617: the real, three-addon chain, applied to the
    // offered {31'h0,out_buffer} expansion -- genuinely useful even
    // for a single real bit (invert flips all 32 offered bits; shift
    // can relocate which bit position carries the real latch value). ──
    wire [31:0] latch_expanded = {31'h0, out_buffer};
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(latch_expanded), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    assign status_latched = latched;
    // Real, honest gating: an inactive/disarmed cell is never ready --
    // same real convention as #618-#621's own.
    assign ready_out = effective_armed && !effective_freeze;

    // ── points.md #617: real, targeted programming channel — same
    // real priority-select shape as #618-#621's own. Every real field
    // here fits in a single targeted write (no split needed, matching
    // #621's own step_amount case, not #619/#620's wider fields). ──
    localparam [2:0] PROG_ID_SET_DIR         = 3'd0;
    localparam [2:0] PROG_ID_CLEAR_DIR       = 3'd1;
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd2;
    localparam [2:0] PROG_ID_TOGGLE_DIR      = 3'd3;
    localparam [2:0] PROG_ID_ADDON_CONFIG    = 3'd4;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            latched         <= 1'b0;
            out_buffer      <= 1'b0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            set_dir         <= 6'h0;
            clear_dir       <= 6'h0;
            downstream_mask <= 6'h0;
            toggle_dir      <= 6'h0;
            addon_config    <= 20'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            set_dir         <= cfg_data[5:0];
            clear_dir       <= cfg_data[11:6];
            downstream_mask <= cfg_data[17:12];
            toggle_dir      <= cfg_data[23:18];
            addon_config    <= cfg_data[43:24];
            latched         <= 1'b0;
            out_buffer      <= 1'b0;
            data_valid      <= 1'b1;   // live from the first cycle after config
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_SET_DIR:         set_dir         <= prog_word[5:0];
                PROG_ID_CLEAR_DIR:       clear_dir       <= prog_word[5:0];
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_TOGGLE_DIR:      toggle_dir      <= prog_word[5:0];
                PROG_ID_ADDON_CONFIG:    addon_config    <= prog_word[19:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_set || capture_clr || capture_tog) begin
                latched <= next_latched;
            end

            if (pending_ack == 4'h0) begin
                out_buffer <= next_latched;
            end

            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

