    // same real convention as #618-#621's own.
    assign ready_out = effective_armed && !effective_freeze;

    // ── points.md #617: real, targeted programming channel — same
    // real priority-select shape as #618-#621's own. Every real field
    // here fits in a single targeted write (no split needed, matching
    // #621's own step_amount case, not #619/#620's wider fields). ──
    localparam [2:0] PROG_ID_SET_DIR         = 3'd0;
    localparam [2:0] PROG_ID_CLEAR_DIR       = 3'd1;
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd2;
    localparam [2:0] PROG_ID_TOGGLE_DIR      = 3'd3;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            latched         <= 1'b0;
            out_buffer      <= 1'b0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            set_dir         <= 6'h0;
            clear_dir       <= 6'h0;
            downstream_mask <= 6'h0;
            toggle_dir      <= 6'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            set_dir         <= cfg_data[5:0];
            clear_dir       <= cfg_data[11:6];
            downstream_mask <= cfg_data[17:12];
            toggle_dir      <= cfg_data[23:18];
            latched         <= 1'b0;
            out_buffer      <= 1'b0;
            data_valid      <= 1'b1;   // live from the first cycle after config
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_SET_DIR:         set_dir         <= prog_word[5:0];
                PROG_ID_CLEAR_DIR:       clear_dir       <= prog_word[5:0];
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_TOGGLE_DIR:      toggle_dir      <= prog_word[5:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_set || capture_clr || capture_tog) begin
                latched <= next_latched;
            end

            if (pending_ack == 4'h0) begin
                out_buffer <= next_latched;
            end

            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// latch_cell_v4s.v -- stripped version of latch_cell_v4c.v's real function. Same
// wrinkle as accumulator_cell_v4s.v: the original distinguishes SET/CLEAR/TOGGLE
// by which cardinal direction an arrival came from, not by data content -- so
// this becomes three dedicated one-bit event pulses instead of three masks.
//
// One simplification worth stating precisely: the original's SET only actually
// fires when the arriving value's bit 0 is 1 (a real #295 bug fix -- an arrival
// carrying 0 is silently a no-op, functionally IDENTICAL to no request at all).
// So a single `set_in` pulse (asserted = a real set request) is exactly
// equivalent to that original behaviour -- there is no case where the original's
// "arrival with value 0" did anything different from "no arrival," so no separate
// value line is needed here.
//
// Priority CLEAR > SET > TOGGLE, unchanged from the original.
//
// No config fields at all for the core function -- unlike the other v4s cells,
// there is nothing left to configure once direction masks are removed. cfg_valid
// still exists purely to arm the cell (gate it until boot-load has happened once),
// matching every other v4s cell's safety convention.
`default_nettype none
`timescale 1ns / 1ps

module latch_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,   // unused by this cell's function; kept for a
                                     // uniform port shape across the v4s family

    input  wire         set_in,
    input  wire         clear_in,
    input  wire         toggle_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        armed       = 1'b0;
    reg        latched     = 1'b0;
    reg        out_buffer  = 1'b0;
    reg        valid_out_r = 1'b0;

    // ── The real priority logic -- unchanged from v4c: CLEAR > SET > TOGGLE ──
    wire next_latched = clear_in ? 1'b0 : set_in ? 1'b1 : toggle_in ? ~latched : latched;
    wire any_event = set_in || clear_in || toggle_in;

    assign data_out  = {31'h0, out_buffer};
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            latched     <= 1'b0;
            out_buffer  <= 1'b0;
            valid_out_r <= 1'b0;
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            latched     <= 1'b0;
            out_buffer  <= 1'b0;
            valid_out_r <= 1'b0;
        end else begin
            if (any_event) latched <= next_latched;
            out_buffer  <= next_latched;
            valid_out_r <= armed && any_event;
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// latch_cell_v4sa.v -- points.md #915: the Flex-Sub shape (ack+freeze per
// #906, WIDTH per #909/#910) applied to latch. Unlike adder/accumulator/
// compare, latch's real payload is always exactly 1 bit -- WIDTH here only
// changes how many zero-padding bits surround that bit in data_out, kept for
// uniformity with the rest of the family's bus convention, not for any real
// resource saving (flagged honestly, not oversold).
//
// Same real wrinkle as latch_cell_v4s.v: SET/CLEAR/TOGGLE as three dedicated
// one-bit event pulses (not cardinal-direction masks); priority CLEAR > SET >
// TOGGLE unchanged. See latch_cell_v4s.v's own header for the real SET-only-
// fires-on-a-1 equivalence reasoning -- unchanged here.
//
// ack/freeze: identical shape to adder_cell_v4sa.v/accumulator_cell_v4sa.v/
// compare_cell_v4sa.v -- standard ready/valid, freeze_in global and gating
// the whole update including cfg_valid's own effect.
//
// Lessons from #906/#911/#912 applied from the start: the testbench settles
// (a real delay) BEFORE clearing any event pulse the DUT also samples on the
// same edge.
`default_nettype none
`timescale 1ns / 1ps

module latch_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,   // unused by this cell's function; kept for a
                                     // uniform port shape across the family

    input  wire         set_in,
    input  wire         clear_in,
    input  wire         toggle_in,
    output wire          ack_out,     // backward, to whoever drives set/clear/toggle

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in
);

    reg armed       = 1'b0;
    reg latched     = 1'b0;
    reg pending     = 1'b0;
    reg out_buffer  = 1'b0;

    // ── The real priority logic -- unchanged: CLEAR > SET > TOGGLE ───────
    wire next_latched = clear_in ? 1'b0 : set_in ? 1'b1 : toggle_in ? ~latched : latched;
    wire any_event = set_in || clear_in || toggle_in;

    assign data_out  = {{(WIDTH-1){1'b0}}, out_buffer};
    assign valid_out = pending;
    assign ack_out   = armed && !pending && !freeze_in;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            latched     <= 1'b0;
            pending     <= 1'b0;
            out_buffer  <= 1'b0;
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            latched     <= 1'b0;
            pending     <= 1'b0;
            out_buffer  <= 1'b0;
        end else if (!freeze_in) begin
            // The latch's own stored state updates on every real event
            // regardless of pending/ack, same reasoning as accumulator's
            // running total -- only the OFFER is ack-gated.
            if (any_event) latched <= next_latched;

            if (pending) begin
                if (ack_in) pending <= 1'b0;
            end else if (any_event) begin
                out_buffer <= next_latched;
                pending    <= 1'b1;
            end
        end
    end

endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// ram_cell_v4.v — points.md #617/#619: the SECOND real "unified
// carrier" core, following `adder_cell_v4.v` (#618). Real, proven core
// logic CLONED from ram_cell_v1.v unchanged (single-arrival capture,
// no A/B two-stage — a genuinely DIFFERENT real capture shape from
// the adder, deliberately chosen to test whether the same shell
// template actually generalizes, not just repeats). Same real shell
// additions as `#618`, per Alan's own precise 5-point breakdown
// (`#617`):
//   1. programming: real, targeted `program_in`/`PROG_ID` channel,
//      faithfully ported from nano, remapped onto this core's own
//      real 6 fields (downstream_mask/upstream_mask/fixed_mode/
//      init_data split across two real half-writes/addon_config).
//   2. shift/nibble_mask/lane: the same real, already-proven 3-addon
//      chain, wired identically to `unicell_super_v3.v`/`#618`.
//   3. 6-way cardinality: real field-width headroom only, same as
//      `#618` -- only 4 real cardinal ports physically wired here.
//   4. ack all around: the programming channel's own real,
//      independent per-direction ack.
//   5. `active`: the same real, explicit port, tied high standalone.
//
// REAL, NECESSARY WIDTH CHANGE, found while porting, not assumed:
// this core's own real init_data field is a full 32 bits -- combined
// with the wider 6-bit masks and the real 20-bit addon_config, the
// total (66 bits) genuinely exceeds v1's own 64-bit cfg_data. Widened
// to 80 bits here (matching SUPER_LATCH's own real, already-
// established width elsewhere in this project, not an arbitrary
// number) -- 14 bits of real, honest reserved headroom, same
// "reserved, not wasted" convention every other real field table in
// this project already follows.
//
// REAL, NECESSARY PROTOCOL ADAPTATION: `init_data` (32 bits) cannot
// fit in one real targeted PROG_ID write at all -- `prog_data_in` is
// 32 bits wide (matching nano's own real convention), and an ID field
// needs real room above the word, so a single write can carry at most
// ~20-23 bits of real payload. Split into two real, separate
// half-writes (`PROG_ID_INIT_DATA_LOW`/`_HIGH`) rather than widening
// the programming channel itself -- keeps this core's own programming
// ports IDENTICAL in shape to `adder_cell_v4.v`'s, consistent across
// the whole real "family" (Alan's own explicit request: "make all of
// these v4 that way we can keep things separate").
//
// REAL, HONEST SCOPE, matching `#618`'s own stated deferrals exactly:
// `is_command_cell`/COMMAND_EMIT mode NOT included (real, separate,
// later question -- `#617`'s own session already flagged this may
// deserve to be its own, 9th core rather than a per-core mode).
//
// cfg_data[79:0] field map (atomic boot-load path):
//   [5:0]   downstream_mask  — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  upstream_mask    — one-hot(s), N/S/E/W real + 2 reserved
//   [12]    fixed_mode       — 1=permanent ROM-style, 0=flowing
//   [13]    load_data_valid  — mark data_reg valid immediately on load
//   [45:14] init_data[31:0]  — preset value
//   [65:46] addon_config     — 20 bits, SAME real layout as
//                              unicell_super_v3.v's own real addon_config
//   [79:66] reserved         — 14 bits, real, honest headroom
`default_nettype none
`timescale 1ns / 1ps

module ram_cell_v4 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit — tie high
    // for standalone use.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [79:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: the real, targeted programming channel, same
    // real shape as adder_cell_v4.v's own (#618) — faithfully ported
    // from nano's real program_in/PROG_ID protocol. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid
);

    // ── State — real core state, unchanged in shape from v1 (6-bit
    // masks instead of 4-bit, plus the new real addon_config, are the
    // only real width changes) ──
    reg [31:0] data_reg        = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg        fixed_mode      = 1'b0;
    reg [19:0] addon_config    = 20'h0;
    reg [3:0]  pending_ack     = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as adder_cell_v4.v's own (#618) and
    // unicell_stripped_v1.v's own real `armed` register.
    reg        armed           = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ── Upstream capture — real, unchanged shape from v1: single-
    // arrival, no A/B two-stage. Only the low 4 bits of the now-6-bit
    // upstream_mask are ever wired to a real physical port here
    // (bits [5:4] are real, reserved headroom, matching nano's own
    // convention — #604's own 3D prerequisite, not implemented). ──
    wire ram_sel_n = arrived_n && upstream_mask[0];
    wire ram_sel_s = arrived_s && upstream_mask[1];
    wire ram_sel_e = arrived_e && upstream_mask[2];
    wire ram_sel_w = arrived_w && upstream_mask[3];
    wire ram_any_upstream_arrived = ram_sel_n | ram_sel_s | ram_sel_e | ram_sel_w;
    wire [31:0] upstream_val = (ram_sel_n ? data_in_n : 32'h0) |
                               (ram_sel_s ? data_in_s : 32'h0) |
                               (ram_sel_e ? data_in_e : 32'h0) |
                               (ram_sel_w ? data_in_w : 32'h0);

    // HOLD (ledger #1035, ported from the flex ram's HOLD #1021): a FIXED ram that has an upstream face holds its word, offers it again and again (never used up), and ANY word arriving on an
    // upstream face REPLACES it, always acknowledged. It offers nothing until a word has been written (or preloaded: cfg load_data_valid). No new config bit: fixed_mode with a non-empty upstream_mask
    // was a dead combination before (fixed cells never captured); a fixed ram with NO upstream is still the plain constant, a flowing ram is unchanged.
    wire hold_mode   = fixed_mode && (|upstream_mask[3:0]);
    wire can_capture = hold_mode || (!data_valid && !fixed_mode);
    wire capture_now = ram_any_upstream_arrived && can_capture &&
                       !effective_freeze && effective_armed && !program_in;

    assign ack_out_n = capture_now && ram_sel_n;
    assign ack_out_s = capture_now && ram_sel_s;
    assign ack_out_e = capture_now && ram_sel_e;
    assign ack_out_w = capture_now && ram_sel_w;

    // ── Downstream offering — real, unchanged shape from v1, gated
    // additionally on `effective_armed`. ──
    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #617: the real, three-addon chain, wired identically
    // to adder_cell_v4.v's own (#618) and unicell_super_v3.v's own
    // real, already-proven wiring (#311/#312). ──
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(data_reg), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    // Real, honest gating: an inactive or disarmed cell never signals
    // ready, same real convention as adder_cell_v4.v's own (#618) and
    // nano's own real `ready_bit && armed` (#615).
    assign ready_out = effective_armed && can_capture && !effective_freeze;
    assign status_data_valid = data_valid;

    // ── points.md #617: real, targeted programming channel — same
    // real priority-select shape as adder_cell_v4.v's own (#618).
    // Real, necessary protocol adaptation: init_data (32 bits) is
    // split across two real half-writes (LOW/HIGH), since it can't
    // fit in one real 20-bit word alongside its own 3-bit ID. ──
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_FIXED_MODE      = 3'd2;
    localparam [2:0] PROG_ID_INIT_DATA_LOW   = 3'd3;
    localparam [2:0] PROG_ID_INIT_DATA_HIGH  = 3'd4;
    localparam [2:0] PROG_ID_ADDON_CONFIG    = 3'd5;
    localparam [2:0] PROG_ID_LOAD_DATA_VALID = 3'd6;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    // Split into a separate real reg so the two half-writes can land
    // independently without disturbing each other — same real
    // "targeted, not a hammer" property every other field already has.
    reg [31:0] init_data = 32'h0;

    always @(posedge clk) begin
        if (rst) begin
            data_reg        <= 32'h0;
            data_valid      <= 1'b0;
            downstream_mask <= 6'h0;
            upstream_mask   <= 6'h0;
            fixed_mode      <= 1'b0;
            addon_config    <= 20'h0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
            init_data       <= 32'h0;
        end else if (cfg_valid) begin
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            fixed_mode      <= cfg_data[12];
            data_valid      <= cfg_data[13];
            init_data       <= cfg_data[45:14];
            data_reg        <= cfg_data[45:14];
            addon_config    <= cfg_data[65:46];
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_FIXED_MODE:      fixed_mode      <= prog_word[0];
                PROG_ID_INIT_DATA_LOW:   init_data[15:0]  <= prog_word[15:0];
                PROG_ID_INIT_DATA_HIGH:  init_data[31:16] <= prog_word[15:0];
                PROG_ID_ADDON_CONFIG:    addon_config    <= prog_word[19:0];
                // points.md #617/#619: a real, necessary correction,
                // caught by simulation, not assumed correct -- a first
                // draft had COMPLETE unconditionally recommit
                // data_reg/data_valid from init_data on EVERY targeted
                // reprogram, even ones that never touched init_data at
                // all, silently corrupting a flowing cell's own
                // current held value. Real fix: committing init_data
                // into data_reg is its own real, explicit, separate
                // action (PROG_ID_LOAD_DATA_VALID), matching
                // cfg_data's own real `load_data_valid` bit -- COMPLETE
                // itself now does ONLY what nano's own real COMPLETE
                // does (#615): commit the arm state, nothing else.
                PROG_ID_LOAD_DATA_VALID: begin
                    if (prog_word[0]) begin
                        data_reg   <= init_data;
                        data_valid <= 1'b1;
                    end
                end
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_now) begin
                data_reg   <= upstream_val;
                data_valid <= 1'b1;
            end else if (!fixed_mode && offer_draining) begin
                data_valid <= 1'b0;
            end
            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4c.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// ram_cell_v4c.v — points.md #720: the "c" (carrier) variant of
// ram_cell_v4.v. Same real reasoning as adder_cell_v4c.v's own header
// -- the VIX carrier's whole design concept is to hold common
// functionality centrally, and ram_cell_v4's own internal 3-addon
// chain (nibble_mask/shift_lane/invert) duplicates exactly what the
// carrier itself now provides once, shared across whichever core is
// active. ram_cell_v4.v itself is UNCHANGED, still the real, proven,
// standalone core.
//
// Real, honest scope of this file's own changes from v4:
//   1. The internal addon chain is REMOVED entirely -- data_out_n/s/
//      e/w now come directly from data_reg, the real held value.
//   2. addon_config (20 bits) is removed from cfg_data's own field
//      map, the register, and the PROG_ID_ADDON_CONFIG case -- cfg_
//      data KEEPS its original 80-bit width (simpler, no risk to any
//      wiring elsewhere that assumes it); the bits addon_config used
//      to occupy are now genuinely reserved.
//   3. downstream_mask/upstream_mask/fixed_mode/init_data STAY real
//      registers (same reasoning as adder_cell_v4c.v's own header:
//      this cell's live-programming channel genuinely needs a
//      register it can independently write to). The real config-off-
//      shell fix lives at the carrier's own shell level -- feed this
//      cell's own cfg_data from the carrier's stable core_config, not
//      a transient incoming/about-to-commit value.
//
// cfg_data[79:0] field map (atomic boot-load path):
//   [5:0]   downstream_mask  — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  upstream_mask    — one-hot(s), N/S/E/W real + 2 reserved
//   [12]    fixed_mode       — 1=permanent ROM-style, 0=flowing
//   [13]    load_data_valid  — mark data_reg valid immediately on load
//   [45:14] init_data[31:0]  — preset value
//   [79:46] reserved         — 34 bits (addon_config's own old home,
//                              now genuinely free, plus the original
//                              14 bits of headroom)

`default_nettype none
`timescale 1ns / 1ps

module ram_cell_v4c #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit — tie high
    // for standalone use.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [79:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: the real, targeted programming channel, same
    // real shape as adder_cell_v4.v's own (#618) — faithfully ported
    // from nano's real program_in/PROG_ID protocol. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid
);

    // ── State — real core state, matching v1's own shape (6-bit
    // masks instead of 4-bit is the only real width change here;
    // #720 removed addon_config entirely rather than adding it) ──
    reg [31:0] data_reg        = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg        fixed_mode      = 1'b0;
    reg [3:0]  pending_ack     = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as adder_cell_v4.v's own (#618) and
    // unicell_stripped_v1.v's own real `armed` register.
    reg        armed           = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ── Upstream capture — real, unchanged shape from v1: single-
    // arrival, no A/B two-stage. Only the low 4 bits of the now-6-bit
    // upstream_mask are ever wired to a real physical port here
    // (bits [5:4] are real, reserved headroom, matching nano's own
    // convention — #604's own 3D prerequisite, not implemented). ──
    wire ram_sel_n = arrived_n && upstream_mask[0];
    wire ram_sel_s = arrived_s && upstream_mask[1];
    wire ram_sel_e = arrived_e && upstream_mask[2];
    wire ram_sel_w = arrived_w && upstream_mask[3];
    wire ram_any_upstream_arrived = ram_sel_n | ram_sel_s | ram_sel_e | ram_sel_w;
    wire [31:0] upstream_val = (ram_sel_n ? data_in_n : 32'h0) |
                               (ram_sel_s ? data_in_s : 32'h0) |
                               (ram_sel_e ? data_in_e : 32'h0) |
                               (ram_sel_w ? data_in_w : 32'h0);

    // HOLD (ledger #1035, ported from the flex ram's HOLD #1021): a FIXED ram that has an upstream face holds its word, offers it again and again (never used up), and ANY word arriving on an
    // upstream face REPLACES it, always acknowledged. It offers nothing until a word has been written (or preloaded: cfg load_data_valid). No new config bit: fixed_mode with a non-empty upstream_mask
    // was a dead combination before (fixed cells never captured); a fixed ram with NO upstream is still the plain constant, a flowing ram is unchanged.
    wire hold_mode   = fixed_mode && (|upstream_mask[3:0]);
    wire can_capture = hold_mode || (!data_valid && !fixed_mode);
    wire capture_now = ram_any_upstream_arrived && can_capture &&
                       !effective_freeze && effective_armed && !program_in;

    assign ack_out_n = capture_now && ram_sel_n;
    assign ack_out_s = capture_now && ram_sel_s;
    assign ack_out_e = capture_now && ram_sel_e;
    assign ack_out_w = capture_now && ram_sel_w;

    // ── Downstream offering — real, unchanged shape from v1, gated
    // additionally on `effective_armed`. ──
    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #720: NO addon chain here at all — the carrier
    // already provides one, shared across whichever core is active.
    // data_out_n/s/e/w are the real held value, directly. ──
    assign data_out_n = data_reg;
    assign data_out_s = data_reg;
    assign data_out_e = data_reg;
    assign data_out_w = data_reg;

    // Real, honest gating: an inactive or disarmed cell never signals
    // ready, same real convention as adder_cell_v4.v's own (#618) and
    // nano's own real `ready_bit && armed` (#615).
    assign ready_out = effective_armed && can_capture && !effective_freeze;
    assign status_data_valid = data_valid;

    // ── points.md #617: real, targeted programming channel — same
    // real priority-select shape as adder_cell_v4.v's own (#618).
    // Real, necessary protocol adaptation: init_data (32 bits) is
    // split across two real half-writes (LOW/HIGH), since it can't
    // fit in one real 20-bit word alongside its own 3-bit ID. ──
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_FIXED_MODE      = 3'd2;
    localparam [2:0] PROG_ID_INIT_DATA_LOW   = 3'd3;
    localparam [2:0] PROG_ID_INIT_DATA_HIGH  = 3'd4;
    localparam [2:0] PROG_ID_LOAD_DATA_VALID = 3'd6;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    // Split into a separate real reg so the two half-writes can land
    // independently without disturbing each other — same real
    // "targeted, not a hammer" property every other field already has.
    reg [31:0] init_data = 32'h0;

    always @(posedge clk) begin
        if (rst) begin
            data_reg        <= 32'h0;
            data_valid      <= 1'b0;
            downstream_mask <= 6'h0;
            upstream_mask   <= 6'h0;
            fixed_mode      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
            init_data       <= 32'h0;
        end else if (cfg_valid) begin
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            fixed_mode      <= cfg_data[12];
            data_valid      <= cfg_data[13];
            init_data       <= cfg_data[45:14];
            data_reg        <= cfg_data[45:14];
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_FIXED_MODE:      fixed_mode      <= prog_word[0];
                PROG_ID_INIT_DATA_LOW:   init_data[15:0]  <= prog_word[15:0];
                PROG_ID_INIT_DATA_HIGH:  init_data[31:16] <= prog_word[15:0];
                // points.md #617/#619: a real, necessary correction,
                // caught by simulation, not assumed correct -- a first
                // draft had COMPLETE unconditionally recommit
                // data_reg/data_valid from init_data on EVERY targeted
                // reprogram, even ones that never touched init_data at
                // all, silently corrupting a flowing cell's own
                // current held value. Real fix: committing init_data
                // into data_reg is its own real, explicit, separate
                // action (PROG_ID_LOAD_DATA_VALID), matching
                // cfg_data's own real `load_data_valid` bit -- COMPLETE
                // itself now does ONLY what nano's own real COMPLETE
                // does (#615): commit the arm state, nothing else.
                PROG_ID_LOAD_DATA_VALID: begin
                    if (prog_word[0]) begin
                        data_reg   <= init_data;
                        data_valid <= 1'b1;
                    end
                end
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_now) begin
                data_reg   <= upstream_val;
                data_valid <= 1'b1;
            end else if (!fixed_mode && offer_draining) begin
                data_valid <= 1'b0;
            end
            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// ram_cell_v4s.v -- stripped version of ram_cell_v4c.v's real function: hold one
// 32-bit value, either fixed at configuration time (ROM-style) or freshly
// captured whenever new data genuinely arrives (flowing). No backward
// ack/draining concept survives here -- in flowing mode, every valid_in simply
// overwrites the held value; there is no "already have unconsumed data" gating,
// because there is no consumer that could ever fail to consume it in time.
//
// Same small-extra-config-port pattern as sequencer_cell_v4s.v: fixed_mode (1
// bit) plus a full 32-bit init_data doesn't fit together in one 32-bit cfg_data,
// so fixed_mode gets its own tiny dedicated config input.
//
// fixed_mode behaviour, unchanged in spirit from v4c: once armed, a fixed-mode
// cell's held value never changes and its valid_out is CONTINUOUSLY high (there
// is no backward "offer draining" to ever clear it, matching the original's own
// `!fixed_mode` guard on that clear). A flowing-mode cell's valid_out pulses only
// on the cycle a genuine new capture happens.
//
// cfg_data field map:
//   [31:0] init_data -- the preset value (fixed mode) or the initial held value
//                        before any real capture (flowing mode)
// cfg_fixed_mode: 1 = ROM-style permanent value, 0 = flowing (captures on valid_in)
`default_nettype none
`timescale 1ns / 1ps

module ram_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,
    input  wire         cfg_fixed_mode,

    input  wire [31:0]  data_in,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        fixed_mode  = 1'b0;
    reg        armed       = 1'b0;
    reg [31:0] data_reg    = 32'h0;
    reg        valid_out_r = 1'b0;

    assign data_out  = data_reg;
    assign valid_out = fixed_mode ? armed : valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            fixed_mode  <= 1'b0;
            armed       <= 1'b0;
            data_reg    <= 32'h0;
            valid_out_r <= 1'b0;
        end else if (cfg_valid) begin
            fixed_mode  <= cfg_fixed_mode;
            data_reg    <= cfg_data;
            armed       <= 1'b1;
            valid_out_r <= 1'b0;
        end else if (!fixed_mode) begin
            if (valid_in) data_reg <= data_in;
            valid_out_r <= armed && valid_in;
        end
        // fixed_mode: data_reg and valid_out (via armed) simply hold forever.
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// ram_cell_v4sa.v -- points.md #915: the Flex-Sub shape (ack+freeze per #906,
// WIDTH per #909/#910) applied to ram. A real design point worth stating:
// fixed_mode and flowing mode genuinely need DIFFERENT treatment here, not
// one shape forced onto both. Fixed mode's whole point is "always valid,
// never drains" (unchanged from ram_cell_v4s.v) -- there is nothing to offer
// and wait for, so it does not use the pending/ack protocol at all; ack_out
// simply reflects "configured", and valid_out is continuously high. Flowing
// mode uses the SAME pending/ack discipline as every other v4sa cell.
//
// cfg_data field map, unchanged: [31:0] init_data. cfg_fixed_mode on its own
// small port, same reason as v4s (1 bit + a full 32-bit word doesn't fit in
// one 32-bit cfg_data together).
`default_nettype none
`timescale 1ns / 1ps

module ram_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32,
    // ledger #1021 (Alan, 7 Oct 2026): 1 = a FLOWING-mode ram offers its configured value ONCE, at start, then behaves as an ordinary flowing ram (the VM's `load_data_valid`: a preloaded,
    // non-fixed ram offers its constant once and then waits). 0 (default) = as before: the configured value is loaded but not offered until something is written. Fixed mode is unaffected.
    parameter        OFFER_PRELOAD = 0,
    // ledger #1021 (Alan, 7 Oct 2026: "offer on tick (constant), offer on ack (one shot and empty), offer on ack (hold value, re-offer on request; the value stored is the in port, that updates its
    // contents)"). HOLD = 1 gives FIXED mode its third behaviour: the cell still offers its value continuously and is never drained (a consumer takes a copy whenever it is ready: that readiness IS
    // the request), but data arriving on the in-port now REPLACES the stored value (always accepted; the next copy is the new word). It starts empty (offers nothing) until a word has been written,
    // or holds the configured word at once when OFFER_PRELOAD = 1. Only fixed mode is changed; HOLD = 0 (default) is the constant exactly as before.
    parameter        HOLD = 0
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    // ledger #1011: the constant / init word SCALES with the cell: a WIDTH-bit cell has a WIDTH-bit init port (never narrower than the 32-bit config bus,
    // so every existing 32-bit-or-narrower instance is byte-for-byte the same port as before).
    input  wire [(WIDTH > 32 ? WIDTH : 32)-1:0]  cfg_data,
    input  wire         cfg_fixed_mode,

    input  wire [WIDTH-1:0]  data_in,
    input  wire               valid_in,
    output wire                ack_out,     // backward, to whoever feeds data_in (flowing mode only)

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,
    input  wire               ack_in       // backward, from the downstream receiver (flowing mode only)
);

    reg                  fixed_mode  = 1'b0;
    reg                  armed       = 1'b0;
    reg                  pending     = 1'b0;   // flowing mode only
    reg                  have        = 1'b0;   // HOLD only: a value is stored
    reg [WIDTH-1:0]      data_reg    = {WIDTH{1'b0}};

    assign data_out  = data_reg;
    assign valid_out = fixed_mode ? ((HOLD != 0) ? (armed && have) : armed) : pending;
    // Fixed mode is always ready (nothing to offer-and-wait-for, it is a
    // constant); flowing mode follows the standard pending/ack discipline.
    assign ack_out   = fixed_mode ? (armed && !freeze_in) : (armed && !pending && !freeze_in);

    always @(posedge clk) begin
        if (rst) begin
            fixed_mode  <= 1'b0;
            armed       <= 1'b0;
            pending     <= 1'b0;
            data_reg    <= {WIDTH{1'b0}};
            have        <= 1'b0;
        end else if (cfg_valid) begin
            fixed_mode  <= cfg_fixed_mode;
            data_reg    <= cfg_data[WIDTH-1:0];
            armed       <= 1'b1;
            pending     <= (OFFER_PRELOAD != 0) && !cfg_fixed_mode;   // OFFER_PRELOAD: the configured word is the first (and only preloaded) offer
            have        <= (OFFER_PRELOAD != 0);                       // HOLD: OFFER_PRELOAD = the configured word is already the held value; otherwise start empty
        end else if (!freeze_in) begin
            if (!fixed_mode) begin
                if (pending) begin
                    if (ack_in) pending <= 1'b0;
                end else if (valid_in) begin
                    data_reg <= data_in;
                    pending  <= 1'b1;
                end
            end
            else if (HOLD != 0 && valid_in) begin
                // HOLD (#1021): a word arriving in fixed mode replaces the held value (ack_out is already always high in fixed mode)
                data_reg <= data_in;
                have     <= 1'b1;
            end
            // fixed_mode without HOLD: data_reg and valid_out (via armed) simply hold
            // forever, same as v4s.
        end
    end

endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// sequencer_cell_v4.v — points.md #617/#625: the SEVENTH and final
// real "unified carrier" core (all 8 real core types now have a real
// `v4` build). Real core logic CLONED from sequencer_cell_v1.v
// unchanged: a config-fixed cyclic list of up to 4 real 8-bit values,
// offered in order, advancing only once the current offer is
// genuinely acked.
//
// REAL, HONEST CONFIRMATION OF ALAN'S OWN DIRECT PREDICTION, CHECKED
// AGAINST THE REAL RTL BEFORE BUILDING, NOT ASSUMED: this core
// genuinely has NO capture side at all -- `ack_out_X` is tied low on
// every direction in the real v1 RTL (confirmed directly, "there is
// nothing to acknowledge," matching that file's own real comment).
// Several of #617's own 5 points therefore have LESS real surface
// here than on any other core built so far:
//   1. programming: STILL real and applies in full -- every one of
//      this core's own real fields (VALUE_0-3, SEQUENCE_LEN,
//      downstream_mask) is real, targetable config, same as anywhere
//      else.
//   2. shift/nibble_mask/lane: STILL real and applies in full --
//      wired to the offered output, same as every other core.
//   3. 6-way cardinality: applies ONLY to `downstream_mask` (the one
//      real directional field this core has at all) -- there is no
//      `upstream_mask` to widen, because there is no upstream.
//   4. "ack all around": the real PROGRAMMING channel still gets its
//      own real, independent ack per direction (unchanged from every
//      other core) -- but the ORDINARY data-side ack stays tied to 0
//      on every direction, unchanged from v1, because there is
//      genuinely nothing to acknowledge on that side, ever.
//   5. `active`: applies, but with a real, genuine SIMPLIFICATION
//      versus every other core built so far (#618-#624) -- there is
//      no capture path to separately gate. Gating `want_to_offer`
//      alone is sufficient: `offer_just_completed` (the real advance
//      trigger) is causally downstream of a successful offer, so an
//      inactive cell's own index cannot advance AT ALL while inactive
//      -- not because of an extra, explicit gate, but because the
//      offer that would trigger an advance never happens in the first
//      place. The simplest real case of the "inactive = zero effect"
//      principle across all seven cores built so far, not requiring
//      the extra capture-side wiring #621/#623's own real accumulator/
//      latch builds needed.
//
// REAL, NOTABLE DATA POINT: this core's own real field total
// (32+2+6+20 = 60 bits) fits in the original 64-bit cfg_data with 4
// bits of real, honest margin -- no widening needed. Its own real
// PROG_ID budget (7 real fields: VALUE_0-3, SEQUENCE_LEN,
// downstream_mask, addon_config) fits EXACTLY in the same 3-bit ID
// every core except `branch` (#624, 15 fields) used -- a real,
// concrete confirmation that the ID-width question genuinely depends
// on each core's own real field count, not a fixed rule.
//
// REAL, HONEST SCOPE, matching #618-#624's own stated deferrals:
// `is_command_cell` mode NOT included (parked as a possible 9th-core
// question).
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [7:0]   VALUE_0
//   [15:8]  VALUE_1
//   [23:16] VALUE_2
//   [31:24] VALUE_3
//   [33:32] SEQUENCE_LEN     — stored as length-1 (0 means length 1)
//   [39:34] downstream_mask  — one-hot(s), N/S/E/W real + 2 reserved
//   [59:40] addon_config     — 20 bits, SAME real layout as
//                              unicell_super_v3.v's own real addon_config
//   [63:60] reserved
`default_nettype none
`timescale 1ns / 1ps

module sequencer_cell_v4 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    // points.md #617 point 5: real, explicit "active" bit -- gates
    // the offer side only, see the header's own real reasoning above.
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    // ── points.md #617: real, targeted programming channel, same real
    // shape as #618-#624's own -- fully real and applicable here,
    // unlike the data-side capture logic every other core has. ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         ready_out,
    output wire [1:0]   status_seq_index
);

    reg [7:0] value_0 = 8'h00, value_1 = 8'h00, value_2 = 8'h00, value_3 = 8'h00;
    reg [1:0] sequence_len_m1 = 2'd0;
    reg [5:0] downstream_mask = 6'h0;
    reg [19:0] addon_config = 20'h0;

    reg [1:0] seq_index  = 2'd0;
    reg [7:0] out_buffer = 8'h00;
    reg data_valid = 1'b0;
    reg [3:0] pending_ack = 4'h0;
    // points.md #617: real, staged-reconfiguration arm state, same
    // real semantics as #618-#624's own.
    reg armed = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    function [7:0] value_for_index(input [1:0] idx);
        case (idx)
            2'd0: value_for_index = value_0;
            2'd1: value_for_index = value_1;
            2'd2: value_for_index = value_2;
            default: value_for_index = value_3;
        endcase
    endfunction

    // Real, unchanged from v1: no capture at all -- nothing arrives
    // that this core reacts to, confirmed directly, not assumed.
    assign ack_out_n = 1'b0;
    assign ack_out_s = 1'b0;
    assign ack_out_e = 1'b0;
    assign ack_out_w = 1'b0;

    // ── Downstream offering -- real, unchanged shape from v1, gated
    // additionally on effective_armed (#617's own real principle,
    // applied here in its simplest real form -- see header). ──
    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;

    wire offer_just_completed = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);
    wire [1:0] next_seq_index = (seq_index == sequence_len_m1) ? 2'd0 : seq_index + 2'd1;

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #617: the real, three-addon chain, applied to the
    // offered {24'h0,out_buffer} expansion, wired identically to
    // #618-#624's own. ──
    wire [31:0] seq_expanded = {24'h0, out_buffer};
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(seq_expanded), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    assign status_seq_index = seq_index;
    // Real, honest gating: an inactive/disarmed cell is never ready --
    // same real convention as #618-#624's own.
    assign ready_out = effective_armed && !effective_freeze;

    // ── points.md #617: real, targeted programming channel — same
    // real priority-select shape as #618-#624's own. Every real field
    // here fits in a single targeted write; the real ID budget fits
    // EXACTLY in 3 bits (7 fields + COMPLETE), unlike branch's own
    // real 4-bit need (#624) -- a real, direct confirmation the
    // budget genuinely depends on each core's own field count. ──
    localparam [2:0] PROG_ID_VALUE_0         = 3'd0;
    localparam [2:0] PROG_ID_VALUE_1         = 3'd1;
    localparam [2:0] PROG_ID_VALUE_2         = 3'd2;
    localparam [2:0] PROG_ID_VALUE_3         = 3'd3;
    localparam [2:0] PROG_ID_SEQUENCE_LEN    = 3'd4;
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd5;
    localparam [2:0] PROG_ID_ADDON_CONFIG    = 3'd6;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            value_0         <= 8'h00; value_1 <= 8'h00; value_2 <= 8'h00; value_3 <= 8'h00;
            sequence_len_m1 <= 2'd0;
            downstream_mask <= 6'h0;
            addon_config    <= 20'h0;
            seq_index       <= 2'd0;
            out_buffer      <= 8'h00;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            value_0         <= cfg_data[7:0];
            value_1         <= cfg_data[15:8];
            value_2         <= cfg_data[23:16];
            value_3         <= cfg_data[31:24];
            sequence_len_m1 <= cfg_data[33:32];
            downstream_mask <= cfg_data[39:34];
            addon_config    <= cfg_data[59:40];
            seq_index       <= 2'd0;
            out_buffer      <= cfg_data[7:0];   // value_for_index(0) -- same value_0 field, direct
            data_valid      <= 1'b1;            // live from the first cycle after config
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_VALUE_0:         value_0         <= prog_word[7:0];
                PROG_ID_VALUE_1:         value_1         <= prog_word[7:0];
                PROG_ID_VALUE_2:         value_2         <= prog_word[7:0];
                PROG_ID_VALUE_3:         value_3         <= prog_word[7:0];
                PROG_ID_SEQUENCE_LEN:    sequence_len_m1 <= prog_word[1:0];
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_ADDON_CONFIG:    addon_config    <= prog_word[19:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (offer_just_completed) begin
                seq_index  <= next_seq_index;
                out_buffer <= value_for_index(next_seq_index);
            end
            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

