// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// sequencer_cell_v4s.v -- stripped version of sequencer_cell_v4c.v's real
// function. A real structural point worth stating: the original never captures
// any incoming data at all -- it advances purely when its CURRENT offer's ack
// completes, i.e. purely on the backward handshake this whole family removes.
// The forward-only replacement: a dedicated `advance_in` pulse, an explicit
// external "move to the next value" event -- a genuine forward control input, not
// a backward ack, so it fits the family's philosophy cleanly (this is exactly the
// external tick pattern #892's real on-board smoke test already used
// successfully for the same underlying core).
//
// One family convention bent slightly, for a real reason: this cell's native
// config (four 8-bit values + a 2-bit sequence length) is 34 bits, one more than
// the shared cfg_data[31:0] can hold once all four values keep their full width.
// Rather than shrink a value or force an awkward re-pack, sequence length gets
// its own small, separate config input, loaded on the same cfg_valid pulse.
//
// cfg_data field map:
//   [7:0]   VALUE_0
//   [15:8]  VALUE_1
//   [23:16] VALUE_2
//   [31:24] VALUE_3
// cfg_seq_len_m1[1:0]: sequence length minus 1 (0 = length 1, ... 3 = length 4)
`default_nettype none
`timescale 1ns / 1ps

module sequencer_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,
    input  wire [1:0]   cfg_seq_len_m1,

    input  wire         advance_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg [7:0] value_0 = 8'h00, value_1 = 8'h00, value_2 = 8'h00, value_3 = 8'h00;
    reg [1:0] sequence_len_m1 = 2'd0;
    reg       armed = 1'b0;

    reg [1:0] seq_index   = 2'd0;
    reg [7:0] out_buffer  = 8'h00;
    reg       valid_out_r = 1'b0;

    // ── Real, unchanged from v4c ─────────────────────────────────────────
    function [7:0] value_for_index(input [1:0] idx);
        case (idx)
            2'd0: value_for_index = value_0;
            2'd1: value_for_index = value_1;
            2'd2: value_for_index = value_2;
            default: value_for_index = value_3;
        endcase
    endfunction

    wire [1:0] next_seq_index = (seq_index == sequence_len_m1) ? 2'd0 : seq_index + 2'd1;

    assign data_out  = {24'h0, out_buffer};
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            value_0 <= 8'h00; value_1 <= 8'h00; value_2 <= 8'h00; value_3 <= 8'h00;
            sequence_len_m1 <= 2'd0;
            armed           <= 1'b0;
            seq_index       <= 2'd0;
            out_buffer      <= 8'h00;
            valid_out_r     <= 1'b0;
        end else if (cfg_valid) begin
            value_0         <= cfg_data[7:0];
            value_1         <= cfg_data[15:8];
            value_2         <= cfg_data[23:16];
            value_3         <= cfg_data[31:24];
            sequence_len_m1 <= cfg_seq_len_m1;
            armed           <= 1'b1;
            seq_index       <= 2'd0;
            out_buffer      <= cfg_data[7:0];   // value_for_index(0)
            valid_out_r     <= 1'b0;
        end else begin
            if (advance_in) begin
                seq_index  <= next_seq_index;
                out_buffer <= value_for_index(next_seq_index);
            end
            valid_out_r <= armed && advance_in;
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// sequencer_cell_v4sa.v -- points.md #915: the Flex-Sub shape (ack+freeze per
// #906, WIDTH per #909/#910) applied to sequencer. Same honest note as
// latch_cell_v4sa.v: the real stored values are fixed 8-bit fields packed
// into cfg_data (a native constraint, not a WIDTH choice), so WIDTH here only
// changes data_out's zero-padding, kept for bus-convention uniformity, not a
// real resource saving.
//
// Same real structural point as sequencer_cell_v4s.v: the original never
// captures incoming data -- advance_in is a genuine forward control pulse
// (the external tick pattern #892's real smoke test already used), not a
// backward ack.
//
// What's new here, and worth stating precisely: advance_in is now gated by
// the SAME pending/ack discipline every other v4sa cell uses, not accepted
// unconditionally every time it fires. A new advance_in while a previous
// offer is still unacked is ignored -- exactly like any other v4sa cell's
// sender being expected to check ack_out before firing again. This is a
// real, deliberate behavioural narrowing from sequencer_cell_v4s.v's own
// "advance_in always moves the index, every single assertion," needed to fit
// the family's now-standard backpressure discipline.
//
// cfg_data field map, unchanged: [7:0]/[15:8]/[23:16]/[31:24] = VALUE_0..3;
// cfg_seq_len_m1[1:0] on its own small port, same reason as v4s.
`default_nettype none
`timescale 1ns / 1ps

module sequencer_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,
    input  wire [1:0]   cfg_seq_len_m1,

    input  wire         advance_in,
    output wire          ack_out,     // backward, to whoever drives advance_in

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in
);

    reg [7:0] value_0 = 8'h00, value_1 = 8'h00, value_2 = 8'h00, value_3 = 8'h00;
    reg [1:0] sequence_len_m1 = 2'd0;
    reg       armed = 1'b0;
    reg       pending = 1'b0;

    reg [1:0] seq_index   = 2'd0;
    reg [7:0] out_buffer  = 8'h00;

    // ── Real, unchanged from v4c/v4s ──────────────────────────────────────
    function [7:0] value_for_index(input [1:0] idx);
        case (idx)
            2'd0: value_for_index = value_0;
            2'd1: value_for_index = value_1;
            2'd2: value_for_index = value_2;
            default: value_for_index = value_3;
        endcase
    endfunction

    wire [1:0] next_seq_index = (seq_index == sequence_len_m1) ? 2'd0 : seq_index + 2'd1;

    assign data_out  = {{(WIDTH-8){1'b0}}, out_buffer};
    assign valid_out = pending;
    assign ack_out   = armed && !pending && !freeze_in;

    always @(posedge clk) begin
        if (rst) begin
            value_0 <= 8'h00; value_1 <= 8'h00; value_2 <= 8'h00; value_3 <= 8'h00;
            sequence_len_m1 <= 2'd0;
            armed           <= 1'b0;
            pending         <= 1'b0;
            seq_index       <= 2'd0;
            out_buffer      <= 8'h00;
        end else if (cfg_valid) begin
            value_0         <= cfg_data[7:0];
            value_1         <= cfg_data[15:8];
            value_2         <= cfg_data[23:16];
            value_3         <= cfg_data[31:24];
            sequence_len_m1 <= cfg_seq_len_m1;
            armed           <= 1'b1;
            pending         <= 1'b0;
            seq_index       <= 2'd0;
            out_buffer      <= cfg_data[7:0];   // value_for_index(0)
        end else if (!freeze_in) begin
            if (pending) begin
                if (ack_in) pending <= 1'b0;
            end else if (advance_in && armed) begin   // gated by `armed` like every other v4sa cell (ledger #956: an UNCONFIGURED cell used to offer a value)
                seq_index  <= next_seq_index;
                out_buffer <= value_for_index(next_seq_index);
                pending    <= 1'b1;
            end
        end
    end

endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// nano_gate_v4.v — points.md #617/#626: nano's own STRIP-DOWN to the
// unified carrier shape, the one core in this whole family that gets
// LESS internal machinery, not more, since it already had the richest
// real feature set of all 8 (per this same session's own real
// discovery). Real core logic CLONED UNCHANGED from
// unicell_stripped_v1.v, per Alan's own direct decision to keep it
// "as is... the Swiss army knife of all the cores": the real
// two-arrival NOR-decomposed gate computation (12 real topology
// codes, unchanged since the FULL cell), the real dynamic
// pattern-based routing (pattern_low/equal/high + dynamic_route_en,
// gated by the real, measured ENABLE_DYNAMIC_ROUTING compile-time
// parameter -- kept precisely because it's genuinely core-specific,
// outcome-dependent routing, the same real reasoning `branch_cell_v4.
// v`'s own route_low/equal/high got, #624), real relay-vs-consume
// classification (`cardinal_edge`), and the full real memory-cell
// extension set (`hold_in`/`fb_internal_in`/`a_reemit_in`/
// `a_update_in`/`a_self_update_in`), plus `error_frozen`'s own real
// protective latch.
//
// REAL, DELIBERATE REMOVAL, per Alan's own direct decision: the
// command-cell mechanism is gone ENTIRELY, moving to a real, separate
// command core (not yet built) rather than staying bolted onto this
// one:
//   - `is_command_cell` (`cmd_latch[10]` in v1) removed outright.
//     Confirmed directly before removing, not assumed: it was ONLY
//     ever a config-time alias forcing `effective_hold`/
//     `effective_reemit` permanently true -- the exact same real
//     behavior remains fully reachable by driving `hold_in`/
//     `a_reemit_in` directly from whatever real source needs it
//     (including a future command core). Zero real capability lost.
//   - `cmd_in_n/s/e/w`/`cmd_out_n/s/e/w` removed outright. Confirmed
//     directly before removing: these were real, reserved PORTS
//     (`#84`) but genuinely UNWIRED in the actual RTL (`cmd_out_x`
//     tied to `32'h0` unconditionally) -- a dead stub, not a working
//     channel. Zero real capability lost removing it either.
//
// Same real shell additions as #618-#625, per Alan's own precise
// 5-point breakdown (#617):
//   1. programming: the real, targeted program_in/PROG_ID channel --
//      ALREADY nano's own real mechanism (the one every other core's
//      own #618-#625 build was faithfully ported FROM, #615) --
//      extended here with one real, new targeted field
//      (`PROG_ID_ADDON_CONFIG`) and widened to a real 4-bit ID (9 real
//      fields + COMPLETE now exceed the original 3-bit/8-slot budget
//      -- the SAME real pressure `branch_cell_v4.v` hit, #624, not a
//      coincidence: both are this project's own richest, most
//      field-dense cores).
//   2. shift/nibble_mask/lane: the real, already-proven 3-addon chain,
//      wired to the offered `out_buffer`, same as #618-#625.
//   3. 6-way cardinality: nano ALREADY had this -- `routing_mask`/
//      `cardinal_edge` are genuinely 6 bits wide in the real v1 RTL,
//      the real prerequisite `#604` itself already named. No change
//      needed here; nano was the one core the other 7 were catching
//      up TO on this specific point.
//   4. ack all around: nano ALREADY had this too -- the real
//      programming channel's own independent per-direction ack was
//      always here (`#615`).
//   5. `active`: the one real, genuinely new addition. Folded into
//      the SAME place `armed` already lives in the real v1 logic
//      (`effective_freeze = freeze_in || error_frozen || !armed`) --
//      matching that EXISTING real convention exactly rather than
//      importing the OTHER 7 cores' own separate `effective_armed`
//      pattern, since nano already had its own established way of
//      composing these gates.
//
// REAL, NOTABLE DATA POINT: `addon_config` (20 bits) fits inside the
// EXISTING 128-bit `cmd_latch` without widening `cfg_data` at all --
// confirmed directly, not assumed: the real v1 header already
// documents roughly 53 bits of genuine, deliberate reserved headroom
// ([63:14] alone is 50 bits) left free specifically for future
// extension. The one core built up from the richest starting budget
// is also the one that needed the LEAST real extra room.
//
// cmd_latch[127:0] field map (atomic boot-load path) -- unchanged
// bit positions from v1 except where noted:
//   [9:0]   topology         — same 12 real NOR-decomposed gate codes
//   [10]    reserved         — was is_command_cell, now free
//   [12:11] reserved
//   [13]    ready            — this cell's own readiness
//   [33:14] addon_config     — 20 bits, SAME real layout as
//                              unicell_super_v3.v's own real addon_config,
//                              placed in v1's own real reserved space
//   [63:34] reserved         — 30 bits, real, honest headroom
//   [69:64] routing_mask     — unchanged from v1
//   [75:70] cardinal_edge    — unchanged from v1
//   [81:76] pattern_low      — unchanged from v1
//   [87:82] pattern_equal    — unchanged from v1
//   [93:88] pattern_high     — unchanged from v1
//   [94]    dynamic_route_en — unchanged from v1
//   [95]    reserved
//   [127:96] out_buffer      — unchanged from v1
`default_nettype none
`timescale 1ns / 1ps

module nano_gate_v4 #(
    parameter [15:0] CELL_ID = 16'h0000,
    // Real, unchanged from v1 -- the same measured ALM/timing
    // optimization (#169/silicon session): compile-time gate for the
    // dynamic-routing comparator, zero cost for any cell that never
    // uses it.
    parameter        ENABLE_DYNAMIC_ROUTING = 1'b0
) (
    input  wire        clk,
    input  wire         rst,

    // points.md #617 point 5: real, explicit "active" bit -- folded
    // into effective_freeze alongside armed, matching nano's own
    // existing real convention (see header).
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [127:0] cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    input  wire         freeze_in,

    // ── Real, unchanged live control wires from v1 -- these are
    // genuinely live control, not config, per v1's own real,
    // established distinction (see header of unicell_stripped_v1.v). ──
    input  wire         hold_in,
    input  wire         fb_internal_in,
    input  wire         a_reemit_in,
    input  wire         a_update_in,
    input  wire         a_self_update_in,

    // ── points.md #617: real, targeted programming channel -- ALREADY
    // nano's own real mechanism, unchanged in shape, extended with one
    // new real field and a widened 4-bit ID (see header). ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w
);

    // ── State — real, unchanged from v1 ──────────────────────────────
    reg [127:0] cmd_latch  = 128'h0;
    reg [31:0]  data_reg   = 32'h0;
    reg         a_arrived  = 1'b0;
    reg [5:0]   pending_ack= 6'h0;
    reg         program_done_r = 1'b0;
    reg         error_frozen = 1'b0;
    reg         armed = 1'b0;

    wire [9:0] topology     = cmd_latch[9:0];
    wire       ready_bit    = cmd_latch[13];
    wire [19:0] addon_config= cmd_latch[33:14];
    wire [5:0] routing_mask = cmd_latch[69:64];
    wire [5:0] cardinal_edge= cmd_latch[75:70];
    wire [31:0] out_buffer  = cmd_latch[127:96];

    wire [3:0] pattern_low    = cmd_latch[79:76];
    wire [3:0] pattern_equal  = cmd_latch[85:82];
    wire [3:0] pattern_high   = cmd_latch[91:88];
    wire       dynamic_route_en = cmd_latch[94];

    // Real, deliberate removal (see header): is_command_cell is gone.
    // effective_hold/effective_reemit are now just the real, live
    // control wires directly -- the exact same behavior remains fully
    // reachable by driving them from any real source.
    wire effective_hold   = hold_in;
    wire effective_reemit = a_reemit_in;

    assign ready_out = ready_bit && armed && active;
    assign program_done = program_done_r;
    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;

    // ── points.md #617/#626: real, widened 4-bit PROG_ID -- the SAME
    // real pressure branch_cell_v4.v hit (#624): 9 real fields +
    // COMPLETE exceed the original 3-bit/8-slot budget. id at [23:20],
    // word at [19:0], same real "ID directly above its own data
    // payload" principle every other core's own layout follows. ──
    localparam [3:0] PROG_ID_TOPOLOGY     = 4'd0;
    localparam [3:0] PROG_ID_ROUTING_MASK = 4'd1;
    localparam [3:0] PROG_ID_CARDINAL_EDGE= 4'd2;
    localparam [3:0] PROG_ID_PATTERN_LOW  = 4'd3;
    localparam [3:0] PROG_ID_PATTERN_EQUAL= 4'd4;
    localparam [3:0] PROG_ID_PATTERN_HIGH = 4'd5;
    localparam [3:0] PROG_ID_DYN_ROUTE_EN = 4'd6;
    localparam [3:0] PROG_ID_ADDON_CONFIG = 4'd7;
    localparam [3:0] PROG_ID_COMPLETE     = 4'd15;

    wire [3:0]  prog_id   = prog_data_val[23:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    // points.md #617: real, new active gate added here -- the ORIGINAL
    // v1 line had no active concept at all (program_in && prog_any_
    // arrived); every other v4 core's own programming_active includes
    // it, extended here for consistency across the whole real family.
    wire programming_active = program_in && active && prog_any_arrived;

    // ── Real, unchanged from v1: OR-combine arrival selection ────────
    wire any_arrived = arrived_n | arrived_s | arrived_e | arrived_w;
    wire [31:0] arrived_val = (arrived_n ? data_in_n : 32'h0) |
                              (arrived_s ? data_in_s : 32'h0) |
                              (arrived_e ? data_in_e : 32'h0) |
                              (arrived_w ? data_in_w : 32'h0);
    wire capture_now = consume_arrived && !a_arrived && !effective_freeze && !program_in;

    wire sel_n = arrived_n;
    wire sel_s = arrived_s;
    wire sel_e = arrived_e;
    wire sel_w = arrived_w;

    // ── Real, unchanged from v1: relay-vs-consume classification. ────
    wire selected_is_relay = (sel_n && cardinal_edge[0]) ||
                             (sel_s && cardinal_edge[1]) ||
                             (sel_e && cardinal_edge[2]) ||
                             (sel_w && cardinal_edge[3]);
    wire relay_arrived   = any_arrived && selected_is_relay;
    wire consume_arrived = any_arrived && !selected_is_relay;

    wire any_relay_dir   = (sel_n && cardinal_edge[0]) || (sel_s && cardinal_edge[1]) ||
                           (sel_e && cardinal_edge[2]) || (sel_w && cardinal_edge[3]);
    wire any_consume_dir = (sel_n && !cardinal_edge[0]) || (sel_s && !cardinal_edge[1]) ||
                           (sel_e && !cardinal_edge[2]) || (sel_w && !cardinal_edge[3]);
    wire relay_mismatch  = any_arrived && any_relay_dir && any_consume_dir;

    // points.md #617: real, new active gate folded in here, matching
    // nano's own existing real convention of composing gates into
    // effective_freeze (rather than a separate effective_armed the
    // way #618-#625's own cores use, since that pattern doesn't exist
    // in nano's own real design to begin with).
    wire effective_freeze = freeze_in || error_frozen || !armed || !active;

    wire internal_fb_active = hold_in && fb_internal_in && !effective_freeze && !program_in;

    wire a_reemit_active = effective_hold && effective_reemit && a_arrived && consume_arrived &&
                           ready_bit && targets_all_ready && !effective_freeze && !program_in;
    wire a_update_active = hold_in && a_update_in && consume_arrived && !effective_freeze && !program_in;

    // ── Real, unchanged from v1: the two-arrival gate computation. ───
    wire [31:0] input_val  = a_arrived ? data_reg : arrived_val;
    wire [31:0] second_val = internal_fb_active ? out_buffer :
                              (a_arrived ? arrived_val : data_reg);

    wire [3:0] effective_routing;

    generate
    if (ENABLE_DYNAMIC_ROUTING) begin : gen_dynamic_routing
        wire cmp_gt = (second_val > input_val);
        wire cmp_lt = (second_val < input_val);
        wire [3:0] selected_pattern = cmp_gt ? pattern_high :
                                      cmp_lt ? pattern_low  :
                                               pattern_equal;
        assign effective_routing = dynamic_route_en ? (selected_pattern & routing_mask[3:0])
                                                     : routing_mask[3:0];
    end else begin : gen_static_routing_only
        assign effective_routing = routing_mask[3:0];
    end
    endgenerate

    wire [31:0] g0 = ~(input_val  | input_val);
    wire [31:0] g1 = ~(second_val | second_val);
    wire [31:0] g2 = ~(g0 | g1);
    wire [31:0] g3 = ~(g2 | g2);
    wire [31:0] g4 = ~(input_val  | second_val);
    wire [31:0] g5 = ~(g4 | g4);
    wire [31:0] g6 = ~(input_val  | g4);
    wire [31:0] g7 = ~(second_val | g4);
    wire [31:0] g8 = ~(g6 | g7);
    wire [31:0] g9 = ~(g8 | g8);

    reg [31:0] computed_output;
    always @(*) begin
        computed_output = input_val;
        case (topology)
            10'h000: computed_output = input_val;
            10'h02C: computed_output = second_val;
            10'h001: computed_output = g0;
            10'h002: computed_output = g1;
            10'h004: computed_output = g4;
            10'h007: computed_output = g2;
            10'h024: computed_output = g5;
            10'h027: computed_output = g3;
            10'h0BC: computed_output = g9;
            10'h03C: computed_output = g8;
            10'h030: computed_output = 32'h0;
            10'h0B0: computed_output = 32'hFFFFFFFF;
            default: computed_output = input_val;
        endcase
    end

    wire new_data = consume_arrived && a_arrived;

    wire want_n = effective_routing[0];
    wire want_s = effective_routing[1];
    wire want_e = effective_routing[2];
    wire want_w = effective_routing[3];

    wire targets_all_ready = (!want_n || ready_in_n) &&
                             (!want_s || ready_in_s) &&
                             (!want_e || ready_in_e) &&
                             (!want_w || ready_in_w);

    // Real, necessary exclusion, found while wiring a real adder_cell_v4
    // into a genuine hold+update closed loop (LLVM phi/loop-var work,
    // points.md #636): can_fire's own condition (new_data=consume_
    // arrived&&a_arrived) is independently satisfied by ANY real
    // arrival while hold_in keeps a_arrived permanently 1 -- including
    // one that's ALSO a_update_in-intended. Without this exclusion,
    // any_fire (below) schedules a spurious extra offer using STALE
    // cmd_latch[127:96] data (a_update_active's own branch never
    // touches it) whenever a real downstream target happens to already
    // be ready during an update -- silently corrupting the very next
    // real arrival this cell captures. ack_out/consumed_now are
    // unaffected: a_update_active already contributes to consumed_now
    // independently, so the real upstream sender is still acked correctly.
    wire can_fire = new_data && ready_bit && targets_all_ready && !effective_freeze && !program_in && !a_update_in;
    wire relay_fire = relay_arrived && ready_bit && targets_all_ready && !effective_freeze && !program_in;

    wire [5:0] targeted_vec = {2'b00, want_w, want_e, want_s, want_n};
    wire [5:0] ack_in_vec   = {2'b00, ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire       any_fire     = can_fire || relay_fire || a_reemit_active;
    wire [5:0] next_pending_ack = any_fire            ? (targeted_vec & ~ack_in_vec) :
                                  (pending_ack != 6'h0) ? (pending_ack  & ~ack_in_vec) :
                                                          pending_ack;
    wire       next_ready = hold_in || (next_pending_ack == 6'h0);

    wire consumed_now = capture_now || can_fire || relay_fire || a_reemit_active || a_update_active;
    assign ack_out_n = consumed_now && sel_n;
    assign ack_out_s = consumed_now && sel_s;
    assign ack_out_e = consumed_now && sel_e;
    assign ack_out_w = consumed_now && sel_w;

    // ── points.md #617: the real, three-addon chain, applied to the
    // offered out_buffer, wired identically to #618-#625's own. ──
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(out_buffer), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    always @(posedge clk) begin
        if (rst) begin
            cmd_latch     <= 128'h0;
            data_reg      <= 32'h0;
            a_arrived     <= 1'b0;
            pending_ack   <= 6'h0;
            program_done_r<= 1'b0;
            error_frozen  <= 1'b0;
            armed         <= 1'b0;
        end else if (cfg_valid) begin
            cmd_latch     <= cfg_data;
            cmd_latch[13] <= 1'b1;
            pending_ack   <= 6'h0;
            error_frozen  <= 1'b0;
            armed         <= 1'b1;
        end else begin
            if (relay_mismatch) error_frozen <= 1'b1;

            if (programming_active) begin
                case (prog_id)
                    PROG_ID_TOPOLOGY:      cmd_latch[9:0]   <= prog_word[9:0];
                    PROG_ID_ROUTING_MASK:  cmd_latch[67:64] <= prog_word[3:0];
                    PROG_ID_CARDINAL_EDGE: cmd_latch[73:70] <= prog_word[3:0];
                    PROG_ID_PATTERN_LOW:   cmd_latch[79:76] <= prog_word[3:0];
                    PROG_ID_PATTERN_EQUAL: cmd_latch[85:82] <= prog_word[3:0];
                    PROG_ID_PATTERN_HIGH:  cmd_latch[91:88] <= prog_word[3:0];
                    PROG_ID_DYN_ROUTE_EN:  cmd_latch[94]    <= prog_word[0];
                    PROG_ID_ADDON_CONFIG:  cmd_latch[33:14] <= prog_word[19:0];
                    PROG_ID_COMPLETE: begin
                        cmd_latch[13]  <= 1'b1;
                        program_done_r <= 1'b1;
                        error_frozen   <= 1'b0;
                        armed          <= prog_word[0];
                    end
                    default: ;
                endcase
            end else if (internal_fb_active) begin
                if (a_self_update_in)
                    data_reg <= computed_output;
                else
                    cmd_latch[127:96] <= computed_output;
            end else if (a_update_active) begin
                data_reg <= arrived_val;
            end else if (a_reemit_active) begin
                cmd_latch[127:96] <= data_reg;
            end else if (capture_now) begin
                data_reg  <= arrived_val;
                a_arrived <= 1'b1;
            end else if (can_fire) begin
                cmd_latch[127:96] <= computed_output;
                a_arrived         <= hold_in;
            end else if (relay_fire) begin
                cmd_latch[127:96] <= arrived_val;
            end

            if (!program_in) program_done_r <= 1'b0;

            pending_ack   <= next_pending_ack;
            cmd_latch[13] <= next_ready;
        end
    end

endmodule

v4c.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// nano_gate_v4c.v — points.md #720: the "c" (carrier) variant of
// nano_gate_v4.v. Same real reasoning as the other _v4c files' own
// headers -- the carrier's whole design concept is to hold common
// functionality centrally, and this core's own internal 3-addon chain
// duplicates exactly what the carrier itself now provides once,
// shared. nano_gate_v4.v itself is UNCHANGED, still the real, proven,
// standalone core.
//
// Real, honest scope of this file's own changes from v4:
//   1. The internal addon chain is REMOVED entirely -- data_out_n/s/
//      e/w now come directly from out_buffer (a wire view into
//      cmd_latch[127:96], unchanged).
//   2. addon_config (a 20-bit VIEW into cmd_latch[33:14], not a
//      separate register) is removed, along with PROG_ID_ADDON_CONFIG.
//      cmd_latch itself is UNCHANGED width (128 bits); those bits are
//      now genuinely reserved again, same as v1 originally had them.
//      PROG_ID_COMPLETE stays at 4'd15, addon_config's own old slot
//      (4'd7) is simply unused now.
//   3. Same real config-off-shell reasoning as every other _v4c file:
//      cmd_latch itself stays a real register (this cell's own live-
//      programming channel needs it independently writable); the real
//      fix lives at the carrier's own shell level.
//
// cmd_latch[127:0] field map (atomic boot-load path) -- IDENTICAL to
// v4's own except addon_config's own old home is reserved again:
//   [9:0]   topology         — same 12 real NOR-decomposed gate codes
//   [10]    reserved         — was is_command_cell (v1), now free
//   [12:11] reserved
//   [13]    ready            — this cell's own readiness
//   [63:14] reserved         — 50 bits (addon_config's own old home,
//                              now genuinely free again, plus the
//                              original 30 bits of headroom)
//   [69:64] routing_mask     — unchanged from v1
//   [75:70] cardinal_edge    — unchanged from v1
//   [81:76] pattern_low      — unchanged from v1
//   [87:82] pattern_equal    — unchanged from v1
//   [93:88] pattern_high     — unchanged from v1
//   [94]    dynamic_route_en — unchanged from v1
//   [95]    reserved
//   [127:96] out_buffer      — unchanged from v1

`default_nettype none
`timescale 1ns / 1ps

module nano_gate_v4c #(
    parameter [15:0] CELL_ID = 16'h0000,
    // Real, unchanged from v1 -- the same measured ALM/timing
    // optimization (#169/silicon session): compile-time gate for the
    // dynamic-routing comparator, zero cost for any cell that never
    // uses it.
    parameter        ENABLE_DYNAMIC_ROUTING = 1'b0
) (
    input  wire        clk,
    input  wire         rst,

    // points.md #617 point 5: real, explicit "active" bit -- folded
    // into effective_freeze alongside armed, matching nano's own
    // existing real convention (see header).
    input  wire         active,

    input  wire         cfg_valid,
    input  wire [127:0] cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    input  wire         freeze_in,

    // ── Real, unchanged live control wires from v1 -- these are
    // genuinely live control, not config, per v1's own real,
    // established distinction (see header of unicell_stripped_v1.v). ──
    input  wire         hold_in,
    input  wire         fb_internal_in,
    input  wire         a_reemit_in,
    input  wire         a_update_in,
    input  wire         a_self_update_in,

    // ── points.md #617: real, targeted programming channel -- ALREADY
    // nano's own real mechanism, unchanged in shape, extended with one
    // new real field and a widened 4-bit ID (see header). ──
    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w
);

    // ── State — real, unchanged from v1 ──────────────────────────────
    reg [127:0] cmd_latch  = 128'h0;
    reg [31:0]  data_reg   = 32'h0;
    reg         a_arrived  = 1'b0;
    reg [5:0]   pending_ack= 6'h0;
    reg         program_done_r = 1'b0;
    reg         error_frozen = 1'b0;
    reg         armed = 1'b0;

    wire [9:0] topology     = cmd_latch[9:0];
    wire       ready_bit    = cmd_latch[13];
    wire [5:0] routing_mask = cmd_latch[69:64];
    wire [5:0] cardinal_edge= cmd_latch[75:70];
    wire [31:0] out_buffer  = cmd_latch[127:96];

    wire [3:0] pattern_low    = cmd_latch[79:76];
    wire [3:0] pattern_equal  = cmd_latch[85:82];
    wire [3:0] pattern_high   = cmd_latch[91:88];
    wire       dynamic_route_en = cmd_latch[94];

    // Real, deliberate removal (see header): is_command_cell is gone.
    // effective_hold/effective_reemit are now just the real, live
    // control wires directly -- the exact same behavior remains fully
    // reachable by driving them from any real source.
    wire effective_hold   = hold_in;
    wire effective_reemit = a_reemit_in;

    assign ready_out = ready_bit && armed && active;
    assign program_done = program_done_r;
    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;

    // ── points.md #617/#626: real, widened 4-bit PROG_ID -- the SAME
    // real pressure branch_cell_v4.v hit (#624): 9 real fields +
    // COMPLETE exceed the original 3-bit/8-slot budget. id at [23:20],
    // word at [19:0], same real "ID directly above its own data
    // payload" principle every other core's own layout follows. ──
    localparam [3:0] PROG_ID_TOPOLOGY     = 4'd0;
    localparam [3:0] PROG_ID_ROUTING_MASK = 4'd1;
    localparam [3:0] PROG_ID_CARDINAL_EDGE= 4'd2;
    localparam [3:0] PROG_ID_PATTERN_LOW  = 4'd3;
    localparam [3:0] PROG_ID_PATTERN_EQUAL= 4'd4;
    localparam [3:0] PROG_ID_PATTERN_HIGH = 4'd5;
    localparam [3:0] PROG_ID_DYN_ROUTE_EN = 4'd6;
    localparam [3:0] PROG_ID_COMPLETE     = 4'd15;

    wire [3:0]  prog_id   = prog_data_val[23:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    // points.md #617: real, new active gate added here -- the ORIGINAL
    // v1 line had no active concept at all (program_in && prog_any_
    // arrived); every other v4 core's own programming_active includes
    // it, extended here for consistency across the whole real family.
    wire programming_active = program_in && active && prog_any_arrived;

    // ── Real, unchanged from v1: OR-combine arrival selection ────────
    wire any_arrived = arrived_n | arrived_s | arrived_e | arrived_w;
    wire [31:0] arrived_val = (arrived_n ? data_in_n : 32'h0) |
                              (arrived_s ? data_in_s : 32'h0) |
                              (arrived_e ? data_in_e : 32'h0) |
                              (arrived_w ? data_in_w : 32'h0);
    wire capture_now = consume_arrived && !a_arrived && !effective_freeze && !program_in;

    wire sel_n = arrived_n;
    wire sel_s = arrived_s;
    wire sel_e = arrived_e;
    wire sel_w = arrived_w;

    // ── Real, unchanged from v1: relay-vs-consume classification. ────
    wire selected_is_relay = (sel_n && cardinal_edge[0]) ||
                             (sel_s && cardinal_edge[1]) ||
                             (sel_e && cardinal_edge[2]) ||
                             (sel_w && cardinal_edge[3]);
    wire relay_arrived   = any_arrived && selected_is_relay;
    wire consume_arrived = any_arrived && !selected_is_relay;

    wire any_relay_dir   = (sel_n && cardinal_edge[0]) || (sel_s && cardinal_edge[1]) ||
                           (sel_e && cardinal_edge[2]) || (sel_w && cardinal_edge[3]);
    wire any_consume_dir = (sel_n && !cardinal_edge[0]) || (sel_s && !cardinal_edge[1]) ||
                           (sel_e && !cardinal_edge[2]) || (sel_w && !cardinal_edge[3]);
    wire relay_mismatch  = any_arrived && any_relay_dir && any_consume_dir;

    // points.md #617: real, new active gate folded in here, matching
    // nano's own existing real convention of composing gates into
    // effective_freeze (rather than a separate effective_armed the
    // way #618-#625's own cores use, since that pattern doesn't exist
    // in nano's own real design to begin with).
    wire effective_freeze = freeze_in || error_frozen || !armed || !active;

    wire internal_fb_active = hold_in && fb_internal_in && !effective_freeze && !program_in;

    wire a_reemit_active = effective_hold && effective_reemit && a_arrived && consume_arrived &&
                           ready_bit && targets_all_ready && !effective_freeze && !program_in;
    wire a_update_active = hold_in && a_update_in && consume_arrived && !effective_freeze && !program_in;

    // ── Real, unchanged from v1: the two-arrival gate computation. ───
    wire [31:0] input_val  = a_arrived ? data_reg : arrived_val;
    wire [31:0] second_val = internal_fb_active ? out_buffer :
                              (a_arrived ? arrived_val : data_reg);

    wire [3:0] effective_routing;

    generate
    if (ENABLE_DYNAMIC_ROUTING) begin : gen_dynamic_routing
        wire cmp_gt = (second_val > input_val);
        wire cmp_lt = (second_val < input_val);
        wire [3:0] selected_pattern = cmp_gt ? pattern_high :
                                      cmp_lt ? pattern_low  :
                                               pattern_equal;
        assign effective_routing = dynamic_route_en ? (selected_pattern & routing_mask[3:0])
                                                     : routing_mask[3:0];
    end else begin : gen_static_routing_only
        assign effective_routing = routing_mask[3:0];
    end
    endgenerate

    wire [31:0] g0 = ~(input_val  | input_val);
    wire [31:0] g1 = ~(second_val | second_val);
    wire [31:0] g2 = ~(g0 | g1);
    wire [31:0] g3 = ~(g2 | g2);
    wire [31:0] g4 = ~(input_val  | second_val);
    wire [31:0] g5 = ~(g4 | g4);
    wire [31:0] g6 = ~(input_val  | g4);
    wire [31:0] g7 = ~(second_val | g4);
    wire [31:0] g8 = ~(g6 | g7);
    wire [31:0] g9 = ~(g8 | g8);

    reg [31:0] computed_output;
    always @(*) begin
        computed_output = input_val;
        case (topology)
            10'h000: computed_output = input_val;
            10'h02C: computed_output = second_val;
            10'h001: computed_output = g0;
            10'h002: computed_output = g1;
            10'h004: computed_output = g4;
            10'h007: computed_output = g2;
            10'h024: computed_output = g5;
            10'h027: computed_output = g3;
            10'h0BC: computed_output = g9;
            10'h03C: computed_output = g8;
            10'h030: computed_output = 32'h0;
            10'h0B0: computed_output = 32'hFFFFFFFF;
            default: computed_output = input_val;
        endcase
    end

    wire new_data = consume_arrived && a_arrived;

    wire want_n = effective_routing[0];
    wire want_s = effective_routing[1];
    wire want_e = effective_routing[2];
    wire want_w = effective_routing[3];

    wire targets_all_ready = (!want_n || ready_in_n) &&
                             (!want_s || ready_in_s) &&
                             (!want_e || ready_in_e) &&
                             (!want_w || ready_in_w);

    // Real, necessary exclusion, found while wiring a real adder_cell_v4
    // into a genuine hold+update closed loop (LLVM phi/loop-var work,
    // points.md #636): can_fire's own condition (new_data=consume_
    // arrived&&a_arrived) is independently satisfied by ANY real
    // arrival while hold_in keeps a_arrived permanently 1 -- including
    // one that's ALSO a_update_in-intended. Without this exclusion,
    // any_fire (below) schedules a spurious extra offer using STALE
    // cmd_latch[127:96] data (a_update_active's own branch never
    // touches it) whenever a real downstream target happens to already
    // be ready during an update -- silently corrupting the very next
    // real arrival this cell captures. ack_out/consumed_now are
    // unaffected: a_update_active already contributes to consumed_now
    // independently, so the real upstream sender is still acked correctly.
    wire can_fire = new_data && ready_bit && targets_all_ready && !effective_freeze && !program_in && !a_update_in;
    wire relay_fire = relay_arrived && ready_bit && targets_all_ready && !effective_freeze && !program_in;

    wire [5:0] targeted_vec = {2'b00, want_w, want_e, want_s, want_n};
    wire [5:0] ack_in_vec   = {2'b00, ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire       any_fire     = can_fire || relay_fire || a_reemit_active;
    wire [5:0] next_pending_ack = any_fire            ? (targeted_vec & ~ack_in_vec) :
                                  (pending_ack != 6'h0) ? (pending_ack  & ~ack_in_vec) :
                                                          pending_ack;
    wire       next_ready = hold_in || (next_pending_ack == 6'h0);

    wire consumed_now = capture_now || can_fire || relay_fire || a_reemit_active || a_update_active;
    assign ack_out_n = consumed_now && sel_n;
    assign ack_out_s = consumed_now && sel_s;
    assign ack_out_e = consumed_now && sel_e;
    assign ack_out_w = consumed_now && sel_w;

    // ── points.md #720: NO addon chain here at all — the carrier
    // already provides one, shared across whichever core is active. ──
    assign data_out_n = out_buffer;
    assign data_out_s = out_buffer;
    assign data_out_e = out_buffer;
    assign data_out_w = out_buffer;

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    always @(posedge clk) begin
        if (rst) begin
            cmd_latch     <= 128'h0;
            data_reg      <= 32'h0;
            a_arrived     <= 1'b0;
            pending_ack   <= 6'h0;
            program_done_r<= 1'b0;
            error_frozen  <= 1'b0;
            armed         <= 1'b0;
        end else if (cfg_valid) begin
            cmd_latch     <= cfg_data;
            cmd_latch[13] <= 1'b1;
            pending_ack   <= 6'h0;
            error_frozen  <= 1'b0;
            armed         <= 1'b1;
        end else begin
            if (relay_mismatch) error_frozen <= 1'b1;

            if (programming_active) begin
                case (prog_id)
                    PROG_ID_TOPOLOGY:      cmd_latch[9:0]   <= prog_word[9:0];
                    PROG_ID_ROUTING_MASK:  cmd_latch[67:64] <= prog_word[3:0];
                    PROG_ID_CARDINAL_EDGE: cmd_latch[73:70] <= prog_word[3:0];
                    PROG_ID_PATTERN_LOW:   cmd_latch[79:76] <= prog_word[3:0];
                    PROG_ID_PATTERN_EQUAL: cmd_latch[85:82] <= prog_word[3:0];
                    PROG_ID_PATTERN_HIGH:  cmd_latch[91:88] <= prog_word[3:0];
                    PROG_ID_DYN_ROUTE_EN:  cmd_latch[94]    <= prog_word[0];
                    PROG_ID_COMPLETE: begin
                        cmd_latch[13]  <= 1'b1;
                        program_done_r <= 1'b1;
                        error_frozen   <= 1'b0;
                        armed          <= prog_word[0];
                    end
                    default: ;
                endcase
            end else if (internal_fb_active) begin
                if (a_self_update_in)
                    data_reg <= computed_output;
                else
                    cmd_latch[127:96] <= computed_output;
            end else if (a_update_active) begin
                data_reg <= arrived_val;
            end else if (a_reemit_active) begin
                cmd_latch[127:96] <= data_reg;
            end else if (capture_now) begin
                data_reg  <= arrived_val;
                a_arrived <= 1'b1;
            end else if (can_fire) begin
                cmd_latch[127:96] <= computed_output;
                a_arrived         <= hold_in;
            end else if (relay_fire) begin
                cmd_latch[127:96] <= arrived_val;
            end

            if (!program_in) program_done_r <= 1'b0;

            pending_ack   <= next_pending_ack;
            cmd_latch[13] <= next_ready;
        end
    end

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// nano_cell_v4s.v -- points.md #917: the stripped version of the real,
// original logic core, `nano_gate_v4c.v` -- the one cell this whole family
// has been missing since being flagged as the real structural exception back
// in #898/#899, finally built.
//
// The real function, read from nano_gate_v4c.v directly and verified by hand
// before trusting it (a full truth-table check against every one of its 12
// real cases, not assumed from the gate names alone): a universal 2-input
// logic function, selected by a `topology` field, applied between a HELD
// operand and a FLOWING one:
//   topology 10'h000: pass through HELD
//   topology 10'h02C: pass through FLOW
//   topology 10'h001: NOT HELD
//   topology 10'h002: NOT FLOW
//   topology 10'h004: NOR(HELD, FLOW)
//   topology 10'h007: AND(HELD, FLOW)
//   topology 10'h024: OR(HELD, FLOW)
//   topology 10'h027: NAND(HELD, FLOW)
//   topology 10'h0BC: XOR(HELD, FLOW)
//   topology 10'h03C: XNOR(HELD, FLOW)
//   topology 10'h030: constant all-zero
//   topology 10'h0B0: constant all-one
//   any other value: pass through HELD (the original's own default)
//
// The real structural exception this cell needed, per #898's own framing:
// every other v4s cell is fixed-role, single-shot-per-cycle -- this one
// genuinely needs TWO different input roles. The original solved this with
// `hold_in` (a continuous level: while high, the cell's `a_arrived` stays
// permanently set, so `input_val` keeps using the SAME captured value while
// `second_val` tracks each fresh arrival) plus cardinal arrival-order
// tracking to tell the two operands apart on a shared wire. With no more
// cardinal routing or arrival-order tricks in this family, the two roles get
// two genuinely dedicated ports instead: `hold_in_data` (loaded rarely, via
// an explicit `load_hold` pulse -- there is no more "first arrival" to
// infer it from) and `flow_in_data` (a new value every time `valid_in`
// fires), matching the same "one dedicated wire per real role" principle
// `adder_cell_v4s.v`'s own `in_a`/`in_b` already established, applied here
// to a cell whose two roles are genuinely different in KIND (one persistent,
// one transient), not just two equal operands.
//
// What's stripped, same reasoning as every other v4s cell: the real 4-way
// cardinal routing (routing_mask/cardinal_edge/dynamic routing) is gone --
// a fixed, single output, the family's own "no cardinality" principle. Live
// reprogramming (program_in and the whole prog_id channel) is gone -- #899's
// own established choice, boot-load config only. Relay-vs-consume
// classification, internal feedback/self-update, and the ack/pending_ack
// mask machinery are all gone -- that machinery existed specifically to
// serve cardinal routing and live reprogramming, both removed here.
//
// cfg_data field map:
//   [9:0] topology -- the same 12 real gate codes, unchanged from the original
`default_nettype none
`timescale 1ns / 1ps

module nano_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,

    input  wire [31:0]  hold_in_data,
    input  wire         load_hold,     // explicit "capture hold_in_data now" pulse

    input  wire [31:0]  flow_in_data,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg [9:0]  topology    = 10'h0;
    reg        armed       = 1'b0;
    reg [31:0] held_value  = 32'h0;
    reg [31:0] out_buffer  = 32'h0;
    reg        valid_out_r = 1'b0;

    // ── The real gate logic -- unchanged from nano_gate_v4c.v, verified by
    // a full truth-table check before trusting it, not assumed from names ──
    wire [31:0] g0 = ~(held_value    | held_value);      // NOT HELD
    wire [31:0] g1 = ~(flow_in_data  | flow_in_data);    // NOT FLOW
    wire [31:0] g2 = ~(g0 | g1);                         // AND(HELD, FLOW)
    wire [31:0] g3 = ~(g2 | g2);                         // NAND(HELD, FLOW)
    wire [31:0] g4 = ~(held_value    | flow_in_data);    // NOR(HELD, FLOW)
    wire [31:0] g5 = ~(g4 | g4);                         // OR(HELD, FLOW)
    wire [31:0] g6 = ~(held_value | g4);
    wire [31:0] g7 = ~(flow_in_data | g4);
    wire [31:0] g8 = ~(g6 | g7);                         // XNOR(HELD, FLOW)
    wire [31:0] g9 = ~(g8 | g8);                         // XOR(HELD, FLOW)

    reg [31:0] computed_output;
    always @(*) begin
        computed_output = held_value;
        case (topology)
            10'h000: computed_output = held_value;
            10'h02C: computed_output = flow_in_data;
            10'h001: computed_output = g0;
            10'h002: computed_output = g1;
            10'h004: computed_output = g4;
            10'h007: computed_output = g2;
            10'h024: computed_output = g5;
            10'h027: computed_output = g3;
            10'h0BC: computed_output = g9;
            10'h03C: computed_output = g8;
            10'h030: computed_output = 32'h0;
            10'h0B0: computed_output = 32'hFFFFFFFF;
            default: computed_output = held_value;
        endcase
    end

    assign data_out  = out_buffer;
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            topology    <= 10'h0;
            armed       <= 1'b0;
            held_value  <= 32'h0;
            out_buffer  <= 32'h0;
            valid_out_r <= 1'b0;
        end else if (cfg_valid) begin
            topology    <= cfg_data[9:0];
            armed       <= 1'b1;
            valid_out_r <= 1'b0;
        end else begin
            if (load_hold) held_value <= hold_in_data;
            out_buffer  <= computed_output;
            valid_out_r <= armed && valid_in;
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// nano_cell_v4sa.v -- points.md #917: the Flex-Sub shape (ack+freeze per
// #906, WIDTH per #909/#910) applied to nano_cell_v4s.v, built to compare
// against it directly, per Alan's own request.
//
// Same real universal 2-input gate function as nano_cell_v4s.v -- see that
// file's own header for the full, hand-verified truth table and the real
// reasoning for the dedicated hold_in_data/flow_in_data two-port shape. No
// change to the function itself; only the family's standard ack+freeze+WIDTH
// treatment added on top.
//
// One real design choice worth stating: `load_hold` is treated as its own
// event, gated by the SAME pending/ack discipline as a normal flowing
// capture would be -- loading a new hold value and presenting a normal
// computed offer are mutually exclusive on any one cycle (matching the
// family's own established "exactly one real thing happens per cycle,
// never two" convention, e.g. router_cell_v4sa.v's clear-vs-capture
// priority). `load_hold` does not itself produce an offer -- it is a real,
// silent side effect that changes what future flowing captures compute
// against, consistent with the original cell's own real behaviour (loading
// the hold was never itself an "output" event there either).
//
// cfg_data field map, unchanged: [9:0] topology.
`default_nettype none
`timescale 1ns / 1ps

module nano_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,

    input  wire [WIDTH-1:0]  hold_in_data,
    input  wire               load_hold,

    input  wire [WIDTH-1:0]  flow_in_data,
    input  wire               valid_in,
    output wire                ack_out,     // backward, to whoever drives flow_in_data/valid_in

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in       // backward, from the one fixed downstream receiver
);

    reg [9:0]       topology    = 10'h0;
    reg             armed       = 1'b0;
    reg             pending     = 1'b0;
    reg [WIDTH-1:0] held_value  = {WIDTH{1'b0}};
    reg [WIDTH-1:0] out_buffer  = {WIDTH{1'b0}};

    // ── The real gate logic -- unchanged from nano_cell_v4s.v, hand-verified
    // against a full truth table before trusting it (see that file's header) ──
    wire [WIDTH-1:0] g0 = ~(held_value    | held_value);
    wire [WIDTH-1:0] g1 = ~(flow_in_data  | flow_in_data);
    wire [WIDTH-1:0] g2 = ~(g0 | g1);
    wire [WIDTH-1:0] g3 = ~(g2 | g2);
    wire [WIDTH-1:0] g4 = ~(held_value    | flow_in_data);
    wire [WIDTH-1:0] g5 = ~(g4 | g4);
    wire [WIDTH-1:0] g6 = ~(held_value | g4);
    wire [WIDTH-1:0] g7 = ~(flow_in_data | g4);
    wire [WIDTH-1:0] g8 = ~(g6 | g7);
    wire [WIDTH-1:0] g9 = ~(g8 | g8);

    reg [WIDTH-1:0] computed_output;
    always @(*) begin
        computed_output = held_value;
        case (topology)
            10'h000: computed_output = held_value;
            10'h02C: computed_output = flow_in_data;
            10'h001: computed_output = g0;
            10'h002: computed_output = g1;
            10'h004: computed_output = g4;
            10'h007: computed_output = g2;
            10'h024: computed_output = g5;
            10'h027: computed_output = g3;
            10'h0BC: computed_output = g9;
            10'h03C: computed_output = g8;
            10'h030: computed_output = {WIDTH{1'b0}};
            10'h0B0: computed_output = {WIDTH{1'b1}};
            default: computed_output = held_value;
        endcase
    end

    assign data_out  = out_buffer;
    assign valid_out = pending;
    assign ack_out   = armed && !pending && !freeze_in;

    always @(posedge clk) begin
        if (rst) begin
            topology    <= 10'h0;
            armed       <= 1'b0;
            pending     <= 1'b0;
            held_value  <= {WIDTH{1'b0}};
            out_buffer  <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            topology    <= cfg_data[9:0];
            armed       <= 1'b1;
            pending     <= 1'b0;
        end else if (!freeze_in) begin
            // load_hold is a real, silent side effect -- it changes what
            // future captures compute against, but is not itself an offer.
            if (load_hold) held_value <= hold_in_data;

            if (pending) begin
                if (ack_in) pending <= 1'b0;
            end else if (valid_in && armed) begin   // ledger #971: gated by `armed` like every other v4sa cell (an UNCONFIGURED nano used to capture and offer)
                out_buffer <= computed_output;
                pending    <= 1'b1;
            end
        end
    end

endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// mul_cell_v4.v — points.md #724: a real, new "unified carrier" core,
// the 10th, built directly on adder_cell_v4.v's own proven shape
// (same two-stage A/B capture, same shell richness -- programming
// channel, addon chain, 6-way cardinality headroom, active/freeze).
// The one real, substantive difference: the core arithmetic itself is
// bitwise_multiplier_32bit.v (#724, promoted from a contributed,
// already-iverilog-verified combinational design in docs/stripped-
// cell/design-notes/future-core-candidates/), not adder_v1.v.
//
// Real, honest scope decisions, stated plainly:
//   - subtract_mode has no real equivalent for multiply and is
//     REMOVED entirely (not left as a dead field) -- this core always
//     computes A*B, nothing else. Its own old cfg_data bit [12] is
//     genuinely reserved now.
//   - LLVM's own `mul` on i32 truncates to the low 32 bits (standard
//     two's-complement wraparound, the same real semantic `add`/`sub`
//     already use here) -- this core offers Product[31:0] as its real
//     result. The high 32 bits (needed for a real, future `mulh`/
//     `umulh`) are computed by the real combinational multiplier but
//     not offered anywhere in THIS core; a future core could tap the
//     same real multiplier for that half without duplicating the
//     multiply itself.
//   - The real multiplier itself is purely combinational (zero clock
//     cycles of latency, confirmed directly in its own real
//     iverilog-verified form before this promotion) -- capturing B
//     and firing the real product happens on the exact same real
//     two-stage cycle count as add/sub/every other arithmetic core
//     here, no extra latency introduced.
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   downstream_mask  — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  upstream_mask    — one-hot(s), N/S/E/W real + 2 reserved
//   [12]    reserved         — subtract_mode's own old home, no real
//                              equivalent for multiply
//   [32:13] addon_config     — 20 bits, SAME real layout as every
//                              other _v4 core's own addon chain
//   [63:33] reserved
`default_nettype none
`timescale 1ns / 1ps

module mul_cell_v4 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid,
    output wire         status_a_arrived
);

    reg [31:0] a_reg           = 32'h0;
    reg        a_arrived       = 1'b0;
    reg [31:0] out_buffer      = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg [19:0] addon_config    = 20'h0;
    reg [3:0]  pending_ack     = 4'h0;
    reg        armed           = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    wire sel_n = arrived_n && upstream_mask[0];
    wire sel_s = arrived_s && upstream_mask[1];
    wire sel_e = arrived_e && upstream_mask[2];
    wire sel_w = arrived_w && upstream_mask[3];
    wire any_upstream_arrived = sel_n | sel_s | sel_e | sel_w;
    wire [31:0] upstream_val = (sel_n ? data_in_n : 32'h0) |
                               (sel_s ? data_in_s : 32'h0) |
                               (sel_e ? data_in_e : 32'h0) |
                               (sel_w ? data_in_w : 32'h0);

    wire capture_now = any_upstream_arrived && !a_arrived && !effective_freeze &&
                       effective_armed && !program_in;
    wire can_fire = any_upstream_arrived && a_arrived && !data_valid && !effective_freeze &&
                    effective_armed && !program_in;

    assign ack_out_n = (capture_now || can_fire) && sel_n;
    assign ack_out_s = (capture_now || can_fire) && sel_s;
    assign ack_out_e = (capture_now || can_fire) && sel_e;
    assign ack_out_w = (capture_now || can_fire) && sel_w;

    // ── The real arithmetic — the one real, substantive difference
    // from adder_cell_v4.v. Purely combinational, zero clock cycles
    // of latency (confirmed directly before this promotion). Only the
    // low 32 bits are offered here, matching LLVM's own real `mul`
    // truncation semantics. ──
    wire [63:0] mul_product;
    bitwise_multiplier_32bit MUL (
        .A(a_reg), .B(upstream_val), .Product(mul_product)
    );
    wire [31:0] mul_result = mul_product[31:0];

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #617's own real, three-addon chain, wired exactly
    // as every other _v4 core's own -- same order, same 20-bit
    // addon_config layout, reused verbatim. ──
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(out_buffer), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    assign ready_out = effective_armed && !effective_freeze && !(a_arrived && data_valid);
    assign status_data_valid = data_valid;
    assign status_a_arrived  = a_arrived;

    // points.md #724: subtract_mode's own old PROG_ID slot (3'd2)
    // removed entirely (no real equivalent for multiply); addon_
    // config keeps its own old ID (3'd3) rather than renumbering.
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_ADDON_CONFIG    = 3'd3;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            a_reg           <= 32'h0;
            a_arrived       <= 1'b0;
            out_buffer      <= 32'h0;
            data_valid      <= 1'b0;
            downstream_mask <= 6'h0;
            upstream_mask   <= 6'h0;
            addon_config    <= 20'h0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            addon_config    <= cfg_data[32:13];
            a_arrived       <= 1'b0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_ADDON_CONFIG:    addon_config    <= prog_word[19:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (can_fire) begin
                out_buffer <= mul_result;
                data_valid <= 1'b1;
                a_arrived  <= 1'b0;
            end else if (capture_now) begin
                a_reg     <= upstream_val;
                a_arrived <= 1'b1;
            end

            if (offer_draining) begin
                data_valid <= 1'b0;
            end
            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4c.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// mul_cell_v4c.v — points.md #724: the "c" (carrier) variant of
// mul_cell_v4.v, built alongside it from the start (unlike the other
// 9 cores, whose _v4c variants were a later correction, #720) --
// Alan's own direct instruction to build both together this time.
// Same real reasoning as every other _v4c file's own header -- the
// carrier's whole design concept is to hold common functionality
// centrally, and this core's own internal 3-addon chain duplicates
// exactly what the carrier itself now provides once, shared.
// mul_cell_v4.v itself is UNCHANGED, still the real, proven,
// standalone core.
//
// Real, honest scope of this file's own changes from v4:
//   1. The internal addon chain is REMOVED entirely -- data_out_n/s/
//      e/w now come directly from out_buffer, the real computed
//      product's own low 32 bits.
//   2. addon_config (20 bits) is removed from cfg_data's own field
//      map, the register, and PROG_ID_ADDON_CONFIG. cfg_data KEEPS
//      its original 64-bit width; PROG_ID_COMPLETE stays at 3'd7,
//      addon_config's own old slot (3'd3) is simply unused now.
//   3. Same real config-off-shell reasoning as every other _v4c file
//      (confirmed correct the hard way in #723): this core's own
//      real config fields STAY registers, fed from the carrier's own
//      combinational incoming_config (the value about to be
//      committed), NOT the registered core_config -- a core that
//      latches once on its own cfg_valid needs the value that's about
//      to land, not the one that already did.
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   downstream_mask  — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  upstream_mask    — one-hot(s), N/S/E/W real + 2 reserved
//   [12]    reserved         — subtract_mode's own old home in
//                              adder_cell_v4c.v; never existed here at
//                              all (multiply has no equivalent)
//   [63:13] reserved         — 51 bits (addon_config's own old home,
//                              now genuinely free, plus the original
//                              31 bits of headroom)

`default_nettype none
`timescale 1ns / 1ps

module mul_cell_v4c #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid,
    output wire         status_a_arrived
);

    reg [31:0] a_reg           = 32'h0;
    reg        a_arrived       = 1'b0;
    reg [31:0] out_buffer      = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg [3:0]  pending_ack     = 4'h0;
    reg        armed           = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    wire sel_n = arrived_n && upstream_mask[0];
    wire sel_s = arrived_s && upstream_mask[1];
    wire sel_e = arrived_e && upstream_mask[2];
    wire sel_w = arrived_w && upstream_mask[3];
    wire any_upstream_arrived = sel_n | sel_s | sel_e | sel_w;
    wire [31:0] upstream_val = (sel_n ? data_in_n : 32'h0) |
                               (sel_s ? data_in_s : 32'h0) |
                               (sel_e ? data_in_e : 32'h0) |
                               (sel_w ? data_in_w : 32'h0);

    wire capture_now = any_upstream_arrived && !a_arrived && !effective_freeze &&
                       effective_armed && !program_in;
    wire can_fire = any_upstream_arrived && a_arrived && !data_valid && !effective_freeze &&
                    effective_armed && !program_in;

    assign ack_out_n = (capture_now || can_fire) && sel_n;
    assign ack_out_s = (capture_now || can_fire) && sel_s;
    assign ack_out_e = (capture_now || can_fire) && sel_e;
    assign ack_out_w = (capture_now || can_fire) && sel_w;

    // ── The real arithmetic — the one real, substantive difference
    // from adder_cell_v4.v. Purely combinational, zero clock cycles
    // of latency (confirmed directly before this promotion). Only the
    // low 32 bits are offered here, matching LLVM's own real `mul`
    // truncation semantics. ──
    wire [63:0] mul_product;
    bitwise_multiplier_32bit MUL (
        .A(a_reg), .B(upstream_val), .Product(mul_product)
    );
    wire [31:0] mul_result = mul_product[31:0];

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #724: NO addon chain here at all — the carrier
    // already provides one, shared across whichever core is active. ──
    assign data_out_n = out_buffer;
    assign data_out_s = out_buffer;
    assign data_out_e = out_buffer;
    assign data_out_w = out_buffer;

    assign ready_out = effective_armed && !effective_freeze && !(a_arrived && data_valid);
    assign status_data_valid = data_valid;
    assign status_a_arrived  = a_arrived;

    // points.md #724: subtract_mode's own old PROG_ID slot (3'd2)
    // removed entirely (no real equivalent for multiply); addon_
    // config keeps its own old ID (3'd3) rather than renumbering.
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            a_reg           <= 32'h0;
            a_arrived       <= 1'b0;
            out_buffer      <= 32'h0;
            data_valid      <= 1'b0;
            downstream_mask <= 6'h0;
            upstream_mask   <= 6'h0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
        end else if (cfg_valid) begin
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            a_arrived       <= 1'b0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (can_fire) begin
                out_buffer <= mul_result;
                data_valid <= 1'b1;
                a_arrived  <= 1'b0;
            end else if (capture_now) begin
                a_reg     <= upstream_val;
                a_arrived <= 1'b1;
            end

            if (offer_draining) begin
                data_valid <= 1'b0;
            end
            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// mul_cell_v4s.v -- stripped version of mul_cell_v4c.v's real function. Exactly
// adder_cell_v4s.v's own shape: this is the textbook case of Alan's own stated
// v4s rule -- however many genuinely distinct roles a function needs, that's how
// many dedicated ports it gets, never a runtime decision about which port means
// what. Multiply needs two real operands, same as add; two dedicated ports
// (in_a, in_b), same as adder_cell_v4s, no cardinality, no mask.
//
// The real arithmetic -- unchanged, same bitwise_multiplier_32bit primitive
// mul_cell_v4/v4c already use, purely combinational, zero clock cycles of its
// own latency (confirmed directly in that primitive's own header). Only the low
// 32 bits of the real 64-bit product are offered, matching mul_cell_v4c's own
// real LLVM-mul-truncation convention.
//
// No config fields at all -- unlike adder (which keeps one bit for
// subtract_mode), multiply has no equivalent mode to select. cfg_valid still
// exists purely to arm the cell, matching every other v4s cell's convention.
`default_nettype none
`timescale 1ns / 1ps

module mul_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,   // unused; kept for a uniform port shape

    input  wire [31:0]  in_a,
    input  wire [31:0]  in_b,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        armed       = 1'b0;
    reg [31:0] out_buffer  = 32'h0;
    reg        valid_out_r = 1'b0;

    // ── The real arithmetic -- unchanged from mul_cell_v4/v4c ────────────
    wire [63:0] mul_product;
    bitwise_multiplier_32bit MUL (
        .A(in_a), .B(in_b), .Product(mul_product)
    );

    assign data_out  = out_buffer;
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            out_buffer  <= 32'h0;
            valid_out_r <= 1'b0;
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            valid_out_r <= 1'b0;
        end else begin
            // Fixed one-cycle latency, unconditional once armed -- same
            // convention as every other v4s cell.
            out_buffer  <= mul_product[31:0];
            valid_out_r <= armed && valid_in;
        end
    end

endmodule

// mul_cell_v4s_dsp.v -- points.md #901 experiment: same real function as
// mul_cell_v4s.v, but the multiply itself is a plain, native `a * b` (per Alan's
// own real DSP-inference example), not the hand-built bitwise_multiplier_32bit
// array multiplier. Real question being tested: does yosys's synth_gowin
// actually map this onto the chip's real MULT18X18/MULT36X36 DSP blocks (48
// available, confirmed sitting at 0 used in every report so far this session),
// or does it still fall back to LUT fabric regardless of RTL style?
`default_nettype none
`timescale 1ns / 1ps

module mul_cell_v4s_dsp #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,   // unused; kept for a uniform port shape

    input  wire [31:0]  in_a,
    input  wire [31:0]  in_b,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        armed       = 1'b0;
    reg [63:0] out_buffer  = 64'h0;   // full real product this time, not pre-truncated
    reg        valid_out_r = 1'b0;

    assign data_out  = out_buffer[31:0];
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            out_buffer  <= 64'h0;
            valid_out_r <= 1'b0;
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            valid_out_r <= 1'b0;
        end else begin
            // Plain multiply -- the pattern a DSP-inference pass actually looks
            // for, per Alan's own real example.
            out_buffer  <= in_a * in_b;
            valid_out_r <= armed && valid_in;
        end
    end

endmodule

// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// mul_cell_v4s_dsp2.v -- points.md #901: real DSP-block multiply, per Alan's own
// example and correction. #901's first attempt (a plain `a * b`) confirmed a real
// toolchain gap: yosys's `synth_gowin` pass does NOT automatically infer the
// chip's real DSP blocks for a plain multiply (measured: identical LUT4 count,
// zero DSP primitives used) -- unlike Gowin's own proprietary compiler, which
// does exactly this per Alan's own real example. There is no `dsp_map.v`-style
// inference pass in this yosys's Gowin techlibs at all.
//
// The real primitives DO exist and ARE usable, though -- `MULT36X36` is declared
// as a real blackbox in yosys's own `cells_xtra.v` (confirmed by inspection, not
// assumed), covering our 32x32 need with 4 bits of unused headroom on each
// operand. This file instantiates it directly rather than relying on inference.
//
// ASIGN/BSIGN tied low (unsigned multiply, matching bitwise_multiplier_32bit's
// own existing unsigned behaviour, and mul_cell_v4s.v's for a fair comparison).
// AREG/BREG/OUT0_REG all left at their default 0 (no internal DSP pipeline
// registers) so this primitive's own real behaviour matches the family's
// existing fixed-one-cycle-latency convention exactly: the SAME external
// out_buffer register this cell already used still provides that one cycle,
// nothing added or hidden inside the DSP block itself.
`default_nettype none
`timescale 1ns / 1ps

module mul_cell_v4s_dsp2 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,   // unused; kept for a uniform port shape

    input  wire [31:0]  in_a,
    input  wire [31:0]  in_b,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        armed       = 1'b0;
    reg [31:0] out_buffer  = 32'h0;
    reg        valid_out_r = 1'b0;

    // ── The real DSP block, instantiated directly ────────────────────────
    wire [71:0] dsp_product;
    MULT36X36 #(
        .AREG(1'b0), .BREG(1'b0), .OUT0_REG(1'b0), .OUT1_REG(1'b0),
        .PIPE_REG(1'b0), .ASIGN_REG(1'b0), .BSIGN_REG(1'b0)
    ) MUL (
        .A({4'h0, in_a}), .B({4'h0, in_b}),
        .ASIGN(1'b0), .BSIGN(1'b0),
        .CE(1'b1), .CLK(clk), .RESET(rst),
        .DOUT(dsp_product)
    );

    assign data_out  = out_buffer;
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            out_buffer  <= 32'h0;
            valid_out_r <= 1'b0;
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            valid_out_r <= 1'b0;
        end else begin
            out_buffer  <= dsp_product[31:0];
            valid_out_r <= armed && valid_in;
        end
    end

endmodule

// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// mul_cell_v4s_dsp3.v -- points.md #902: the time-multiplexed DSP mul, per Alan's
// own real proposal -- trade latency for DSP footprint so MORE logical mul cells
// can fit on the chip at once, each owning a small MULT18X18 slot instead of a
// whole MULT36X36 tile.
//
// Refinement made before building, not after: since this whole family already
// truncates every multiply to its low 32 bits (matching mul_cell_v4/v4c/v4s's
// own existing convention), the A_high*B_high partial product is UNNECESSARY --
// it only ever affects bits 32-63 of the real 64-bit product, which this
// convention discards regardless (verified by exhaustive random check against
// the real product before trusting it, not assumed). So this needs three
// MULT18X18 uses, not four, plus a real 4th state that captures the pipeline's
// first genuinely fresh operands -- see the state list below.
//
// A real off-by-one-cycle bug found and fixed while building this (not assumed
// correct): DOUT is purely combinational for this primitive's chosen
// configuration (AREG=BREG=OUT_REG=0), so each partial product must be
// registered in the SAME cycle its operands are presented to the multiplier --
// an earlier draft tried to capture it one cycle late, using a_hold/b_hold
// before their own capture had taken effect, silently multiplying the WRONG
// (stale) operands. Fixed by registering each partial product in the same case
// branch that sets up the next state's operands, and folding the final partial
// product straight into the sum on its own cycle rather than needing a separate
// sum-only state.
//
// Real states (4 cycles total, matching Alan's own original framing exactly):
//   ST_LOAD: capture fresh in_a/in_b into a_hold/b_hold. Nothing useful to
//            register from the multiplier yet -- a_hold/b_hold aren't valid
//            until NEXT cycle (this is exactly the timing subtlety the bug
//            above was caused by getting wrong).
//   ST_LL:   a_hold/b_hold now valid. mult_a/mult_b = a_low/b_low. Real product
//            registered into pp_ll THIS cycle (DOUT is combinational).
//   ST_LH:   mult_a/mult_b = a_low/b_high. Real product registered into pp_lh.
//   ST_HL:   mult_a/mult_b = a_high/b_low. This cycle's real product is used
//            DIRECTLY (combinationally, same cycle) together with the already-
//            registered pp_ll/pp_lh to compute the final sum, registered into
//            out_buffer -- no separate sum-only state needed.
//
// Real, fixed, known 4-cycle LATENCY -- exactly the kind of number the family's
// still-unbuilt latency-matching work needs, no different in kind from any other
// cell's fixed one-cycle latency, just a bigger fixed number.
//
// A real, honest THROUGHPUT constraint that must be stated plainly, not
// discovered the hard way: this cell can only START a new operation once every
// 4 cycles (the state machine only captures a fresh in_a/in_b during ST_LOAD). A
// `valid_in` pulse presented during the other 3 cycles of an in-flight operation
// is genuinely, silently missed -- not an error, not corruption, simply not
// sampled. Upstream logic driving this cell must only assert `valid_in` once
// every 4 cycles, aligned to this cell's own free-running state counter (or
// accept that faster requests will be dropped). Tested explicitly: the real
// testbench checks the aligned back-to-back case and the off-boundary-miss case
// directly, not just in comment form.
`default_nettype none
`timescale 1ns / 1ps

module mul_cell_v4s_dsp3 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,   // unused; kept for a uniform port shape

    input  wire [31:0]  in_a,
    input  wire [31:0]  in_b,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        armed       = 1'b0;
    reg [31:0] out_buffer  = 32'h0;
    reg        valid_out_r = 1'b0;

    localparam [1:0] ST_LOAD = 2'd0, ST_LL = 2'd1, ST_LH = 2'd2, ST_HL = 2'd3;
    reg [1:0] state = ST_LOAD;

    reg [31:0] a_hold = 32'h0, b_hold = 32'h0;
    reg [31:0] pp_ll  = 32'h0, pp_lh  = 32'h0;
    reg [3:0]  valid_pipe = 4'h0;   // one bit per cycle of the fixed 4-cycle latency

    wire [15:0] a_low  = a_hold[15:0];
    wire [15:0] a_high = a_hold[31:16];
    wire [15:0] b_low  = b_hold[15:0];
    wire [15:0] b_high = b_hold[31:16];

    // The ONE real shared MULT18X18 -- selected operands per state. ST_LOAD's
    // operands are genuinely don't-care (a_hold/b_hold aren't valid yet, and
    // nothing registers this state's dsp_out).
    reg [17:0] mult_a, mult_b;
    always @(*) begin
        case (state)
            ST_LL:   begin mult_a = {2'h0, a_low};  mult_b = {2'h0, b_low};  end
            ST_LH:   begin mult_a = {2'h0, a_low};  mult_b = {2'h0, b_high}; end
            ST_HL:   begin mult_a = {2'h0, a_high}; mult_b = {2'h0, b_low};  end
            default: begin mult_a = 18'h0;          mult_b = 18'h0;         end
        endcase
    end

    wire [35:0] dsp_out;
    MULT18X18 MUL (
        .A(mult_a), .SIA(18'h0), .B(mult_b), .SIB(18'h0),
        .ASIGN(1'b0), .BSIGN(1'b0), .ASEL(1'b0), .BSEL(1'b0),
        .CE(1'b1), .CLK(clk), .RESET(rst),
        .DOUT(dsp_out), .SOA(), .SOB()
    );

    // Only bits [15:0] of pp_lh (and of this cycle's own HL product) land inside
    // the kept low-32-bit output at all -- verified by exhaustive random check
    // against the real product before trusting it (bit k of a shifted-by-16
    // partial product lands at output bit k+16; k=16..31 would land at output
    // bits 32..47, which the 32-bit truncation discards).
    wire [33:0] sum34 = {2'h0, pp_ll} + {2'h0, pp_lh[15:0], 16'h0} + {2'h0, dsp_out[15:0], 16'h0};

    assign data_out  = out_buffer;
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            out_buffer  <= 32'h0;
            valid_out_r <= 1'b0;
            state       <= ST_LOAD;
            a_hold      <= 32'h0;
            b_hold      <= 32'h0;
            pp_ll       <= 32'h0;
            pp_lh       <= 32'h0;
            valid_pipe  <= 4'h0;
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            valid_out_r <= 1'b0;
            state       <= ST_LOAD;
            valid_pipe  <= 4'h0;
        end else begin
            // Free-running 4-state cycle -- unconditional, exactly like every
            // other v4s cell's fixed-latency register, just spread over more
            // stages.
            case (state)
                ST_LOAD: begin
                    a_hold <= in_a; b_hold <= in_b;
                    state  <= ST_LL;
                end
                ST_LL: begin
                    pp_ll <= dsp_out[31:0];   // real A_low * B_low, THIS cycle's operands
                    state <= ST_LH;
                end
                ST_LH: begin
                    pp_lh <= dsp_out[31:0];   // real A_low * B_high, THIS cycle's operands
                    state <= ST_HL;
                end
                ST_HL: begin
                    // This cycle's own real product (A_high * B_low) is used
                    // directly, combinationally, together with the already-
                    // registered pp_ll/pp_lh -- no separate sum state needed.
                    out_buffer <= sum34[31:0];
                    state      <= ST_LOAD;
                end
            endcase

            valid_pipe  <= {valid_pipe[2:0], armed && valid_in};
            valid_out_r <= valid_pipe[2];
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// mul_cell_v4sa.v -- points.md #916: the Flex-Sub shape (ack+freeze per #906,
// WIDTH per #909/#910) applied to the LUT-built ("actual mul core itself",
// per Alan's own framing) multiply -- the no-DSP-dependency alternative to
// mul_cell_v4sa_dsp.v, kept deliberately separate, not a replacement for it.
//
// A real, deliberate choice made here, not inherited silently:
// `bitwise_multiplier_32bit.v` (mul_cell_v4/v4c/v4s's own real multiplier) is
// hardcoded for exactly 32-bit operands and is SHARED with the mainline
// cardinal-routed cells -- not something to modify for this family's own
// purposes. Rather than touch a shared file (the same caution mask_cell_v4sa.v
// already applied to nibble_mask_addon_v1.v), this uses a plain, genuinely
// WIDTH-generic `in_a * in_b`. #901 already confirmed directly that this
// toolchain's synth_gowin pass never infers DSP blocks from a plain multiply
// -- it synthesises to ordinary LUT logic, functionally equivalent to the
// array multiplier's own real purpose (a no-DSP-dependency fallback), even
// though it is not gate-for-gate identical in structure to the original.
`default_nettype none
`timescale 1ns / 1ps

module mul_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        SECOND_PORT = 0,   // 1 = build the data_out_hi port's logic (#976); 0 = port exists but is silent and costs nothing
    parameter        WIDTH   = 32
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,   // bit 0 = hi_enable (also produce the HIGH word on data_out_hi)

    input  wire [WIDTH-1:0]  in_a,
    input  wire [WIDTH-1:0]  in_b,
    input  wire               valid_in,
    output wire                ack_out,     // backward, to whoever feeds in_a/in_b

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in,      // backward, from the one fixed downstream receiver

    // SECOND OUTPUT PORT (Alan's ruling, 2026-10-06: two results = two ports, as branch does):
    // the HIGH word of the 2*WIDTH product, own valid/ack, independent of data_out's. Only
    // produced when cfg_data[0] (hi_enable) is set; clear, the port is silent and the cell is
    // exactly as before, so leaving these three ports unconnected is safe.
    output wire [WIDTH-1:0]  data_out_hi,
    output wire               valid_out_hi,
    input  wire               ack_in_hi
);

    reg             armed       = 1'b0;
    reg             pending     = 1'b0;
    reg             hi_enable   = 1'b0;
    reg             pending_hi  = 1'b0;
    reg [WIDTH-1:0] hi_buffer   = {WIDTH{1'b0}};
    reg [WIDTH-1:0] out_buffer  = {WIDTH{1'b0}};

    // ── The real arithmetic -- a plain, genuinely width-generic multiply,
    // not the shared, fixed-32-bit bitwise_multiplier_32bit.v primitive ────
    wire [2*WIDTH-1:0] full_product = in_a * in_b;

    assign data_out  = out_buffer;
    assign valid_out = pending;
    assign data_out_hi  = hi_buffer;
    assign valid_out_hi = pending_hi;
    // a new round needs BOTH outputs consumed (same rule as branch_cell_v4sa)
    assign ack_out   = armed && !pending && !pending_hi && !freeze_in;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            pending     <= 1'b0;
            hi_enable   <= 1'b0;
            pending_hi  <= 1'b0;
            hi_buffer   <= {WIDTH{1'b0}};
            out_buffer  <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            hi_enable   <= (SECOND_PORT != 0) && cfg_data[0];
            pending     <= 1'b0;
            pending_hi  <= 1'b0;
        end else if (!freeze_in) begin
            if (pending || pending_hi) begin
                if (pending    && ack_in)    pending    <= 1'b0;
                if (pending_hi && ack_in_hi) pending_hi <= 1'b0;
            end else if (valid_in) begin
                hi_buffer  <= (SECOND_PORT != 0) ? full_product[2*WIDTH-1:WIDTH] : {WIDTH{1'b0}};
                pending_hi <= hi_enable;
                out_buffer <= full_product[WIDTH-1:0];
                pending    <= 1'b1;
            end
        end
    end

endmodule

// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// mul_cell_v4sa_dsp.v -- points.md #916: the Flex-Sub shape (ack+freeze per
// #906, WIDTH per #909/#910) applied to the real DSP-based multiply from
// #901. Per Alan's own direction: mul should let a deployment specify EITHER
// the on-board DSP logic (this file) OR the actual LUT-built mul core itself
// (mul_cell_v4s.v's own bitwise_multiplier_32bit, not yet Flex-Sub'd) -- both
// stay available, this is not a replacement for the other.
//
// A real constraint specific to this DSP-based variant, worth stating
// plainly: WIDTH must be <= 36 here, a genuine hardware ceiling -- MULT36X36
// is a FIXED-size primitive, not something that gets cheaper or more
// expensive as WIDTH narrows the way LUT-built logic does. Operands below 36
// bits are zero-extended into the DSP block; the block itself costs the same
// either way. At this card's own real native width (18), the fit is
// genuinely exact -- MULT18X18 would need no padding at all -- but this file
// keeps using MULT36X36 generically (the same real primitive #901 proved
// working end to end) so one file covers every width up to 36 without
// needing per-width primitive selection logic.
`default_nettype none
`timescale 1ns / 1ps

module mul_cell_v4sa_dsp #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        SECOND_PORT = 0,   // 1 = build the data_out_hi port's logic (#976); 0 = port exists but is silent and costs nothing
    parameter        WIDTH   = 32   // real ceiling for this variant: WIDTH <= 36
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,   // bit 0 = hi_enable (also produce the HIGH word on data_out_hi)

    input  wire [WIDTH-1:0]  in_a,
    input  wire [WIDTH-1:0]  in_b,
    input  wire               valid_in,
    output wire                ack_out,     // backward, to whoever feeds in_a/in_b

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in,      // backward, from the one fixed downstream receiver

    // SECOND OUTPUT PORT (Alan's ruling, 2026-10-06: two results = two ports, as branch does):
    // the HIGH word of the 2*WIDTH product, own valid/ack, independent of data_out's. Only
    // produced when cfg_data[0] (hi_enable) is set; clear, the port is silent and the cell is
    // exactly as before, so leaving these three ports unconnected is safe.
    output wire [WIDTH-1:0]  data_out_hi,
    output wire               valid_out_hi,
    input  wire               ack_in_hi
);

    reg             armed       = 1'b0;
    reg             pending     = 1'b0;
    reg             hi_enable   = 1'b0;
    reg             pending_hi  = 1'b0;
    reg [WIDTH-1:0] hi_buffer   = {WIDTH{1'b0}};
    reg [WIDTH-1:0] out_buffer  = {WIDTH{1'b0}};

    // ── The real DSP block, instantiated directly, unchanged from #901 ───
    wire [71:0] dsp_product;
    MULT36X36 #(
        .AREG(1'b0), .BREG(1'b0), .OUT0_REG(1'b0), .OUT1_REG(1'b0),
        .PIPE_REG(1'b0), .ASIGN_REG(1'b0), .BSIGN_REG(1'b0)
    ) MUL (
        .A({{(36-WIDTH){1'b0}}, in_a}), .B({{(36-WIDTH){1'b0}}, in_b}),
        .ASIGN(1'b0), .BSIGN(1'b0),
        .CE(1'b1), .CLK(clk), .RESET(rst),
        .DOUT(dsp_product)
    );

    assign data_out  = out_buffer;
    assign valid_out = pending;
    assign data_out_hi  = hi_buffer;
    assign valid_out_hi = pending_hi;
    // a new round needs BOTH outputs consumed (same rule as branch_cell_v4sa)
    assign ack_out   = armed && !pending && !pending_hi && !freeze_in;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            pending     <= 1'b0;
            hi_enable   <= 1'b0;
            pending_hi  <= 1'b0;
            hi_buffer   <= {WIDTH{1'b0}};
            out_buffer  <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            hi_enable   <= (SECOND_PORT != 0) && cfg_data[0];
            pending     <= 1'b0;
            pending_hi  <= 1'b0;
        end else if (!freeze_in) begin
            if (pending || pending_hi) begin
                if (pending    && ack_in)    pending    <= 1'b0;
                if (pending_hi && ack_in_hi) pending_hi <= 1'b0;
            end else if (valid_in) begin
                hi_buffer  <= (SECOND_PORT != 0) ? dsp_product[2*WIDTH-1:WIDTH] : {WIDTH{1'b0}};
                pending_hi <= hi_enable;
                out_buffer <= dsp_product[WIDTH-1:0];
                pending    <= 1'b1;
            end
        end
    end

endmodule

