    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,
    output wire         status_data_valid
);
    reg [31:0] out_buffer      = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg [1:0]  mode            = 2'd2;
    reg        rr              = 1'b0;      // arbitrate: 1 = B wins a same-cycle tie
    reg [31:0] a_hold = 32'h0, b_hold = 32'h0;
    reg        a_have = 1'b0, b_have = 1'b0;
    reg [3:0]  pending_ack     = 4'h0;
    reg        armed           = 1'b0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ---- the two faces: A = lowest set upstream bit (N,S,E,W order), B = the next ----
    wire [3:0] um   = upstream_mask[3:0];
    wire [3:0] a_oh = um & (~um + 4'd1);
    wire [3:0] um2  = um & ~a_oh;
    wire [3:0] b_oh = um2 & (~um2 + 4'd1);
    wire [3:0] arr  = {arrived_w, arrived_e, arrived_s, arrived_n};
    wire arr_a = |(arr & a_oh);
    wire arr_b = |(arr & b_oh);
    wire [31:0] val_a = (a_oh[0] ? data_in_n : 32'h0) | (a_oh[1] ? data_in_s : 32'h0) | (a_oh[2] ? data_in_e : 32'h0) | (a_oh[3] ? data_in_w : 32'h0);
    wire [31:0] val_b = (b_oh[0] ? data_in_n : 32'h0) | (b_oh[1] ? data_in_s : 32'h0) | (b_oh[2] ? data_in_e : 32'h0) | (b_oh[3] ? data_in_w : 32'h0);

    wire free = !data_valid && !effective_freeze && effective_armed && !program_in;
    wire m_a = (mode == 2'd0), m_b = (mode == 2'd1), m_arb = (mode == 2'd2), m_or = (mode == 2'd3);

    wire grant_a = free && (m_a ? arr_a : (m_arb ? (arr_a && (!arr_b || !rr)) : 1'b0));
    wire grant_b = free && (m_b ? arr_b : (m_arb ? (arr_b && !grant_a)        : 1'b0));
    wire take_a  = free && m_or && arr_a && !a_have;
    wire take_b  = free && m_or && arr_b && !b_have;
    wire join_done = m_or && (a_have || take_a) && (b_have || take_b);
    wire [31:0] join_a = a_have ? a_hold : val_a;
    wire [31:0] join_b = b_have ? b_hold : val_b;

    wire acc_a = grant_a || take_a;
    wire acc_b = grant_b || take_b;
    assign ack_out_n = (acc_a && a_oh[0]) || (acc_b && b_oh[0]);
    assign ack_out_s = (acc_a && a_oh[1]) || (acc_b && b_oh[1]);
    assign ack_out_e = (acc_a && a_oh[2]) || (acc_b && b_oh[2]);
    assign ack_out_w = (acc_a && a_oh[3]) || (acc_b && b_oh[3]);

    // ---- offering the result: the carrier's fire / ack handshake, as every single-shot core ----
    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) && (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) && (!downstream_mask[3] || ready_in_w);
    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire             ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0) ? (pending_ack & ~ack_in_vec) : pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);
    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];
    assign data_out_n = out_buffer;
    assign data_out_s = out_buffer;
    assign data_out_e = out_buffer;
    assign data_out_w = out_buffer;
    assign ready_out = effective_armed && !effective_freeze && !data_valid;
    assign status_data_valid = data_valid;

    // ---- targeted programming ----
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd0;
    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd1;
    localparam [2:0] PROG_ID_MODE            = 3'd2;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;
    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n : prog_sel_s ? prog_data_in_s : prog_sel_e ? prog_data_in_e : prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];
    wire programming_active = program_in && active && prog_any_arrived;
    reg  program_done_r = 1'b0;
    assign program_done = program_done_r;
    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            out_buffer <= 32'h0; data_valid <= 1'b0; downstream_mask <= 6'h0; upstream_mask <= 6'h0; mode <= 2'd2; rr <= 1'b0;
            a_hold <= 32'h0; b_hold <= 32'h0; a_have <= 1'b0; b_have <= 1'b0; pending_ack <= 4'h0; armed <= 1'b0; program_done_r <= 1'b0;
        end else if (cfg_valid) begin
            downstream_mask <= cfg_data[5:0];
            upstream_mask   <= cfg_data[11:6];
            mode            <= cfg_data[13:12];
            rr <= 1'b0; a_have <= 1'b0; b_have <= 1'b0; data_valid <= 1'b0; pending_ack <= 4'h0; armed <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_MODE:            mode            <= prog_word[1:0];
                PROG_ID_COMPLETE: begin program_done_r <= 1'b1; armed <= prog_word[0]; end
                default: ;
            endcase
        end else begin
            if (m_or) begin
                if (take_a) begin a_hold <= val_a; a_have <= 1'b1; end
                if (take_b) begin b_hold <= val_b; b_have <= 1'b1; end
                if (join_done) begin
                    out_buffer <= join_a | join_b;
                    data_valid <= 1'b1;
                    a_have <= 1'b0; b_have <= 1'b0;
                end
            end else if (grant_a || grant_b) begin
                out_buffer <= grant_a ? val_a : val_b;
                data_valid <= 1'b1;
                if (m_arb) rr <= grant_a;
            end
            if (offer_draining) data_valid <= 1'b0;
            pending_ack <= next_pending_ack;
            if (!program_in) program_done_r <= 1'b0;
        end
    end
endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design -- see LICENSE-HARDWARE and NOTICE
//
// merge_cell_v4sa.v -- the MERGE core for the Flex (handshake) family (Alan, after ledger #954).
//
// WHY A CORE AND NOT GLUE. In the original architecture every cell can take several upstream faces: a merge is a property of the cell. The flex cells
// (v4sa) each have ONE input, so a merge needs a place to live. A first version put selection logic ("an arbiter") in the generator's emitted glue and it
// worked (the whole cordic ran), but Alan's ruling is that the system is built from KNOWN, verified core designs and that arbitrary hand-woven glue at
// particular points goes against the idea of it. So the merge is a core, with its own bench, like every other cell.
//
// WHAT THE VM DOES, AND WHY A PLAIN OR IS WRONG HERE. The VM ORs arrivals in the same tick. Under a handshake two sources can BOTH stay valid for as long
// as a cell is busy; a plain OR would then consume both and FUSE two separate items into one corrupt value. So the merge has explicit, selectable modes:
//
//   cfg_data[1:0] = mode
//     0  A only      pass in_a; in_b is never accepted (a one-path "merge": a configurable pass-through)
//     1  B only      pass in_b; in_a is never accepted
//     2  ARBITRATE   either source, one at a time: grant one, acknowledge ONLY that one, rotate priority after every grant (round-robin: neither can
//                    starve). Right when the two paths are alternatives (a branch's two outcomes rejoining -- the cordic's `gather`).
//     3  JOIN-OR     WAIT for BOTH sources, then output in_a | in_b and acknowledge both together. Right when the two paths are halves of ONE item to be
//                    combined -- the "free OR" used as a feature -- made deterministic: it no longer depends on the two items happening to arrive in the
//                    same cycle.
//
// PROTOCOL (the family's, read from adder_cell_v4sa.v / ram_cell_v4sa.v): a cell captures at an edge where it is not `pending`; the result is registered
// (out_buffer) and `valid_out = pending` is held until `ack_in` is high at an edge. An input's `ack_out_*` is the cell's READY for that input, so a transfer
// is an edge where `valid_in_*` and `ack_out_*` are both high. Like every v4sa cell: one item per two cycles, `freeze_in` gates everything, configuration
// arms the cell and clears its state. Hence ONE cycle of added latency and storage, exactly like a relay.
//
// ORDER. No cell can restore the order of items between two paths (that needs per-item tags). A merge is only well-defined when at most one item is in
// flight in the region it joins (true of the loop-style designs that use merges; the compiler never emits one). Mode 3 does not have the problem: it
// takes one item from each side per output.
`default_nettype none
`timescale 1ns / 1ps

module merge_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              freeze_in,
    input  wire              cfg_valid,
    input  wire [31:0]       cfg_data,      // [1:0] = mode (see above)
    input  wire [WIDTH-1:0]  in_a,
    input  wire              valid_in_a,
    output wire              ack_out_a,     // ready for A
    input  wire [WIDTH-1:0]  in_b,
    input  wire              valid_in_b,
    output wire              ack_out_b,     // ready for B
    output wire [WIDTH-1:0]  data_out,
    output wire              valid_out,
    input  wire              ack_in
);
    reg [1:0]       mode       = 2'd2;
    reg             armed      = 1'b0;
    reg             pending    = 1'b0;
    reg             rr         = 1'b0;      // arbitrate: 1 = B has priority when both are valid
    reg [WIDTH-1:0] out_buffer = {WIDTH{1'b0}};

    wire ready = armed && !pending && !freeze_in;
    wire m_a   = (mode == 2'd0);
    wire m_b   = (mode == 2'd1);
    wire m_arb = (mode == 2'd2);
    wire m_or  = (mode == 2'd3);

    // who is granted this cycle (modes 0-2); mode 3 takes both
    wire g_a = m_a ? valid_in_a : (m_arb ? (valid_in_a && (!valid_in_b || !rr)) : 1'b0);
    wire g_b = m_b ? valid_in_b : (m_arb ? (valid_in_b && !g_a)                  : 1'b0);
    wire take = m_or ? (valid_in_a && valid_in_b) : (g_a || g_b);
    wire [WIDTH-1:0] val = m_or ? (in_a | in_b) : (g_a ? in_a : in_b);

    // ready levels: a transfer happens only for the source(s) actually taken
    assign ack_out_a = ready && (m_or ? valid_in_b : g_a);
    assign ack_out_b = ready && (m_or ? valid_in_a : g_b);

    assign data_out  = out_buffer;
    assign valid_out = pending;

    always @(posedge clk) begin
        if (rst) begin
            mode       <= 2'd2;
            armed      <= 1'b0;
            pending    <= 1'b0;
            rr         <= 1'b0;
            out_buffer <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            mode       <= cfg_data[1:0];
            armed      <= 1'b1;
            pending    <= 1'b0;
            rr         <= 1'b0;
            out_buffer <= {WIDTH{1'b0}};
        end else if (!freeze_in) begin
            if (pending) begin
                if (ack_in) pending <= 1'b0;
            end else if (ready && take) begin
                out_buffer <= val;
                pending    <= 1'b1;
                if (m_arb) rr <= g_a;       // the loser gets priority next time
            end
        end
    end
endmodule

v4.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// priority_cell_v4.v — points.md #730: the 11th unified-carrier core,
// the real priority arbiter (#707, resolved #727). Genuinely different
// in SHAPE from every other core so far: not a two-operand combine
// (add/mul) needing two-stage capture, and not a single-operand
// transform (compare) — this core's own real job is deciding WHICH of
// several simultaneously-arrived real inputs gets captured first,
// using a real, configurable per-direction priority rank rather than
// the OR-combine every other core's own upstream_val already uses.
//
// Real, resolved design (#727), used directly, not re-derived:
//   - Uses the SAME real upstream_mask/downstream_mask convention
//     every other core already has — no fixed, asymmetric port roles.
//   - Priority order is a real, per-direction CONFIGURABLE rank
//     (2 bits each), not a hardcoded value — a fixed priority would
//     force every design using this core into one specific physical
//     layout.
//   - The real output side has no priority semantics attached at all
//     — a normal downstream_mask, exactly like every other core.
//   - Real, documented (not hardware-enforced) expectation: at least
//     TWO real input directions should be enabled via upstream_mask,
//     or there's genuinely no point using this core over a plain
//     relay.
//
// Real, second refinement (2026-09-08): strict priority alone
// genuinely starves lower-ranked ports under sustained load from the
// top-ranked one — not a corner case, the expected behavior of any
// fixed-priority scheme. A real, second scheduling mode added, not a
// replacement: `scheduling_mode` selects strict priority (0, the
// original design, rank 0=highest/3=lowest) or weighted round-robin
// (1, the SAME rank fields reinterpreted as relative WEIGHTS, 0=
// lowest possible weight). Real, honest mechanism: a genuine credit
// accumulator per direction (the same real technique real network
// schedulers use) -- every real arbitration decision, every OTHER
// candidate's own credit gains its own configured weight, and the
// winner's own credit resets to 0. This produces a real, proportional
// interleaving (roughly A,A,A,B,A,A,A,B for a real 3:1 weight ratio),
// not an exact, pre-specified sequence -- a genuinely different,
// bigger core would be needed for that.
//
// Real, honest scope for the arbitration logic itself: both modes
// share ONE real comparator structure over a unified per-direction
// "score" (strict mode: `3 - rank`, so lower rank gives a higher
// score; RR mode: the real, live credit value) — ties broken by the
// same fixed, real N>S>E>W order in both modes. Single-stage capture
// (data_reg/data_valid only) — genuinely simpler than add/mul's own
// two-stage a_reg/a_arrived shape, since there is no second operand to
// wait for at all; the "other" operand here is a competing ARRIVAL,
// not a value to combine with.
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   upstream_mask     — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  downstream_mask   — one-hot(s), N/S/E/W real + 2 reserved
//   [13:12] priority_rank_n   — strict mode: 0=highest,3=lowest.
//   [15:14] priority_rank_s     RR mode: relative weight, 0=lowest
//   [17:16] priority_rank_e     possible weight.
//   [19:18] priority_rank_w
//   [20]    scheduling_mode   — 0=strict priority, 1=weighted RR
//   [40:21] addon_config      — 20 bits, SAME real layout as every
//                               other _v4 core's own addon chain
//                               (shifted 1 bit for scheduling_mode)
//   [63:41] reserved
`default_nettype none
`timescale 1ns / 1ps

module priority_cell_v4 #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid,
    output wire  [1:0]  status_winning_dir   // 2'b00=N 01=S 10=E 11=W, real diagnostic only
);

    reg [31:0] data_reg        = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [1:0]  priority_rank_n = 2'h0;
    reg [1:0]  priority_rank_s = 2'h0;
    reg [1:0]  priority_rank_e = 2'h0;
    reg [1:0]  priority_rank_w = 2'h0;
    reg        scheduling_mode = 1'b0;
    reg [19:0] addon_config    = 20'h0;
    reg [3:0]  pending_ack     = 4'h0;
    reg        armed           = 1'b0;
    reg [1:0]  winning_dir_reg = 2'h0;

    // ── points.md #730 (2nd refinement): real, live credit state for
    // weighted round-robin mode -- internal scheduler state only, NOT
    // part of cfg_data, not directly user-visible. Unused (stays at 0)
    // in strict-priority mode. ──
    reg [7:0]  credit_n = 8'h0;
    reg [7:0]  credit_s = 8'h0;
    reg [7:0]  credit_e = 8'h0;
    reg [7:0]  credit_w = 8'h0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ── Real, genuine priority encoder — the one thing that's new
    // here. A direction is a real candidate only if it's BOTH enabled
    // (upstream_mask) AND has real, arrived data waiting right now.
    // Both scheduling modes share ONE comparator structure over a
    // unified per-direction "score" (points.md #730's own 2nd
    // refinement): strict mode uses `3 - rank` (so a lower configured
    // rank gives a HIGHER score, preserving "0 = highest priority"
    // exactly); RR mode uses the real, live credit value directly.
    // Ties (equal score) broken by a fixed N>S>E>W order in both
    // modes, unchanged from the original design. ──
    wire cand_n = arrived_n && upstream_mask[0];
    wire cand_s = arrived_s && upstream_mask[1];
    wire cand_e = arrived_e && upstream_mask[2];
    wire cand_w = arrived_w && upstream_mask[3];

    // ── points.md #730 (2nd refinement, corrected): the real, proven
    // "Surplus Round Robin" shape -- EVERY real candidate's credit
    // gains its own weight EVERY cycle it competes (win or lose), and
    // ONLY the winner's own credit is then reduced, by the TOTAL
    // weight of every candidate that round (clamped at 0, never
    // negative). An earlier draft incremented only the LOSER's own
    // credit and reset the winner to 0 -- confirmed by direct
      // simulation to produce strict alternation regardless of the
    // configured weight ratio (a real, wrong result, caught before
    // committing to it), since a big winning margin always fully
    // reset rather than carrying its own real surplus forward. ──
    wire [7:0] credit_n_inc = cand_n ? (credit_n + {6'h0, priority_rank_n}) : credit_n;
    wire [7:0] credit_s_inc = cand_s ? (credit_s + {6'h0, priority_rank_s}) : credit_s;
    wire [7:0] credit_e_inc = cand_e ? (credit_e + {6'h0, priority_rank_e}) : credit_e;
    wire [7:0] credit_w_inc = cand_w ? (credit_w + {6'h0, priority_rank_w}) : credit_w;
    wire [7:0] total_weight = (cand_n ? {6'h0, priority_rank_n} : 8'h0) +
                              (cand_s ? {6'h0, priority_rank_s} : 8'h0) +
                              (cand_e ? {6'h0, priority_rank_e} : 8'h0) +
                              (cand_w ? {6'h0, priority_rank_w} : 8'h0);

    wire [7:0] score_n = scheduling_mode ? credit_n_inc : {6'h0, (2'd3 - priority_rank_n)};
    wire [7:0] score_s = scheduling_mode ? credit_s_inc : {6'h0, (2'd3 - priority_rank_s)};
    wire [7:0] score_e = scheduling_mode ? credit_e_inc : {6'h0, (2'd3 - priority_rank_e)};
    wire [7:0] score_w = scheduling_mode ? credit_w_inc : {6'h0, (2'd3 - priority_rank_w)};

    wire n_beats_s = !cand_s || (score_n >= score_s);
    wire n_beats_e = !cand_e || (score_n >= score_e);
    wire n_beats_w = !cand_w || (score_n >= score_w);
    wire win_n = cand_n && n_beats_s && n_beats_e && n_beats_w;

    wire s_beats_e = !cand_e || (score_s >= score_e);
    wire s_beats_w = !cand_w || (score_s >= score_w);
    wire win_s = cand_s && !win_n && s_beats_e && s_beats_w;

    wire e_beats_w = !cand_w || (score_e >= score_w);
    wire win_e = cand_e && !win_n && !win_s && e_beats_w;

    wire win_w = cand_w && !win_n && !win_s && !win_e;

    wire any_win = win_n | win_s | win_e | win_w;
    wire [31:0] winning_val = (win_n ? data_in_n : 32'h0) |
                              (win_s ? data_in_s : 32'h0) |
                              (win_e ? data_in_e : 32'h0) |
                              (win_w ? data_in_w : 32'h0);

    // ── Real, single-stage capture — no second operand to wait for. ──
    wire capture_now = any_win && !data_valid && !effective_freeze &&
                       effective_armed && !program_in;

    assign ack_out_n = capture_now && win_n;
    assign ack_out_s = capture_now && win_s;
    assign ack_out_e = capture_now && win_e;
    assign ack_out_w = capture_now && win_w;

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #617's own real, three-addon chain, wired exactly
    // as every other _v4 core's own -- same order, same 20-bit
    // addon_config layout, reused verbatim. ──
    wire [31:0] after_mask, after_shiftlane, addon_out;
    nibble_mask_addon_v1 ADDON_NM (
        .mask_en(addon_config[8]), .nibble_mask(addon_config[7:0]),
        .data_in(data_reg), .data_out(after_mask)
    );
    shift_lane_addon_v1 ADDON_SL (
        .direction(addon_config[15]), .shift_en(addon_config[14]),
        .shift_amt(addon_config[13:9]), .lane_cut(addon_config[18:16]),
        .data_in(after_mask), .data_out(after_shiftlane)
    );
    invert_addon_v1 ADDON_INV (
        .invert_en(addon_config[19]),
        .data_in(after_shiftlane), .data_out(addon_out)
    );

    assign data_out_n = addon_out;
    assign data_out_s = addon_out;
    assign data_out_e = addon_out;
    assign data_out_w = addon_out;

    assign ready_out = effective_armed && !effective_freeze && !data_valid;
    assign status_data_valid   = data_valid;
    assign status_winning_dir  = winning_dir_reg;

    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd0;
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd1;
    localparam [2:0] PROG_ID_PRIORITY_RANKS  = 3'd2;   // {sched_mode,rank_w,rank_e,rank_s,rank_n}, 9 bits
    localparam [2:0] PROG_ID_ADDON_CONFIG    = 3'd3;
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            data_reg        <= 32'h0;
            data_valid      <= 1'b0;
            upstream_mask   <= 6'h0;
            downstream_mask <= 6'h0;
            priority_rank_n <= 2'h0;
            priority_rank_s <= 2'h0;
            priority_rank_e <= 2'h0;
            priority_rank_w <= 2'h0;
            scheduling_mode <= 1'b0;
            addon_config    <= 20'h0;
            credit_n        <= 8'h0;
            credit_s        <= 8'h0;
            credit_e        <= 8'h0;
            credit_w        <= 8'h0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
            winning_dir_reg <= 2'h0;
        end else if (cfg_valid) begin
            upstream_mask   <= cfg_data[5:0];
            downstream_mask <= cfg_data[11:6];
            priority_rank_n <= cfg_data[13:12];
            priority_rank_s <= cfg_data[15:14];
            priority_rank_e <= cfg_data[17:16];
            priority_rank_w <= cfg_data[19:18];
            scheduling_mode <= cfg_data[20];
            addon_config    <= cfg_data[40:21];
            credit_n        <= 8'h0;
            credit_s        <= 8'h0;
            credit_e        <= 8'h0;
            credit_w        <= 8'h0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_PRIORITY_RANKS: begin
                    priority_rank_n <= prog_word[1:0];
                    priority_rank_s <= prog_word[3:2];
                    priority_rank_e <= prog_word[5:4];
                    priority_rank_w <= prog_word[7:6];
                    scheduling_mode <= prog_word[8];
                    credit_n <= 8'h0;
                    credit_s <= 8'h0;
                    credit_e <= 8'h0;
                    credit_w <= 8'h0;
                end
                PROG_ID_ADDON_CONFIG:    addon_config    <= prog_word[19:0];
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_now) begin
                data_reg        <= winning_val;
                data_valid      <= 1'b1;
                winning_dir_reg <= win_n ? 2'b00 : win_s ? 2'b01 : win_e ? 2'b10 : 2'b11;

                // ── points.md #730 (2nd refinement): real credit
                // update, RR mode only -- every OTHER real candidate
                // that lost this round gains its own configured
                // weight; the winner's own credit resets to 0. Stays
                // at 0 (never accumulates) in strict mode, matching
                // the original design exactly when scheduling_mode=0.
                // ── points.md #730 (2nd refinement, corrected): real
                // Surplus Round Robin update -- every candidate's
                // credit already gained its own weight this cycle
                // (credit_*_inc, computed combinationally above); only
                // the real winner's own credit is now reduced by the
                // real total weight, clamped at 0 rather than
                // underflowing. Non-winning candidates simply keep
                // their own incremented value.
                if (scheduling_mode) begin
                    credit_n <= win_n ? ((credit_n_inc > total_weight) ? (credit_n_inc - total_weight) : 8'h0) : credit_n_inc;
                    credit_s <= win_s ? ((credit_s_inc > total_weight) ? (credit_s_inc - total_weight) : 8'h0) : credit_s_inc;
                    credit_e <= win_e ? ((credit_e_inc > total_weight) ? (credit_e_inc - total_weight) : 8'h0) : credit_e_inc;
                    credit_w <= win_w ? ((credit_w_inc > total_weight) ? (credit_w_inc - total_weight) : 8'h0) : credit_w_inc;
                end
            end

            if (offer_draining) begin
                data_valid <= 1'b0;
            end
            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4c.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// priority_cell_v4c.v — points.md #730: the "c" (carrier) variant of
// priority_cell_v4.v, built alongside it (matching mul's own #724
// precedent -- when both variants are built in the same pass, no
// retrofit is needed). Same real reasoning as every other _v4c file's
// own header: the carrier's whole design concept is to hold common
// functionality centrally, and this core's own internal 3-addon chain
// duplicates exactly what the carrier itself now provides once,
// shared. priority_cell_v4.v itself is UNCHANGED, still the real,
// proven, standalone core -- including its own real strict-priority
// AND weighted-round-robin scheduling modes, both fully preserved
// here unchanged; only the addon chain and config-off-shell source
// differ between the two files.
//
// Real, honest scope of this file's own changes from v4:
//   1. The internal addon chain is REMOVED entirely -- data_out_n/s/
//      e/w now come directly from data_reg, the real captured value.
//   2. addon_config (20 bits) is removed from cfg_data's own field
//      map, the register, and PROG_ID_ADDON_CONFIG. cfg_data KEEPS
//      its original 64-bit width; PROG_ID_COMPLETE stays at 3'd7,
//      addon_config's own old slot (3'd3) is simply unused now.
//   3. Same real config-off-shell reasoning as every other _v4c file
//      (confirmed correct the hard way in #723): this core's own real
//      config fields STAY registers, fed from the carrier's own
//      combinational incoming_config (the value about to be
//      committed), NOT the registered core_config.
//
// cfg_data[63:0] field map (atomic boot-load path):
//   [5:0]   upstream_mask     — one-hot(s), N/S/E/W real + 2 reserved
//   [11:6]  downstream_mask   — one-hot(s), N/S/E/W real + 2 reserved
//   [13:12] priority_rank_n   — strict mode: 0=highest,3=lowest. RR
//   [15:14] priority_rank_s     mode: relative weight, 0=lowest
//   [17:16] priority_rank_e     possible weight.
//   [19:18] priority_rank_w
//   [20]    scheduling_mode   — 0=strict priority, 1=weighted RR
//   [63:21] reserved          — 43 bits (addon_config's own old home,
//                               now genuinely free, plus the original
//                               23 bits of headroom)

`default_nettype none
`timescale 1ns / 1ps

module priority_cell_v4c #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         active,

    input  wire         cfg_valid,
    input  wire [63:0]  cfg_data,

    input  wire [31:0]  data_in_n,   data_in_s,   data_in_e,   data_in_w,
    input  wire         arrived_n,   arrived_s,   arrived_e,   arrived_w,

    output wire [31:0]  data_out_n,  data_out_s,  data_out_e,  data_out_w,
    output wire         fire_n,      fire_s,      fire_e,      fire_w,

    output wire         ready_out,
    input  wire         ready_in_n,  ready_in_s,  ready_in_e,  ready_in_w,

    output wire         ack_out_n,   ack_out_s,   ack_out_e,   ack_out_w,
    input  wire         ack_in_n,    ack_in_s,    ack_in_e,    ack_in_w,

    input  wire         program_in,
    output wire         program_done,
    input  wire [31:0]  prog_data_in_n,  prog_data_in_s,  prog_data_in_e,  prog_data_in_w,
    input  wire          prog_arrived_in_n, prog_arrived_in_s, prog_arrived_in_e, prog_arrived_in_w,
    output wire          prog_ack_out_n,    prog_ack_out_s,    prog_ack_out_e,    prog_ack_out_w,

    input  wire         freeze_in,

    output wire         status_data_valid,
    output wire  [1:0]  status_winning_dir   // 2'b00=N 01=S 10=E 11=W, real diagnostic only
);

    reg [31:0] data_reg        = 32'h0;
    reg        data_valid      = 1'b0;
    reg [5:0]  upstream_mask   = 6'h0;
    reg [5:0]  downstream_mask = 6'h0;
    reg [1:0]  priority_rank_n = 2'h0;
    reg [1:0]  priority_rank_s = 2'h0;
    reg [1:0]  priority_rank_e = 2'h0;
    reg [1:0]  priority_rank_w = 2'h0;
    reg        scheduling_mode = 1'b0;
    reg [3:0]  pending_ack     = 4'h0;
    reg        armed           = 1'b0;
    reg [1:0]  winning_dir_reg = 2'h0;

    // ── points.md #730 (2nd refinement): real, live credit state for
    // weighted round-robin mode -- internal scheduler state only, NOT
    // part of cfg_data, not directly user-visible. Unused (stays at 0)
    // in strict-priority mode. ──
    reg [7:0]  credit_n = 8'h0;
    reg [7:0]  credit_s = 8'h0;
    reg [7:0]  credit_e = 8'h0;
    reg [7:0]  credit_w = 8'h0;

    wire effective_freeze = freeze_in;
    wire effective_armed  = armed && active;

    // ── Real, genuine priority encoder — the one thing that's new
    // here. A direction is a real candidate only if it's BOTH enabled
    // (upstream_mask) AND has real, arrived data waiting right now.
    // Both scheduling modes share ONE comparator structure over a
    // unified per-direction "score" (points.md #730's own 2nd
    // refinement): strict mode uses `3 - rank` (so a lower configured
    // rank gives a HIGHER score, preserving "0 = highest priority"
    // exactly); RR mode uses the real, live credit value directly.
    // Ties (equal score) broken by a fixed N>S>E>W order in both
    // modes, unchanged from the original design. ──
    wire cand_n = arrived_n && upstream_mask[0];
    wire cand_s = arrived_s && upstream_mask[1];
    wire cand_e = arrived_e && upstream_mask[2];
    wire cand_w = arrived_w && upstream_mask[3];

    // ── points.md #730 (2nd refinement, corrected): the real, proven
    // "Surplus Round Robin" shape -- EVERY real candidate's credit
    // gains its own weight EVERY cycle it competes (win or lose), and
    // ONLY the winner's own credit is then reduced, by the TOTAL
    // weight of every candidate that round (clamped at 0, never
    // negative). An earlier draft incremented only the LOSER's own
    // credit and reset the winner to 0 -- confirmed by direct
      // simulation to produce strict alternation regardless of the
    // configured weight ratio (a real, wrong result, caught before
    // committing to it), since a big winning margin always fully
    // reset rather than carrying its own real surplus forward. ──
    wire [7:0] credit_n_inc = cand_n ? (credit_n + {6'h0, priority_rank_n}) : credit_n;
    wire [7:0] credit_s_inc = cand_s ? (credit_s + {6'h0, priority_rank_s}) : credit_s;
    wire [7:0] credit_e_inc = cand_e ? (credit_e + {6'h0, priority_rank_e}) : credit_e;
    wire [7:0] credit_w_inc = cand_w ? (credit_w + {6'h0, priority_rank_w}) : credit_w;
    wire [7:0] total_weight = (cand_n ? {6'h0, priority_rank_n} : 8'h0) +
                              (cand_s ? {6'h0, priority_rank_s} : 8'h0) +
                              (cand_e ? {6'h0, priority_rank_e} : 8'h0) +
                              (cand_w ? {6'h0, priority_rank_w} : 8'h0);

    wire [7:0] score_n = scheduling_mode ? credit_n_inc : {6'h0, (2'd3 - priority_rank_n)};
    wire [7:0] score_s = scheduling_mode ? credit_s_inc : {6'h0, (2'd3 - priority_rank_s)};
    wire [7:0] score_e = scheduling_mode ? credit_e_inc : {6'h0, (2'd3 - priority_rank_e)};
    wire [7:0] score_w = scheduling_mode ? credit_w_inc : {6'h0, (2'd3 - priority_rank_w)};

    wire n_beats_s = !cand_s || (score_n >= score_s);
    wire n_beats_e = !cand_e || (score_n >= score_e);
    wire n_beats_w = !cand_w || (score_n >= score_w);
    wire win_n = cand_n && n_beats_s && n_beats_e && n_beats_w;

    wire s_beats_e = !cand_e || (score_s >= score_e);
    wire s_beats_w = !cand_w || (score_s >= score_w);
    wire win_s = cand_s && !win_n && s_beats_e && s_beats_w;

    wire e_beats_w = !cand_w || (score_e >= score_w);
    wire win_e = cand_e && !win_n && !win_s && e_beats_w;

    wire win_w = cand_w && !win_n && !win_s && !win_e;

    wire any_win = win_n | win_s | win_e | win_w;
    wire [31:0] winning_val = (win_n ? data_in_n : 32'h0) |
                              (win_s ? data_in_s : 32'h0) |
                              (win_e ? data_in_e : 32'h0) |
                              (win_w ? data_in_w : 32'h0);

    // ── Real, single-stage capture — no second operand to wait for. ──
    wire capture_now = any_win && !data_valid && !effective_freeze &&
                       effective_armed && !program_in;

    assign ack_out_n = capture_now && win_n;
    assign ack_out_s = capture_now && win_s;
    assign ack_out_e = capture_now && win_e;
    assign ack_out_w = capture_now && win_w;

    wire want_to_offer = data_valid && !effective_freeze && effective_armed;
    wire targets_all_ready = (!downstream_mask[0] || ready_in_n) &&
                             (!downstream_mask[1] || ready_in_s) &&
                             (!downstream_mask[2] || ready_in_e) &&
                             (!downstream_mask[3] || ready_in_w);

    wire [3:0] ack_in_vec = {ack_in_w, ack_in_e, ack_in_s, ack_in_n};
    wire any_fire = want_to_offer && (pending_ack == 4'h0) && targets_all_ready;
    wire [3:0] next_pending_ack = any_fire              ? (downstream_mask[3:0] & ~ack_in_vec) :
                                  (pending_ack != 4'h0)  ? (pending_ack     & ~ack_in_vec) :
                                                           pending_ack;
    wire offer_draining = (pending_ack != 4'h0) && (next_pending_ack == 4'h0);

    assign fire_n = pending_ack[0];
    assign fire_s = pending_ack[1];
    assign fire_e = pending_ack[2];
    assign fire_w = pending_ack[3];

    // ── points.md #730: NO addon chain here at all — the carrier
    // already provides one, shared across whichever core is active. ──
    assign data_out_n = data_reg;
    assign data_out_s = data_reg;
    assign data_out_e = data_reg;
    assign data_out_w = data_reg;

    assign ready_out = effective_armed && !effective_freeze && !data_valid;
    assign status_data_valid   = data_valid;
    assign status_winning_dir  = winning_dir_reg;

    localparam [2:0] PROG_ID_UPSTREAM_MASK   = 3'd0;
    localparam [2:0] PROG_ID_DOWNSTREAM_MASK = 3'd1;
    localparam [2:0] PROG_ID_PRIORITY_RANKS  = 3'd2;   // {sched_mode,rank_w,rank_e,rank_s,rank_n}, 9 bits
    localparam [2:0] PROG_ID_COMPLETE        = 3'd7;

    wire prog_any_arrived = prog_arrived_in_n | prog_arrived_in_s | prog_arrived_in_e | prog_arrived_in_w;
    wire prog_sel_n = prog_arrived_in_n;
    wire prog_sel_s = prog_arrived_in_s && !prog_arrived_in_n;
    wire prog_sel_e = prog_arrived_in_e && !prog_arrived_in_n && !prog_arrived_in_s;
    wire prog_sel_w = prog_arrived_in_w && !prog_arrived_in_n && !prog_arrived_in_s && !prog_arrived_in_e;
    wire [31:0] prog_data_val = prog_sel_n ? prog_data_in_n :
                                prog_sel_s ? prog_data_in_s :
                                prog_sel_e ? prog_data_in_e :
                                             prog_data_in_w;
    wire [2:0]  prog_id   = prog_data_val[22:20];
    wire [19:0] prog_word = prog_data_val[19:0];

    wire programming_active = program_in && active && prog_any_arrived;
    assign program_done = program_done_r;
    reg   program_done_r = 1'b0;

    assign prog_ack_out_n = programming_active && prog_sel_n;
    assign prog_ack_out_s = programming_active && prog_sel_s;
    assign prog_ack_out_e = programming_active && prog_sel_e;
    assign prog_ack_out_w = programming_active && prog_sel_w;

    always @(posedge clk) begin
        if (rst) begin
            data_reg        <= 32'h0;
            data_valid      <= 1'b0;
            upstream_mask   <= 6'h0;
            downstream_mask <= 6'h0;
            priority_rank_n <= 2'h0;
            priority_rank_s <= 2'h0;
            priority_rank_e <= 2'h0;
            priority_rank_w <= 2'h0;
            scheduling_mode <= 1'b0;
            credit_n        <= 8'h0;
            credit_s        <= 8'h0;
            credit_e        <= 8'h0;
            credit_w        <= 8'h0;
            pending_ack     <= 4'h0;
            armed           <= 1'b0;
            program_done_r  <= 1'b0;
            winning_dir_reg <= 2'h0;
        end else if (cfg_valid) begin
            upstream_mask   <= cfg_data[5:0];
            downstream_mask <= cfg_data[11:6];
            priority_rank_n <= cfg_data[13:12];
            priority_rank_s <= cfg_data[15:14];
            priority_rank_e <= cfg_data[17:16];
            priority_rank_w <= cfg_data[19:18];
            scheduling_mode <= cfg_data[20];
            credit_n        <= 8'h0;
            credit_s        <= 8'h0;
            credit_e        <= 8'h0;
            credit_w        <= 8'h0;
            data_valid      <= 1'b0;
            pending_ack     <= 4'h0;
            armed           <= 1'b1;
        end else if (programming_active) begin
            case (prog_id)
                PROG_ID_UPSTREAM_MASK:   upstream_mask   <= prog_word[5:0];
                PROG_ID_DOWNSTREAM_MASK: downstream_mask <= prog_word[5:0];
                PROG_ID_PRIORITY_RANKS: begin
                    priority_rank_n <= prog_word[1:0];
                    priority_rank_s <= prog_word[3:2];
                    priority_rank_e <= prog_word[5:4];
                    priority_rank_w <= prog_word[7:6];
                    scheduling_mode <= prog_word[8];
                    credit_n <= 8'h0;
                    credit_s <= 8'h0;
                    credit_e <= 8'h0;
                    credit_w <= 8'h0;
                end
                PROG_ID_COMPLETE: begin
                    program_done_r <= 1'b1;
                    armed          <= prog_word[0];
                end
                default: ;
            endcase
        end else begin
            if (capture_now) begin
                data_reg        <= winning_val;
                data_valid      <= 1'b1;
                winning_dir_reg <= win_n ? 2'b00 : win_s ? 2'b01 : win_e ? 2'b10 : 2'b11;

                // ── points.md #730 (2nd refinement): real credit
                // update, RR mode only -- every OTHER real candidate
                // that lost this round gains its own configured
                // weight; the winner's own credit resets to 0. Stays
                // at 0 (never accumulates) in strict mode, matching
                // the original design exactly when scheduling_mode=0.
                // ── points.md #730 (2nd refinement, corrected): real
                // Surplus Round Robin update -- every candidate's
                // credit already gained its own weight this cycle
                // (credit_*_inc, computed combinationally above); only
                // the real winner's own credit is now reduced by the
                // real total weight, clamped at 0 rather than
                // underflowing. Non-winning candidates simply keep
                // their own incremented value.
                if (scheduling_mode) begin
                    credit_n <= win_n ? ((credit_n_inc > total_weight) ? (credit_n_inc - total_weight) : 8'h0) : credit_n_inc;
                    credit_s <= win_s ? ((credit_s_inc > total_weight) ? (credit_s_inc - total_weight) : 8'h0) : credit_s_inc;
                    credit_e <= win_e ? ((credit_e_inc > total_weight) ? (credit_e_inc - total_weight) : 8'h0) : credit_e_inc;
                    credit_w <= win_w ? ((credit_w_inc > total_weight) ? (credit_w_inc - total_weight) : 8'h0) : credit_w_inc;
                end
            end

            if (offer_draining) begin
                data_valid <= 1'b0;
            end
            pending_ack <= next_pending_ack;

            if (!program_in) program_done_r <= 1'b0;
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design -- see LICENSE-HARDWARE and NOTICE
//
// priority_cell_v4sa.v -- ledger #1017: the PRIORITY core on the flex family (valid/ready ack, global freeze, WIDTH), the last of the cores to be ported across.
// The behaviour is priority_cell_v4c.v's (fpga/verilog), unchanged, in the family's handshake protocol:
//
//   FOUR inputs, one per face (n, s, e, w), each with its own data / valid / ready. ONE output (data_out / valid_out / ack_in); the generator's eager fork delivers it to every consumer.
//   A face is a CANDIDATE when its valid is high AND its bit in `upstream_mask` is set (a connected face that the configuration masks off never wins, exactly as in the VM).
//   Exactly ONE candidate is granted per item and ONLY that source is acknowledged; the losers' items stay where they are, waiting, and nobody is blocked by them.
//
//   scheduling_mode 0  STRICT    the candidate with the lowest rank wins ("0 = highest priority"); score = 3 - rank.
//   scheduling_mode 1  WEIGHTED  SURPLUS ROUND ROBIN: every candidate's credit gains its own weight (= its rank field, 0 = lowest weight, 3 = highest) on every round it competes, win or lose;
//                                the highest credit wins; ONLY the winner's credit is then reduced, by the total weight of all candidates that round (clamped at 0).
//   scheduling_mode 2  SEQUENCED CHANNEL (ledger #1018, Alan's #772)  a fixed, cyclic TURN ORDER (up to four turns, each a face; a face may appear more than once). ONLY the face whose turn it is
//                                is ever a candidate; every other arrival waits, however early, however long the due face takes (head-of-line blocking, by design). The turn advances when the due face's
//                                word is taken, and wraps. An empty order never captures. The cell, not the wiring, guarantees the order.
//   Ties (equal score) are broken by the fixed order N > S > E > W in modes 0 and 1.
//
// cfg_data (32 bits):  [3:0] upstream_mask (n = bit 0, s = 1, e = 2, w = 3)   [5:4] rank_n  [7:6] rank_s  [9:8] rank_e  [11:10] rank_w   [12] weighted (mode 1)
//                      [13] sequenced (mode 2, wins over [12])   [16:14] sequence_len (0..4)   [18:17] turn 0  [20:19] turn 1  [22:21] turn 2  [24:23] turn 3  (face codes 0 n, 1 s, 2 e, 3 w)
//   (the downstream mask of the v4c cell is not here: a consumer is wiring, the generator forks the one output.)
//
// PROTOCOL (the family's, read from merge_cell_v4sa.v): the cell captures at an edge where it is not `pending`; the winner's word is registered (out_buffer) and `valid_out = pending` is held until
// `ack_in` is high at an edge. An input's `ack_out_*` is the cell's READY for THAT input, high only for the granted face, so a transfer is an edge where `valid_in_*` and `ack_out_*` are both high.
// One item per two cycles, `freeze_in` gates everything, configuration arms the cell and clears its state (credits included). One cycle of added latency and storage, like a relay.
`default_nettype none
`timescale 1ns / 1ps

module priority_cell_v4sa #(
    parameter [15:0] CELL_ID = 16'h0000,
    parameter        WIDTH   = 32
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              freeze_in,
    input  wire              cfg_valid,
    input  wire [31:0]       cfg_data,
    input  wire [WIDTH-1:0]  in_n,
    input  wire              valid_in_n,
    output wire              ack_out_n,
    input  wire [WIDTH-1:0]  in_s,
    input  wire              valid_in_s,
    output wire              ack_out_s,
    input  wire [WIDTH-1:0]  in_e,
    input  wire              valid_in_e,
    output wire              ack_out_e,
    input  wire [WIDTH-1:0]  in_w,
    input  wire              valid_in_w,
    output wire              ack_out_w,
    output wire [WIDTH-1:0]  data_out,
    output wire              valid_out,
    input  wire              ack_in
);
    reg [3:0]       upstream_mask   = 4'h0;
    reg [1:0]       rank_n = 2'h0, rank_s = 2'h0, rank_e = 2'h0, rank_w = 2'h0;
    reg             scheduling_mode = 1'b0;
    reg             sequenced       = 1'b0;
    reg [2:0]       seq_len         = 3'h0;
    reg [7:0]       seq_order       = 8'h00;
    reg [2:0]       seq_idx         = 3'h0;
    reg [7:0]       credit_n = 8'h0, credit_s = 8'h0, credit_e = 8'h0, credit_w = 8'h0;
    reg             armed      = 1'b0;
    reg             pending    = 1'b0;
    reg [WIDTH-1:0] out_buffer = {WIDTH{1'b0}};

    wire ready = armed && !pending && !freeze_in && !seq_cap;

    // sequenced channel: the face whose turn it is (a turn index past the end, or an empty order, selects nothing)
    wire [1:0] due_face = seq_order[{seq_idx[1:0], 1'b0} +: 2];
    wire       due_ok   = sequenced && (seq_len != 3'h0);
    wire due_n = due_ok && due_face == 2'd0;
    wire due_s = due_ok && due_face == 2'd1;
    wire due_e = due_ok && due_face == 2'd2;
    wire due_w = due_ok && due_face == 2'd3;
    wire seq_cap = sequenced && !due_ok;                 // an empty order never captures

    // candidates: offered AND enabled (AND, in the sequenced mode, due)
    wire cand_n = valid_in_n && upstream_mask[0] && (!sequenced || due_n);
    wire cand_s = valid_in_s && upstream_mask[1] && (!sequenced || due_s);
    wire cand_e = valid_in_e && upstream_mask[2] && (!sequenced || due_e);
    wire cand_w = valid_in_w && upstream_mask[3] && (!sequenced || due_w);

    // surplus round robin: every candidate's credit gains its weight this round
    wire [7:0] inc_n = cand_n ? (credit_n + {6'h0, rank_n}) : credit_n;
    wire [7:0] inc_s = cand_s ? (credit_s + {6'h0, rank_s}) : credit_s;
    wire [7:0] inc_e = cand_e ? (credit_e + {6'h0, rank_e}) : credit_e;
    wire [7:0] inc_w = cand_w ? (credit_w + {6'h0, rank_w}) : credit_w;
    wire [7:0] total_weight = (cand_n ? {6'h0, rank_n} : 8'h0) + (cand_s ? {6'h0, rank_s} : 8'h0) +
                              (cand_e ? {6'h0, rank_e} : 8'h0) + (cand_w ? {6'h0, rank_w} : 8'h0);

    // one comparator structure for both modes: strict scores by (3 - rank), weighted by the credit
    wire [7:0] score_n = scheduling_mode ? inc_n : {6'h0, (2'd3 - rank_n)};
    wire [7:0] score_s = scheduling_mode ? inc_s : {6'h0, (2'd3 - rank_s)};
    wire [7:0] score_e = scheduling_mode ? inc_e : {6'h0, (2'd3 - rank_e)};
    wire [7:0] score_w = scheduling_mode ? inc_w : {6'h0, (2'd3 - rank_w)};

    // winner: highest score, ties N > S > E > W
    wire win_n = cand_n && (!cand_s || score_n >= score_s) && (!cand_e || score_n >= score_e) && (!cand_w || score_n >= score_w);
    wire win_s = cand_s && !win_n && (!cand_e || score_s >= score_e) && (!cand_w || score_s >= score_w);
    wire win_e = cand_e && !win_n && !win_s && (!cand_w || score_e >= score_w);
    wire win_w = cand_w && !win_n && !win_s && !win_e;
    wire any_win = win_n | win_s | win_e | win_w;

    wire [WIDTH-1:0] winning_val = (win_n ? in_n : {WIDTH{1'b0}}) | (win_s ? in_s : {WIDTH{1'b0}}) |
                                   (win_e ? in_e : {WIDTH{1'b0}}) | (win_w ? in_w : {WIDTH{1'b0}});

    // ready is raised ONLY for the granted face
    assign ack_out_n = ready && win_n;
    assign ack_out_s = ready && win_s;
    assign ack_out_e = ready && win_e;
    assign ack_out_w = ready && win_w;

    assign data_out  = out_buffer;
    assign valid_out = pending;

    always @(posedge clk) begin
        if (rst) begin
            upstream_mask <= 4'h0; scheduling_mode <= 1'b0; sequenced <= 1'b0; seq_len <= 3'h0; seq_order <= 8'h00; seq_idx <= 3'h0;
            rank_n <= 2'h0; rank_s <= 2'h0; rank_e <= 2'h0; rank_w <= 2'h0;
            credit_n <= 8'h0; credit_s <= 8'h0; credit_e <= 8'h0; credit_w <= 8'h0;
            armed <= 1'b0; pending <= 1'b0; out_buffer <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            upstream_mask   <= cfg_data[3:0];
            rank_n          <= cfg_data[5:4];
            rank_s          <= cfg_data[7:6];
            rank_e          <= cfg_data[9:8];
            rank_w          <= cfg_data[11:10];
            scheduling_mode <= cfg_data[12];
            sequenced       <= cfg_data[13];
            seq_len         <= cfg_data[16:14];
            seq_order       <= cfg_data[24:17];
            seq_idx         <= 3'h0;
            credit_n <= 8'h0; credit_s <= 8'h0; credit_e <= 8'h0; credit_w <= 8'h0;
            armed <= 1'b1; pending <= 1'b0; out_buffer <= {WIDTH{1'b0}};
        end else if (!freeze_in) begin
            if (pending) begin
                if (ack_in) pending <= 1'b0;
            end else if (ready && any_win) begin
                out_buffer <= winning_val;
                pending    <= 1'b1;
                if (sequenced) seq_idx <= (seq_idx + 3'h1 >= seq_len) ? 3'h0 : seq_idx + 3'h1;
                if (scheduling_mode && !sequenced) begin
                    credit_n <= win_n ? ((inc_n > total_weight) ? (inc_n - total_weight) : 8'h0) : inc_n;
                    credit_s <= win_s ? ((inc_s > total_weight) ? (inc_s - total_weight) : 8'h0) : inc_s;
                    credit_e <= win_e ? ((inc_e > total_weight) ? (inc_e - total_weight) : 8'h0) : inc_e;
                    credit_w <= win_w ? ((inc_w > total_weight) ? (inc_w - total_weight) : 8'h0) : inc_w;
                end
            end
        end
    end
endmodule

