                                {4{~nibble_mask[5]}}, {4{~nibble_mask[4]}},
                                {4{~nibble_mask[3]}}, {4{~nibble_mask[2]}},
                                {4{~nibble_mask[1]}}, {4{~nibble_mask[0]}}};

    assign data_out = mask_en ? (data_in & nibble_keep) : data_in;

endmodule

