// with no gaps, since no two adjacent taps are ever more than 4 apart.
//
// GENUINELY NOT a sparse/fixed-pattern shifter like its coarse
// sibling -- with only 4 real amounts (0-3), a full mux-based general
// shifter costs nothing worth optimizing away; there is no "unsupported
// amount" case here at all, unlike the coarse stage.
//
// Real, deliberate placement in the chain, not incidental: this
// addon's own `shift_amount` output feeds `shift_lane_addon_v2`
// directly (see that module's own header) -- `lane_cut`'s boundary-
// crossing math needs the TOTAL real shift (fine + coarse) to stay
// correct once a fine pre-shift is layered in front of it, or it
// computes the wrong window entirely. This module's own job is
// strictly the DATA shift; carrying the fine amount forward as a
// separate signal (not folding it silently into the data alone) is
// what makes that downstream math possible at all.
//
// Same real direction convention as shift_lane_addon_v1, unchanged:
//   direction  — 0=SHIFT_IN (left-shift, before the cell's own gate
//                work sees the data), 1=SHIFT_OUT (right-shift, after
//                the gate has already fired)
//   shift_en   — 1=apply this fine shift this cycle, 0=pass through
//                (shift_amount still forwarded downstream either way,
//                so shift_lane_addon_v2's own lane_cut math stays
//                correct even when this stage itself is a no-op)
//   shift_amount[1:0] — 0-3, every value real, no unsupported case
`default_nettype none
`timescale 1ns / 1ps

module shift_fine_addon_v1 (
    input  wire        direction,      // 0=SHIFT_IN(left), 1=SHIFT_OUT(right)
    input  wire        shift_en,
    input  wire [1:0]  shift_amount,
    input  wire [31:0] data_in,
    output wire [31:0] data_out,
    output wire [1:0]  shift_amount_out  // forwarded, unchanged, for
                                          // shift_lane_addon_v2's own
                                          // total-shift lane_cut math
);

    wire [31:0] shifted_left;
    assign shifted_left = !shift_en           ? data_in :
                          (shift_amount==2'd1) ? {data_in[30:0], 1'h0} :
                          (shift_amount==2'd2) ? {data_in[29:0], 2'h0} :
                          (shift_amount==2'd3) ? {data_in[28:0], 3'h0} :
                          data_in;   // shift_amount==0: identity, real, not special-cased above

    wire [31:0] shifted_right;
    assign shifted_right = !shift_en           ? data_in :
                           (shift_amount==2'd1) ? {1'h0, data_in[31:1]} :
                           (shift_amount==2'd2) ? {2'h0, data_in[31:2]} :
                           (shift_amount==2'd3) ? {3'h0, data_in[31:3]} :
                           data_in;

    assign data_out = direction ? shifted_right : shifted_left;
    // Real, deliberate: forwards the FINE shift that ACTUALLY happened,
    // not the raw config value -- when shift_en=0 this stage performed
    // no real shift at all, so the correct real contribution to
    // shift_lane_addon_v2's own total-shift lane_cut math is 0, not
    // whatever shift_amount happens to be configured to.
    assign shift_amount_out = shift_en ? shift_amount : 2'd0;

endmodule

v4s.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// shift_cell_v4s.v -- a NEW v4s cell type (not a stripped version of an existing
// core): the shift function, extracted from shift_lane_addon_v2.v (unchanged,
// reused directly, not re-derived) and given its own standalone cell shell, per
// Alan's own direct scope: "the routing, the shift and the mask" as the genuinely
// new pieces the v4s family needs, with everything else being stripped versions
// of existing cores. See sub/README.md for the family's full design.
//
// Same shape as adder_cell_v4s.v: one data_in, one data_out, one forward timing
// line, fixed one-cycle latency, boot-load-only config (no live reprogramming, no
// ack, no freeze -- see adder_cell_v4s.v's own header for why, unchanged here).
//
// cfg_data field map (12 bits used, matching shift_lane_addon_v2's own real ports
// exactly -- nothing renumbered, nothing reinterpreted):
//   [0]     direction      -- 0=SHIFT_IN(left), 1=SHIFT_OUT(right)
//   [1]     shift_en       -- 0=pass through unchanged, 1=apply the shift
//   [6:2]   shift_amt[4:0] -- one of the 9 real supported amounts (1,2,4,8,12,16,
//                             20,24,28); any other value is a deliberate no-op,
//                             matching shift_lane_addon_v2's own sparse table
//   [9:7]   lane_cut[2:0]  -- SHIFT_OUT direction only, unchanged semantics
//   [11:10] shift_fine_in[1:0] -- carried-through fine-shift correction; since
//                             this v4s cell has no upstream shift_fine_addon wired
//                             to it (that would itself need to be a separate v4s
//                             cell feeding this one), this is loaded as a FIXED
//                             config value, not a live signal from another stage.
//                             Leave at 0 unless a real upstream fine-shift stage
//                             is later chained before this one.
`default_nettype none
`timescale 1ns / 1ps

module shift_cell_v4s #(
    parameter [15:0] CELL_ID = 16'h0000
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,
    input  wire [31:0]  cfg_data,

    input  wire [31:0]  data_in,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        direction      = 1'b0;
    reg        shift_en       = 1'b0;
    reg  [4:0] shift_amt      = 5'h0;
    reg  [2:0] lane_cut       = 3'h0;
    reg  [1:0] shift_fine_in  = 2'h0;
    reg        armed          = 1'b0;
    reg [31:0] out_buffer     = 32'h0;
    reg        valid_out_r    = 1'b0;

    // ── The real shift logic -- unchanged from shift_lane_addon_v2 ──────
    wire [31:0] shift_result;
    shift_lane_addon_v2 SHIFT (
        .direction(direction), .shift_en(shift_en), .shift_amt(shift_amt),
        .lane_cut(lane_cut), .shift_fine_in(shift_fine_in),
        .data_in(data_in), .data_out(shift_result)
    );

    assign data_out  = out_buffer;
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            direction     <= 1'b0;
            shift_en      <= 1'b0;
            shift_amt     <= 5'h0;
            lane_cut      <= 3'h0;
            shift_fine_in <= 2'h0;
            armed         <= 1'b0;
            out_buffer    <= 32'h0;
            valid_out_r   <= 1'b0;
        end else if (cfg_valid) begin
            direction     <= cfg_data[0];
            shift_en      <= cfg_data[1];
            shift_amt     <= cfg_data[6:2];
            lane_cut      <= cfg_data[9:7];
            shift_fine_in <= cfg_data[11:10];
            armed         <= 1'b1;
            valid_out_r   <= 1'b0;
        end else begin
            out_buffer  <= shift_result;
            valid_out_r <= armed && valid_in;
        end
    end

endmodule

// shift_stage_v4s.v -- points.md #899 experiment: a shift amount FIXED AT BUILD
// TIME (a real Verilog parameter, not a runtime cfg_data field), per Alan's own
// idea (limit each cell to a small range, chain for larger totals) pushed to its
// logical extreme: if the amount is baked into the cell at synthesis time, there
// is nothing left to select at runtime, and the whole mux/compare tree that made
// shift_cell_v4s expensive (1,686 LUT4 for the coarse mux ALONE, measured) can be
// optimized away entirely. This is the same "physics, not control" principle
// applied one level deeper: not just no runtime ROUTING decision, no runtime
// FUNCTION-SELECTION decision either -- the topology of what this cell computes
// is fixed the moment it's built, not the moment it's configured.
//
// Chain several of these (each a different power-of-2 amount, or 0=passthrough)
// to compose any total shift, matching the shift_amt values the original sparse
// table already supported (1,2,4,8,12,16,20,24,28 all being achievable by
// combinations of 1/2/4/8/16, an exact classic log-depth barrel-shifter
// decomposition, not an approximation).
`default_nettype none
`timescale 1ns / 1ps

module shift_stage_v4s #(
    parameter [15:0] CELL_ID   = 16'h0000,
    parameter [4:0]  SHIFT_AMT = 5'd0,     // FIXED at build time: 0=passthrough, else the amount
    parameter        DIRECTION = 1'b0      // FIXED at build time: 0=left, 1=right
) (
    input  wire        clk,
    input  wire        rst,

    input  wire         cfg_valid,   // arms the cell; no function config left to load
    input  wire [31:0]  cfg_data,    // unused; kept for a uniform port shape

    input  wire [31:0]  data_in,
    input  wire         valid_in,

    output wire [31:0]  data_out,
    output wire         valid_out
);

    reg        armed       = 1'b0;
    reg [31:0] out_buffer  = 32'h0;
    reg        valid_out_r = 1'b0;

    // Build-time-fixed shift -- a real Verilog generate/parameter case, not a
    // runtime mux. Yosys sees SHIFT_AMT/DIRECTION as compile-time constants and
    // reduces this to plain wiring for whichever single case is actually chosen.
    wire [31:0] shifted = (SHIFT_AMT == 5'd0) ? data_in :
                          (DIRECTION == 1'b0) ? (data_in << SHIFT_AMT) :
                                                (data_in >> SHIFT_AMT);

    assign data_out  = out_buffer;
    assign valid_out = valid_out_r;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            out_buffer  <= 32'h0;
            valid_out_r <= 1'b0;
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            valid_out_r <= 1'b0;
        end else begin
            out_buffer  <= shifted;
            valid_out_r <= armed && valid_in;
        end
    end

endmodule

v4sa.source:
// SPDX-License-Identifier: CERN-OHL-P-2.0
// Copyright (c) 2026 Imago UniCell Project
// Hardware design — see LICENSE-HARDWARE and NOTICE
//
// shift_stage_v4sa.v -- points.md #916: the Flex-Sub shape (ack+freeze per
// #906, WIDTH per #909/#910) applied to shift_stage. Per Alan's own real
// point: the meaningful SHIFT_AMT range is directly tied to WIDTH, not a
// fixed 0-31 regardless of it -- the real range is 0 to WIDTH-1. An amount
// >= WIDTH is still well-defined Verilog behaviour (everything shifts out,
// the result is all zero), but it is not a USEFUL shift for that width, and
// the assembler-side work that will eventually choose SHIFT_AMT per target
// should respect WIDTH-1 as the real ceiling, not an arbitrary wider one.
//
// The shift logic itself needs no change beyond WIDTH being threaded through
// correctly: `data_in << SHIFT_AMT` / `>> SHIFT_AMT` on a WIDTH-bit value
// already shifts correctly WITHIN that width (bits shifted past either edge
// are genuinely lost, zeros fill in) -- the same real Verilog mechanism
// #909 already proved correct for width-generic arithmetic, applied here to
// a logical shift instead.
//
// Build-time-fixed SHIFT_AMT/DIRECTION, unchanged in spirit from
// shift_stage_v4s.v -- the whole reason this variant is cheap (#899: 26 LUT4
// vs the runtime-configurable shift_cell_v4s's 3,261) is that there is
// nothing left to select at runtime. Chain several of these to compose a
// larger total shift.
`default_nettype none
`timescale 1ns / 1ps

module shift_stage_v4sa #(
    parameter [15:0] CELL_ID   = 16'h0000,
    parameter        WIDTH     = 32,
    parameter        SHIFT_AMT = 0,       // real range: 0 to WIDTH-1 for a useful shift
    parameter        DIRECTION = 1'b0     // FIXED at build time: 0=left, 1=right
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        freeze_in,

    input  wire         cfg_valid,   // arms the cell; no function config left to load
    input  wire [31:0]  cfg_data,    // unused; kept for a uniform port shape

    input  wire [WIDTH-1:0]  data_in,
    input  wire               valid_in,
    output wire                ack_out,     // backward, to whoever feeds data_in

    output wire [WIDTH-1:0]  data_out,
    output wire               valid_out,   // stays high until ack_in, not a one-shot pulse
    input  wire               ack_in       // backward, from the one fixed downstream receiver
);

    reg             armed       = 1'b0;
    reg             pending     = 1'b0;
    reg [WIDTH-1:0] out_buffer  = {WIDTH{1'b0}};

    // Build-time-fixed shift -- a real Verilog parameter case, not a runtime
    // mux, now genuinely WIDTH-generic: the shift happens within exactly
    // WIDTH bits, same mechanism #909 proved correct for arithmetic.
    wire [WIDTH-1:0] shifted = (SHIFT_AMT == 0) ? data_in :
                               (DIRECTION == 1'b0) ? (data_in << SHIFT_AMT) :
                                                     (data_in >> SHIFT_AMT);

    assign data_out  = out_buffer;
    assign valid_out = pending;
    assign ack_out   = armed && !pending && !freeze_in;

    always @(posedge clk) begin
        if (rst) begin
            armed       <= 1'b0;
            pending     <= 1'b0;
            out_buffer  <= {WIDTH{1'b0}};
        end else if (cfg_valid) begin
            armed       <= 1'b1;
            pending     <= 1'b0;
        end else if (!freeze_in) begin
            if (pending) begin
                if (ack_in) pending <= 1'b0;
            end else if (valid_in) begin
                out_buffer <= shifted;
                pending    <= 1'b1;
            end
        end
    end

endmodule
